-- ==================== CONFIG SEED ====================
-- AMENDED IN pgCK (#48), same family as the ROLES block above: the retired
-- chain's base scripts seeded these rows and the flatten's function-set
-- parity proof could not see data rows, so every virgin install lost them.
-- Warm clusters masked it — config rows survive nothing, but the chain
-- re-seeded ON CONFLICT DO NOTHING on every install, so they were always
-- there. Without kernel_graph_id, ckp.load_kernel passes NULL into
-- pgrdf.parse_turtle (measured: 'argument 1 must not be null' on the s4
-- gate's fresh volume); without transition_map, ckp.transition gates against
-- nothing. core_graph_id is re-derived BY IRI at ckp.boot (P0-A0: never
-- assume an id from config) — the seed only covers the window before boot.
-- kernel_graph_id is an id-to-IRI BINDING instruction consumed by
-- load_kernel's add_graph(id, iri), the chain's proven fresh-install shape.
-- transition_map is the chain's FINAL widened form (0.4.2--0.4.3, DO UPDATE
-- then, DO NOTHING here so a governed refinement is never clobbered).
INSERT INTO ckp.config(k,v) VALUES
  ('core_graph_id','1'), ('kernel_graph_id','2')
ON CONFLICT (k) DO NOTHING;
INSERT INTO ckp.config(k,v) VALUES
  ('transition_map', '{"draft":["review"],"review":["approved","draft"],"approved":[],"planned":["in_progress","blocked"],"in_progress":["done","blocked","planned"],"blocked":["in_progress","planned"],"done":["in_progress"]}')
ON CONFLICT (k) DO NOTHING;

-- ==================== REGISTRY SEED ====================
-- AMENDED IN pgCK (#48), fourth member of the same family: the registry is
-- the SOLE routing authority (CI-B-1 — dispatch refuses any verb absent from
-- it with unknown_affordance, zero payload evaluation), and the chain seeded
-- pgCK's shipped verbs across its steps (0.3.0--0.3.1 core+reads,
-- 0.3.4--0.3.5 reach/transition/match/explain, 0.4.2--0.4.3 retire). The
-- flatten created the table EMPTY: table rows are invisible to function-set
-- parity, and every prior run re-seeded through the chain at CREATE
-- EXTENSION, masking it. Measured: s15's snapshot.board (canon
-- instance.snapshot) -> unknown_affordance on the flattened install.
-- Cumulative chain end-state; governed query/derived affordances stay
-- runtime-registered by their compilers, never seeded here.
INSERT INTO ckp.affordance_registry (kernel, verb, in_topic, plane) VALUES
  -- B4: the substrate's own integrity check. plane='instance' is the ROUTING
  -- truth (the registry's plane column selects the handler: 'query'/'derived' mean
  -- a compiled plan, 'instance' means the built-in CASE) — NOT the root's semantic
  -- plane, which the column conflates with routing. Recorded as a #56-adjacent finding.
  -- Registered here because it is a built-in (plpgsql), not a sealed SPARQL plan —
  -- and sealed as a ckp:Affordance on the bench so it is declared as well as
  -- dispatchable, rather than growing the gap B1 measured (pgCK#56).
  ('pgck','surface.check',       'input.kernel.pgck.action.surface.check',       'instance'),
  ('pgck','integrity.check',     'input.kernel.pgck.action.integrity.check',     'instance'),
  ('pgck','authority.mine',      'input.kernel.pgck.action.authority.mine',      'instance'),
  -- 0.4.51 — the checker surface. Seeded here so they are DISPATCHABLE, and
  -- sealed as ckp:Affordance through propose->vote->apply so they are DECLARED.
  -- Both halves, or this grows the #56 gap it exists to close.
  ('pgck','wave.signals',        'input.kernel.pgck.action.wave.signals',        'instance'),
  -- alias, one version (0.4.63) — see dispatch
  ('pgck','wave.oracle',         'input.kernel.pgck.action.wave.oracle',         'instance'),
  ('pgck','wave.project',        'input.kernel.pgck.action.wave.project',        'instance'),
  ('pgck','adoption.check',      'input.kernel.pgck.action.adoption.check',      'instance'),
  ('pgck','surface.typecheck',   'input.kernel.pgck.action.surface.typecheck',   'instance'),
  ('pgck','surface.unshaped',    'input.kernel.pgck.action.surface.unshaped',    'instance'),
  ('pgck','surface.declared',    'input.kernel.pgck.action.surface.declared',    'instance'),
  ('pgck','surface.grounding',   'input.kernel.pgck.action.surface.grounding',   'instance'),
  ('pgck','surface.explain',     'input.kernel.pgck.action.surface.explain',     'instance'),
  ('pgck','fleet.adoptions',     'input.kernel.pgck.action.fleet.adoptions',     'instance'),
  ('pgck','project.resolve',     'input.kernel.pgck.action.project.resolve',     'instance'),
  ('pgck','instance.create',      'input.kernel.pgck.action.instance.create',      'instance'),
  ('pgck','instance.update',      'input.kernel.pgck.action.instance.update',      'instance'),
  ('pgck','instance.link',        'input.kernel.pgck.action.instance.link',        'instance'),
  ('pgck','instance.query',       'input.kernel.pgck.action.instance.query',       'instance'),
  ('pgck','instance.get',         'input.kernel.pgck.action.instance.get',         'instance'),
  ('pgck','instance.verify',      'input.kernel.pgck.action.instance.verify',      'instance'),
  ('pgck','instance.snapshot',    'input.kernel.pgck.action.instance.snapshot',    'instance'),
  ('pgck','instance.provenance',  'input.kernel.pgck.action.instance.provenance',  'instance'),
  ('pgck','instance.validate',    'input.kernel.pgck.action.instance.validate',    'instance'),
  ('pgck','instance.reach',       'input.kernel.pgck.action.instance.reach',       'instance'),
  ('pgck','instance.transition',  'input.kernel.pgck.action.instance.transition',  'instance'),
  ('pgck','instance.retire',      'input.kernel.pgck.action.instance.retire',      'instance'),
  ('pgck','concept.match',        'input.kernel.pgck.action.concept.match',        'instance'),
  ('pgck','instance.explain',     'input.kernel.pgck.action.instance.explain',     'instance'),
  ('pgck','affordances',          'input.kernel.pgck.action.affordances',          'instance'),
  ('pgck','kernels.list',         'input.kernel.pgck.action.kernels.list',         'instance'),
  ('pgck','participant.join',     'input.kernel.pgck.action.participant.join',     'instance'),
  ('pgck','notify',               'input.kernel.pgck.action.notify',               'instance'),
  ('pgck','kernel.propose_change','input.kernel.pgck.action.kernel.propose_change','governance'),
  ('pgck','kernel.vote',          'input.kernel.pgck.action.kernel.vote',          'governance'),
