  ('pgck','kernel.germinate',     'input.kernel.pgck.action.kernel.germinate',     'instance')
ON CONFLICT (kernel, verb) DO NOTHING;

-- Fifth member (#48): the governed concept.match plan — the ONLY static
-- ckp.plans seed in the chain (0.4.12--0.4.13; everything else in ckp.plans
-- is compiled at governed apply time). $graph$/$term$ are bound by
-- ckp.concept_match at run time; the query text is the governed fact.
-- Chain semantics kept (DO UPDATE): every install re-asserted the epoch-1
-- plan text; governed recompiles land at higher epochs.
INSERT INTO ckp.plans(kernel, verb, epoch, plan)
VALUES ('pgck', 'concept.match', 1, jsonb_build_object(
  'kind', 'sparql',
  'params', jsonb_build_array('term'),
  'statement',
    'PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#> '
    || 'SELECT ?id ?label WHERE { GRAPH <$graph$> { ?id rdfs:label ?label . '
    || 'FILTER(CONTAINS(LCASE(STR(?label)), LCASE("$term$"))) } } ORDER BY ?label'))
ON CONFLICT (kernel, verb, epoch) DO UPDATE SET plan = EXCLUDED.plan, compiled_at = now();

-- ==================== ROUTINES (80) ====================

CREATE OR REPLACE PROCEDURE ckp._enforce_internal_floor()
 LANGUAGE plpgsql
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $procedure$
BEGIN
  -- Single idempotent statement set: applies to EVERY table/sequence currently in
  -- schema ckp (config + dictionary now; instances/ledger/proof/outbox after
  -- bootstrap; plans after CI-C-4). No PUBLIC; ck_substrate is the operating role.
  REVOKE ALL ON ALL TABLES    IN SCHEMA ckp FROM PUBLIC;
  REVOKE ALL ON ALL SEQUENCES IN SCHEMA ckp FROM PUBLIC;
  GRANT  ALL ON ALL TABLES    IN SCHEMA ckp TO ck_substrate;
  GRANT  ALL ON ALL SEQUENCES IN SCHEMA ckp TO ck_substrate;
  -- Schema USAGE for the operating roles (measured missing from zero,
  -- 2026-08-08): the ring-1 definer set runs as ck_substrate and resolves
  -- ckp.* by name, and the outbox drain connects as ck_drainer — without
  -- USAGE both die on a FRESH install ('permission denied for schema ckp')
  -- while every long-lived bench works, because its grants predate the
  -- completeness file. The completeness pass grants ckp USAGE to
  -- ck_participant only; these two were only ever granted by hand.
  GRANT  USAGE ON SCHEMA ckp TO ck_substrate;
  GRANT  USAGE ON SCHEMA ckp TO ck_drainer;
  -- PROCEDURES (measured 2026-08-10, B2): 'ALL FUNCTIONS' does not cover
  -- procedures, so boot/import_module/load_kernel/bootstrap_kernel kept
  -- default PUBLIC EXECUTE on every route — mitigated only accidentally by
  -- their pg_read_file superuser gate. Revoke PUBLIC (explicit role grants
  -- survive a PUBLIC revoke untouched); ck_substrate keeps EXECUTE.
  REVOKE ALL ON ALL PROCEDURES IN SCHEMA ckp FROM PUBLIC;
  REVOKE ALL ON ALL PROCEDURES IN SCHEMA ckp FROM ck_participant;
  GRANT  EXECUTE ON ALL PROCEDURES IN SCHEMA ckp TO ck_substrate;
END;
$procedure$
;

CREATE OR REPLACE PROCEDURE ckp.boot(IN p_core_ttl_path text DEFAULT '/ontology/v3.12/core.ttl'::text)
 LANGUAGE plpgsql
AS $procedure$
DECLARE v_core INT; v_ttl TEXT; v_shapes INT;
BEGIN
  PERFORM pgrdf.shmem_reset();
  -- P0-A0 (pgCK#23): resolve the core graph BY IRI and record the id it got.
  -- Never assume an id from config. Two paths bound graphs — one by explicit
  -- id from ckp.config, one by IRI with an auto-assigned id — and whichever ran
  -- first won the id. That left core_graph_id pointing at the kernel graph and
  -- boot raising 'graph_id 1 is bound to a different IRI' on every run, so the
  -- core ontology was never loaded and every ckp.validate(_, core) conformed
  -- trivially against an empty shapes graph.
  v_core := pgrdf.add_graph('urn:ckp:core');
  INSERT INTO ckp.config(k,v) VALUES ('core_graph_id', v_core::text)
    ON CONFLICT (k) DO UPDATE SET v = EXCLUDED.v;
  PERFORM pgrdf.clear_graph(v_core);
  v_ttl := pg_read_file(p_core_ttl_path);
  PERFORM pgrdf.parse_turtle(v_ttl, v_core, 'urn:ckp:core#');
  PERFORM pgrdf.materialize(v_core);
  -- Fail loudly. An empty core graph is not a runnable state: it makes the
  -- seal's own ledger/proof gate unreachable and every core constraint inert.
  SELECT count(*) INTO v_shapes FROM pgrdf.sparql(
    'PREFIX sh:<http://www.w3.org/ns/shacl#> SELECT ?s WHERE { GRAPH <urn:ckp:core> { ?s a sh:NodeShape } }');
  IF v_shapes = 0 THEN
    RAISE EXCEPTION 'ckp.boot: core ontology at % loaded 0 sh:NodeShape — refusing to run with an unenforced core', p_core_ttl_path;
  END IF;
  -- Ring repair (fresh install, measured 2026-08-08): the per-graph tables
  -- this boot just created belong to the CALLING superuser — boot cannot be a
  -- ck_substrate definer because pg_read_file is superuser-gated — while every
  -- internal that reads them (ckp._composed_shapes and the rest of the ring-1
  -- definer set) runs as ck_substrate. On a fresh install the completeness
  -- floor ran at CREATE EXTENSION, before these tables existed, so the first
  -- seal died inside pgrdf.copy_graph with `permission denied for table
  -- _pgrdf_quads_g1`. Re-assert the substrate floor over pgrdf exactly as the
  -- completeness pass states it, now covering the dynamically created tables.
  -- (The lasting fix is a grant at creation inside pgrdf.add_graph — filed
  -- against pgRDF; this covers every graph boot itself creates.)
  GRANT ALL ON ALL TABLES    IN SCHEMA pgrdf TO ck_substrate;
  GRANT ALL ON ALL SEQUENCES IN SCHEMA pgrdf TO ck_substrate;
  RAISE NOTICE 'ckp.boot: core graph % loaded from %, % NodeShapes', v_core, p_core_ttl_path, v_shapes;
END;
$procedure$
;

CREATE OR REPLACE PROCEDURE ckp.bootstrap_kernel()
 LANGUAGE plpgsql
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $procedure$
BEGIN
  CREATE TABLE IF NOT EXISTS ckp.instances (
    id TEXT PRIMARY KEY, body JSONB NOT NULL,
    meta JSONB NOT NULL DEFAULT '{}'::jsonb,
    ts_created TIMESTAMPTZ NOT NULL DEFAULT now(),
    ts_updated TIMESTAMPTZ NOT NULL DEFAULT now()
  );
  CREATE TABLE IF NOT EXISTS ckp.ledger (
    seq BIGSERIAL PRIMARY KEY, instance_id TEXT NOT NULL,
    body_sha256 TEXT NOT NULL, sig TEXT NOT NULL,
    prev_seq BIGINT, ts TIMESTAMPTZ NOT NULL DEFAULT now()
  );
  CREATE TABLE IF NOT EXISTS ckp.proof (
    id BIGSERIAL PRIMARY KEY, about TEXT NOT NULL,
    method TEXT NOT NULL, digest TEXT NOT NULL,
    verified_at TIMESTAMPTZ NOT NULL DEFAULT now()
  );
  CREATE TABLE IF NOT EXISTS ckp.outbox (
    seq           BIGSERIAL PRIMARY KEY,
    ledger_seq    BIGINT NOT NULL REFERENCES ckp.ledger(seq) ON DELETE CASCADE,
    subject       TEXT NOT NULL,
    payload       BYTEA NOT NULL,
    headers       JSONB NOT NULL DEFAULT '{}'::jsonb,
    attempt_count INTEGER NOT NULL DEFAULT 0,
    enqueued_at   TIMESTAMPTZ NOT NULL DEFAULT now()
  );
  CREATE INDEX IF NOT EXISTS ckp_outbox_seq_idx ON ckp.outbox(seq);
  -- 0.4.61 — the adoption pin ledger (ck-dev's defect: a module composed under a
  -- sourceDigest of sixty-four zeros; the pin was judged by AdoptionShape and
  -- consulted by NOTHING). The substrate cannot verify a FILE-BYTE digest from
  -- triples, so the honest split is: file verification belongs to the loader at
  -- the file door; the substrate pins the GRAPH's canonical digest at first
  -- composition and makes later drift DETECTABLE. Trust-on-first-sight, named.
  CREATE TABLE IF NOT EXISTS ckp.adoption_pins (
    graph_iri    TEXT PRIMARY KEY,
    graph_digest TEXT NOT NULL,
    pinned_at    TIMESTAMPTZ NOT NULL DEFAULT now()
  );
  -- 0.4.67: the structural plane joins the pin (reload-surviving digest +
  -- blank-node-immune counts). ADD COLUMN keeps pre-0.4.67 pins valid: their
  -- structural fields backfill at the next composition's re-pin or stay NULL,
  -- honestly reported as "pinned before the structural plane existed".
  ALTER TABLE ckp.adoption_pins ADD COLUMN IF NOT EXISTS structural_digest TEXT;
  ALTER TABLE ckp.adoption_pins ADD COLUMN IF NOT EXISTS nodeshapes INTEGER;
  ALTER TABLE ckp.adoption_pins ADD COLUMN IF NOT EXISTS properties INTEGER;
  ALTER TABLE ckp.adoption_pins ADD COLUMN IF NOT EXISTS asserted INTEGER;
  -- 0.4.65 — the obligation registry (§5b): governed proof-producers run at
  -- seal-exit. Registered only through add_proof_obligation (propose→vote→
  -- apply); consulted by ckp.seal via ckp._run_proof_obligations.
  CREATE TABLE IF NOT EXISTS ckp.proof_obligations (
    project     TEXT NOT NULL,
    obligation  TEXT NOT NULL,
    target_type TEXT NOT NULL,
    check_name  TEXT NOT NULL,
    added_epoch INTEGER,
    active      BOOLEAN NOT NULL DEFAULT true,
    ts_added    TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (project, obligation)
  );
  DROP TRIGGER IF EXISTS ckp_ledger_after_insert ON ckp.ledger;
  CREATE TRIGGER ckp_ledger_after_insert
    AFTER INSERT ON ckp.ledger
    FOR EACH ROW EXECUTE FUNCTION ckp.ledger_to_outbox();

  -- CI-A-4: floor the runtime-created tables (instances/ledger/proof/outbox).
  CALL ckp._enforce_internal_floor();

  -- 0.4.57 — RESET THE ENGINE'S TERM CACHE. An aborted seal (every negative
  -- control in the suite is one) can leave pgrdf's shmem term cache in a state
  -- where a quad STORES but SHACL cannot SEE it — measured here as an Edge
  -- candidate whose serialized created_at triple was present in the TTL and
  -- absent from the validator's view, refusing conformant work. The engine's
  -- own remedy is pgrdf.shmem_reset() after any aborted seal; this bootstrap
  -- is the per-file entry point of every test, so each file starts clean.
  -- Guarded: older engines without the function skip silently.
  IF to_regprocedure('pgrdf.shmem_reset()') IS NOT NULL THEN
    PERFORM pgrdf.shmem_reset();
  END IF;

  -- 0.4.64 — the dev/test bootstrap NAMES its service identity, per the refusal
  -- ruling: unattributed seals refuse, and the sanctioned operator path is an
  -- explicitly declared service identity. Session-scoped, constant (never a
  -- fresh uuid — one suite, one accountable name), and only a default: a test
  -- that sets its own requester overrides it, and a test that must exercise
  -- the refusal clears it. This procedure is superuser-only; a participant
  -- cannot reach it.
  PERFORM set_config('ckp.requester', 'svc:bench-bootstrap', false);
END;
$procedure$
;

CREATE OR REPLACE PROCEDURE ckp.import_module(IN p_module text, IN p_project text, IN p_root text DEFAULT '/ontology'::text)
 LANGUAGE plpgsql
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $procedure$
DECLARE
  -- EMPTY BY RULING. affordance/delegation/proof are declared by the v3.11 root
  -- itself; delivery/validate were cut; task/goal do not exist in v3.11 at all.
  v_known_modules text[] := ARRAY[]::text[];
  v_retired       text[] := ARRAY['affordance','delegation','proof','delivery','validate','task','goal'];
  v_core_ns text := 'https://conceptkernel.org/ontology/v3.11/core#';
  v_path text;
  v_iri  text := format('urn:ckp:%s/kernel/board', p_project);
  v_g    int;
  v_ttl  text;
  v_minted text;
BEGIN
  IF p_module = ANY (v_retired) THEN
    RAISE EXCEPTION E'ckp.import_module: module "%" is RETIRED, not missing.\n'
      'task and goal do not exist in the v3.11 root — measured against the loaded '
      'core (digest e5f7d1e5…): ckp:Goal and ckp:Task are declared by nothing. The '
      'board vocabulary is the adopted wave module: use wave:Ticket, wave:Pass and '
      'wave:Index. affordance, delegation and proof are declared by the root itself; '
      'delivery and validate were cut by ruling. A module reaches a surface only '
      'through a sealed ckp:Adoption naming its digest — never by reading % .',
      p_module, format('%s/%s.ttl', p_root, p_module);
  END IF;

  IF NOT (p_module = ANY (v_known_modules)) THEN
    RAISE EXCEPTION 'ckp.import_module: unknown module %; the known set is EMPTY by ruling. '
      'Every module in force is adopted by digest (ckp:Adoption), not imported from a mount.', p_module;
  END IF;

  -- Unreachable while the known set is empty; retained so re-opening the door
  -- cannot skip R7. An extension MUST NOT mint terms into the core namespace.
  v_path := format('%s/%s.ttl', p_root, p_module);
  v_ttl  := pg_read_file(v_path);
  SELECT string_agg(DISTINCT m[1], ', ')
    INTO v_minted
  FROM regexp_matches(v_ttl, '(?:^|[^A-Za-z0-9_])(ckp:[A-Za-z_][A-Za-z0-9_]*)\s+a\s+(?:rdfs:Class|owl:Class|owl:ObjectProperty|owl:DatatypeProperty)', 'g') AS m;
  IF v_minted IS NOT NULL THEN
    RAISE EXCEPTION E'ckp.import_module: module "%" mints term(s) into the CORE namespace (%): %\n'
      'R7 is normative — re-issue under domain naming and adopt it by digest.',
      p_module, v_core_ns, v_minted;
  END IF;
  SELECT pgrdf.add_graph(v_iri) INTO v_g;
  PERFORM pgrdf.parse_turtle(v_ttl, v_g, v_iri || '#');
  PERFORM pgrdf.materialize(v_g);
  RAISE NOTICE 'ckp.import_module: % imported into %', p_module, v_iri;
END;
$procedure$;

CREATE OR REPLACE PROCEDURE ckp.load_kernel(IN p_path text, IN p_project text)
 LANGUAGE plpgsql
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $procedure$
DECLARE
  v_k   INT := (SELECT v::int FROM ckp.config WHERE k='kernel_graph_id');
  v_iri TEXT := format('urn:ckp:%s/kernel/ck', p_project);
  v_ttl TEXT;
BEGIN
  PERFORM pgrdf.add_graph(v_k, v_iri);
  PERFORM pgrdf.clear_graph(v_k);
  v_ttl := pg_read_file(p_path);
  PERFORM pgrdf.parse_turtle(v_ttl, v_k, 'urn:ckp:kernel#');
  PERFORM pgrdf.materialize(v_k);
  -- Ring repair (#48, same pattern as ckp.boot): the kernel graph's quad table
  -- was just created owned by the CALLING superuser; the first seal's definer
  -- path reads it as ck_substrate. Re-assert the substrate floor over pgrdf.
  GRANT ALL ON ALL TABLES    IN SCHEMA pgrdf TO ck_substrate;
  GRANT ALL ON ALL SEQUENCES IN SCHEMA pgrdf TO ck_substrate;
  -- No ambient board graph. task/goal are retired (see import_module above); the
  -- board is the adopted wave module, which arrives by Adoption, not by import.
END;
$procedure$;

-- 0.4.51 — WHICH KERNEL DID THE CALLER MEAN? Resolved from a SEALED FACT, not
-- from the transport string.
--
-- ckp.germinate_kernel refuses any project failing ^[a-z0-9]+(-[a-z0-9]+)*$ --
-- one lowercase transport segment. ckp._project() applied NO rule at all, and
-- the inbound relay sets ckp.project VERBATIM from the NATS subject segment
-- (inbound_dispatch.rs). So THE NAME WAS VALIDATED WHERE KERNELS ARE BORN AND
-- UNVALIDATED WHERE FACTS ARE SEALED, and one kernel came to exist twice.
--
-- Measured on the bench (PASS-30): urn:ckp:pgck/instances holds sealed
-- projections of BOTH urn:ckp:project:pgck AND urn:ckp:project:pgCK, and of
-- BOTH urn:ckp:pgck/kernel AND urn:ckp:pgCK/kernel, all four labelled "pgCK";
-- urn:ckp:pgCK/instances holds 14 triples from the A3 adoption act; and
-- neither urn:ckp:pgCK/kernel/ck nor urn:ckp:pgCK/shapes/composed exists. The
-- split never surfaced as an error because registry_lookup resolves the
-- substrate floor row under the literal 'pgck', so ROUTING SURVIVED IT while
-- composition, adoption and the epoch did not.
--
-- Slugging the segment would have been the silent fix, and silent is the
-- disease: it would have re-pointed three kernels that were germinated before
-- the canonical rule existed (urn:ckp:pgRDF/kernel/ck and
-- urn:ckp:SuperAiHarness3000/kernel/ck are LOCKED graphs with 25 triples each)
-- onto empty surfaces, with no error anywhere. So the resolution asks a fact
-- instead of transforming a string:
--
--   1. the segment is canonical AND a sealed ckp:Kernel carries it exactly -> it
--   2. exactly one CANONICAL sealed kernel matches case-insensitively      -> that one
--   3. more than one canonical match                                       -> REFUSE, naming them
--   4. no sealed kernel, and the segment is canonical                      -> pass (germination)
--   5. no sealed kernel, non-canonical, but urn:ckp:<seg>/kernel/ck EXISTS -> grandfathered
--   6. otherwise                                                           -> REFUSE with the slug
--
-- THE ORDER WAS DESIGNED AGAINST THE LIVE INVENTORY, NOT AGAINST A PREFERENCE,
-- and the first draft of it was wrong in both directions — measured before it
-- shipped, which is the only reason it is not in the release:
--
--   * "exact match always wins" preserved the split it exists to close. BOTH
--     urn:ckp:pgCK/kernel and urn:ckp:pgck/kernel are sealed, so `pgCK` matched
--     exactly and resolved to itself forever. Hence clause 1's canonical guard:
--     a non-canonical spelling can never win by exactness alone, so `pgCK` falls
--     to clause 2 and lands on the sealed kernel that a germination would have
--     produced.
--   * "refuse anything non-canonical without a sealed kernel" stranded two live
--     components. urn:ckp:pgRDF/kernel/ck and urn:ckp:SuperAiHarness3000/kernel/ck
--     are LOCKED graphs with 25 triples each and NO sealed ckp:Kernel — they were
--     germinated before the canonical rule existed. Clause 5 grandfathers exactly
--     those: the substrate still derives from a fact (their kernel graph), just a
--     weaker one than a seal. It admits no NEW non-canonical name, because a name
--     with neither a seal nor a graph has nothing behind it.
--
-- Clause 3 is not a policy choice either. Two CANONICAL sealed kernels answering
-- to one name is a genuine conflict, and guessing which one a caller meant is
-- how the phantom project was written in the first place.
--
-- Clause 5's exit condition, stated so it cannot be forgotten: it disappears the
-- day those two kernels are re-germinated under canonical names, or seal a
-- ckp:Kernel of their own. It is a legacy allowance with a named end, not a knob.
--
-- It RAISEs rather than returning a sentinel because ckp._dispatch_safe already
-- turns a RAISE into {ok:false, refused:true, sqlstate, error} data (0.4.41),
-- so the door answers with the clause and the worker lives. Read paths fail
-- closed for the same reason writes do.
-- 0.4.56 — THE RESOLVER NOW SAYS WHY, AND THERE IS ONLY ONE OF IT.
--
-- ckp.project_resolve reported which clause fired by INFERRING it from the
-- outcome (`v_out <> v_seg` therefore clause 2). The moment 0.4.54 added the
-- graph-substance clause that inference was wrong: `pgrdf -> pgRDF` resolved on
-- a kernel GRAPH and was reported as "clause 2 — the one CANONICAL sealed
-- kernel", with `sealedKernelsMatching: []` printed directly beneath it,
-- contradicting the label in the same object.
--
-- A CHECKER THAT MISREPORTS ITS OWN REASON is the defect class this pass exists
-- to end, so the fix is not a better inference — it is to stop inferring. The
-- resolution logic lives HERE, once, and returns {project, clause, hits}.
-- ckp._project() is a thin reader of it, so the hot path is unchanged and the
-- explanation cannot drift from the decision: they are the same execution.
CREATE OR REPLACE FUNCTION ckp._project_explain()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  N       text := 'https://conceptkernel.org/ontology/v3.11/core#';
  -- ONE definition of "which project is this". Twelve call sites resolved it
  -- inline in two spellings that DISAGREED on the empty string: ckp.dispatch
  -- mapped '' to '', everything else mapped '' to 'demo' -- so an empty GUC
  -- sent the affordance lookup and the write to different kernels.
  --
  -- The 'demo' fallback is itself a real kernel name, which makes it a landing
  -- site for writes that belong to nobody. It lives HERE now, in one place, so
  -- it can be made fail-closed in a single edit instead of twelve.
  CANON   text := '^[a-z0-9]+(-[a-z0-9]+)*$';
  v_raw   text := NULLIF(current_setting('ckp.project', true), '');
  v_kid   text;
  v_hits  text[];
  v_ask   text;
BEGIN
  -- 0.4.79 — CLAUSE 0: NO KERNEL NAMED. This slot held 'demo' from the repo's
  -- first day (816e9e3, 2026-05-16) and propagated to 14 load-bearing sites: an
  -- EXAMPLE became infrastructure because no gate could refuse a default. It
  -- invented a jurisdiction, so facts sealed declaring themselves governed by
  -- urn:ckp:demo/kernel/ck -- a graph with ZERO quads, measured on a fresh boot
  -- of the current release. Now: absent means ABSENT. The law is still readable
  -- (surface.declared, surface.typecheck, instance.validate all work core-only);
  -- what refuses is SEALING, because M2 (producedBy) is not optional -- a fact
  -- must name whose law governs it. Not having germinated is a complete and
  -- correct state, not a fault.
  IF v_raw IS NULL THEN
    RETURN jsonb_build_object('project', NULL, 'clause',
      'clause 0 - no kernel named (ckp.project unset). The law is in force and readable; sealing refuses until a kernel is named, because a fact must say whose law governs it.',
      'hits', '[]'::jsonb);
  END IF;
  v_kid := 'urn:ckp:'||v_raw||'/kernel';
  -- 1. a CANONICAL spelling with its own sealed kernel wins outright. This is the
  --    common path and costs one indexless scan of a small table. The canonical
  --    guard is load-bearing: without it a non-canonical twin resolves to itself
  --    and the split it exists to close survives (measured — see above).
  IF v_raw ~ CANON AND EXISTS (SELECT 1 FROM ckp.instances i
              WHERE i.body->>'type' = N||'Kernel' AND i.body->>'@id' = v_kid) THEN
    RETURN jsonb_build_object('project', v_raw, 'clause',
      'clause 1 — canonical, and it carries its own sealed ckp:Kernel', 'hits', to_jsonb(v_hits));
  END IF;
  -- 2/3. resolve case-insensitively against the CANONICAL sealed kernels — the
  --      ones a germination today would have produced.
  SELECT array_agg(DISTINCT i.body->>'@id') INTO v_hits
    FROM ckp.instances i
   WHERE i.body->>'type' = N||'Kernel'
     AND lower(i.body->>'@id') = lower(v_kid)
     AND regexp_replace(i.body->>'@id', '^urn:ckp:(.*)/kernel$', '\1') ~ CANON;
  IF v_hits IS NOT NULL AND array_length(v_hits, 1) = 1 THEN
    RETURN jsonb_build_object('project', regexp_replace(v_hits[1], '^urn:ckp:(.*)/kernel$', '\1'),
      'clause', 'clause 2 — resolved onto the one CANONICAL SEALED kernel that answers to this name',
      'hits', to_jsonb(v_hits));
  ELSIF v_hits IS NOT NULL AND array_length(v_hits, 1) > 1 THEN
    -- RAISE takes only `%`; a `%L` here would print the value followed by a
    -- literal L. Format first, raise the formatted string. (Caught by the
    -- negative control, which is the argument for having written one.)
    RAISE EXCEPTION '%', format(
      'ckp._project: kernel id %L is ambiguous — %s sealed kernels answer to it case-insensitively (%s). One kernel must have one spelling; resolve it by governance (seal a ckp:Supersession for the one that is not authoritative) rather than by guessing here.',
      v_raw, array_length(v_hits, 1), array_to_string(v_hits, ', '));
  END IF;
  -- 4. NO SEALED KERNEL — RESOLVE ONTO THE SPELLING THAT HAS SUBSTANCE.
  --
  -- 0.4.54, and this gap was exposed by pgRDF's own report, not by pgCK. The
  -- 0.4.51 rule resolved case only against SEALED kernels, so it closed the split
  -- for pgck — which happens to have one — and did NOTHING for a kernel that
  -- exists only as a GRAPH. Measured with pgCK's own project.resolve verb:
  --     pgrdf -> clause 4 -> pgrdf   (urn:ckp:pgrdf/kernel/ck EMPTY)
  --     pgRDF -> clause 5 -> pgRDF   (urn:ckp:pgRDF/kernel/ck, 25 triples, their doctrine)
  -- sealedKernelsMatching [] for both. Two spellings, two surfaces, and the fix
  -- shipped to end exactly that could not see it. A rule that only works for
  -- kernels shaped like mine is not a rule.
  --
  -- The ordering principle is NOT "prefer the canonical spelling" — it is PREFER
  -- THE SPELLING WITH SUBSTANCE, sealed beating graph, because the substrate must
  -- derive from a fact rather than from a preference about names. Pointing pgrdf
  -- at its empty canonical graph would be canonically tidy and would lose their
  -- doctrine, which is the wrong trade every time.
  --
  -- Migration path, deliberately: the day a kernel seals a ckp:Kernel under its
  -- canonical name, clauses 1-2 take over and BOTH spellings resolve there. This
  -- clause retires itself; it is not a permanent tolerance.
  SELECT array_agg(DISTINCT g) INTO v_hits FROM (
    SELECT j->>'g' AS g FROM pgrdf.sparql(format($q$
      SELECT DISTINCT ?g WHERE { GRAPH ?g { ?s ?p ?o } }
    $q$)) j
    WHERE lower(j->>'g') = lower(format('urn:ckp:%s/kernel/ck', v_raw))
  ) d;
  IF v_hits IS NOT NULL AND array_length(v_hits, 1) = 1 THEN
    RETURN jsonb_build_object('project', regexp_replace(v_hits[1], '^urn:ckp:(.*)/kernel/ck$', '\1'),
      'clause', 'clause 4 — no sealed kernel anywhere; resolved onto the one spelling whose kernel GRAPH has substance',
      'hits', to_jsonb(v_hits));
  ELSIF v_hits IS NOT NULL AND array_length(v_hits, 1) > 1 THEN
    RAISE EXCEPTION '%', format(
      'ckp._project: kernel id %L is ambiguous — %s non-empty kernel graphs answer to it case-insensitively (%s), and none carries a sealed ckp:Kernel to break the tie. Seal a ckp:Kernel under the canonical spelling; that resolves it permanently.',
      v_raw, array_length(v_hits, 1), array_to_string(v_hits, ', '));
  END IF;
  -- 5. nothing behind any spelling. A canonical name is the germination path and
  --    MUST stay open, or kernel.germinate is unreachable for every project that
  --    does not exist yet.
  IF v_raw ~ CANON THEN
    RETURN jsonb_build_object('project', v_raw, 'clause',
      'clause 5 — canonical, nothing sealed or graphed behind it yet; the germination path stays open',
      'hits', '[]'::jsonb);
  END IF;
  -- 6. neither a seal nor a graph stands behind this name. Refuse with the slug,
  --    the same message germination gives, so the two doors teach one rule.
  RAISE EXCEPTION '%', format(
    'ckp._project: kernel id %L is not canonical, no sealed kernel carries it and no kernel graph stands behind it. A project name is lowercase, dashes optional, one transport segment — use %L. (ckp.germinate_kernel refuses the same name; this door now applies the same rule, so a fact can never be sealed into a project that could not be germinated.)',
    v_raw, ckp._slug(regexp_replace(v_raw, '^.*[:/]', '')));
END;
$function$
;

-- The hot path. One reader of one resolver: ckp._project() cannot disagree with
-- ckp.project_resolve about which kernel a segment means, because they are the
-- same execution and the explanation is a field of the decision.
CREATE OR REPLACE FUNCTION ckp._project()
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
  SELECT ckp._project_explain()->>'project';
$function$
;

CREATE OR REPLACE FUNCTION ckp._body_to_ttl(p_body jsonb, p_subj text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  v_type text := p_body->>'type';
  v_ttl  text;
  v_key  text;
  v_val  jsonb;
  v_obj  text;
  s      text;
BEGIN
  v_ttl := '<'||p_subj||'> a <'||COALESCE(v_type, 'urn:ckp:Unknown')||'> .'||chr(10);
  FOR v_key, v_val IN SELECT key, value FROM jsonb_each(p_body)
  LOOP
    -- control keys + non-IRI keys are not RDF properties.
    CONTINUE WHEN v_key IN ('type','@id','participant','participant_display_name','participant_email');
    CONTINUE WHEN position(':' in v_key) = 0;
    IF    jsonb_typeof(v_val) = 'number'  THEN v_obj := v_val::text;            -- xsd:integer / decimal
    ELSIF jsonb_typeof(v_val) = 'boolean' THEN v_obj := v_val::text;            -- xsd:boolean
    ELSIF jsonb_typeof(v_val) = 'string'  THEN
      s := v_val #>> '{}';
      IF s ~ '^[a-z][a-z0-9+.-]*:[^ ]' THEN
        v_obj := '<'||s||'>';                                                   -- IRI node (nodeKind sh:IRI)
      ELSE
        v_obj := '"'||replace(replace(replace(s,'\','\\'),'"','\"'),chr(10),'\n')||'"';  -- xsd:string literal
      END IF;
    ELSIF jsonb_typeof(v_val) = 'array' THEN
      -- 0.4.43: ARRAYS EXPAND INTO ONE TRIPLE PER ELEMENT. They were silently
      -- dropped here, so NO sealed instance could carry a multi-valued property —
      -- which made ckp:Kernel unsealable, because KernelShape requires
      -- hasOrgan minCount 3. That is the whole reason "pgCK cannot create a concept
      -- kernel" was true: not a design decision, a serializer gap. Measured:
      -- germinate refused with MinCount(3) not satisfied while the body carried all
      -- three organs. Same value rules as the scalar arm, per element.
      FOR s IN SELECT jsonb_array_elements_text(v_val) LOOP
        IF s ~ '^[a-z][a-z0-9+.-]*:[^ ]' THEN
          v_ttl := v_ttl||'<'||p_subj||'> <'||v_key||'> <'||s||'> .'||chr(10);
        ELSE
          v_ttl := v_ttl||'<'||p_subj||'> <'||v_key||'> "'||
                   replace(replace(replace(s,'\\','\\\\'),'"','\\"'),chr(10),'\\n')||'" .'||chr(10);
        END IF;
      END LOOP;
      CONTINUE;
    ELSE
      CONTINUE;                                                                 -- objects: not simple values
    END IF;
    v_ttl := v_ttl || '<'||p_subj||'> <'||v_key||'> '||v_obj||' .'||chr(10);
  END LOOP;
  RETURN v_ttl;
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp._body_to_ttl(p_body jsonb, p_subj text, p_shapes_graph integer)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  v_type text := p_body->>'type';
  v_ttl text; v_key text; v_val jsonb; v_obj text; s text;
  v_dt jsonb := '{}'::jsonb; j jsonb; v_giri text; v_d text;
BEGIN
  IF p_shapes_graph IS NOT NULL THEN
    SELECT iri INTO v_giri FROM pgrdf._pgrdf_graphs WHERE graph_id = p_shapes_graph;
    FOR j IN SELECT * FROM pgrdf.sparql(format($q$
        PREFIX sh: <http://www.w3.org/ns/shacl#>
        SELECT ?path ?dt WHERE { GRAPH <%s> { ?s sh:property ?p . ?p sh:path ?path ; sh:datatype ?dt } }
      $q$, v_giri))
    LOOP
      v_dt := v_dt || jsonb_build_object(j->>'path', j->>'dt');
    END LOOP;
  END IF;

  v_ttl := '<'||p_subj||'> a <'||COALESCE(v_type,'urn:ckp:Unknown')||'> .'||chr(10);
  FOR v_key, v_val IN SELECT key, value FROM jsonb_each(p_body)
  LOOP
    CONTINUE WHEN v_key IN ('type','@id','participant','participant_display_name','participant_email');
    CONTINUE WHEN position(':' in v_key) = 0;
    v_d := v_dt->>v_key;
    IF    jsonb_typeof(v_val) = 'number'  THEN v_obj := v_val::text;
    ELSIF jsonb_typeof(v_val) = 'boolean' THEN v_obj := v_val::text;
    ELSIF jsonb_typeof(v_val) = 'string'  THEN
      s := v_val #>> '{}';
      IF s ~ '^[a-z][a-z0-9+.-]*:[^ ]' AND (v_d IS NULL OR v_d = '') THEN
        v_obj := '<'||s||'>';
      ELSE
        v_obj := '"'||replace(replace(replace(s,'\','\\'),'"','\"'),chr(10),'\n')||'"';
        -- declared datatype wins; xsd:string is the default and needs no tag
        IF v_d IS NOT NULL AND v_d <> 'http://www.w3.org/2001/XMLSchema#string' THEN
          v_obj := v_obj||'^^<'||v_d||'>';
        END IF;
      END IF;
    ELSIF jsonb_typeof(v_val) = 'array' THEN
      -- A multi-valued property emits one triple per element. Without this arm
      -- arrays were silently dropped, so no sealed instance could carry a
      -- repeated property -- which made ckp:Kernel unsealable, since it
      -- requires three organs: germinate refused with hasOrgan MinCount(3)
      -- while the body carried all three. Same value rules as the scalar arm,
      -- applied per element. NOTE this is the 3-arg overload, the one ckp.seal
      -- actually calls; fixing only the 2-arg sibling changes nothing.
      FOR s IN SELECT jsonb_array_elements_text(v_val) LOOP
        IF s ~ '^[a-z][a-z0-9+.-]*:[^ ]' AND (v_d IS NULL OR v_d = '') THEN
          v_ttl := v_ttl || '<'||p_subj||'> <'||v_key||'> <'||s||'> .'||chr(10);
        ELSE
          v_obj := '"'||replace(replace(replace(s,'\','\\'),'"','\"'),chr(10),'\n')||'"';
          IF v_d IS NOT NULL AND v_d <> 'http://www.w3.org/2001/XMLSchema#string' THEN
            v_obj := v_obj||'^^<'||v_d||'>';
          END IF;
          v_ttl := v_ttl || '<'||p_subj||'> <'||v_key||'> '||v_obj||' .'||chr(10);
        END IF;
      END LOOP;
      CONTINUE;
    ELSE CONTINUE;
    END IF;
    v_ttl := v_ttl || '<'||p_subj||'> <'||v_key||'> '||v_obj||' .'||chr(10);
  END LOOP;
  RETURN v_ttl;
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp._adopted_graphs(p_project text)
 RETURNS text[]
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  N text := 'https://conceptkernel.org/ontology/v3.11/core#';
BEGIN
  -- Sealed, unsuperseded Adoptions of THIS project, in seal order.
  --
  -- 0.4.57 — THE THIRD SPELLING, found by pgck-mcp the hard way. This accepted
  -- 'urn:ckp:<p>' and 'urn:ckp:<p>/kernel/ck' and MISSED 'urn:ckp:project:<p>' —
  -- which is the MOST principled form, because germinate_kernel seals exactly
  -- that IRI as the ckp:Project @id and the kernel's inProject points at it. So
  -- a caller who read the graph and used the Project's real IRI sealed an
  -- Adoption that was judged by AdoptionShape, ledgered, proof-digested — and
  -- silently composed NOTHING. Measured by pgck-mcp (adoption at their seq 159,
  -- intoEpoch 4, then a full materialization at epoch 5: modules [], digest
  -- unchanged) and filed as the surface.modules ask on this kernel. pgCK's own
  -- adoptions worked only because they copied A3's bare spelling — the composer
  -- rewarded the accident and ignored the principle. A sealed record whose
  -- declared value has no effect is R2's defect shape, inside the composer.
  RETURN COALESCE((
    SELECT array_agg(a.body->>(N||'adopts') ORDER BY a.ts_created)
    FROM ckp.instances a
    WHERE a.body->>'type' = N||'Adoption'
      AND a.body->>(N||'adopts') IS NOT NULL
      -- 0.4.60: pgRDF found the FOURTH spelling in their own sealed doctrine —
      -- urn:ckp:project/<p>, slash not colon (their kernel graph's inProject
      -- carries it). Anyone copying their sealed doctrine into an Adoption got
      -- a valid, load-bearing-for-nothing record. All four forms match now;
      -- the real cure (one canonical spelling at seal) is a shape question.
      AND a.body->>(N||'intoProject') IN ('urn:ckp:'||p_project,
                                          'urn:ckp:'||p_project||'/kernel/ck',
                                          'urn:ckp:project:'||p_project,
                                          'urn:ckp:project/'||p_project)
      AND NOT EXISTS (
        SELECT 1 FROM ckp.instances s
        WHERE s.body->>'type' = N||'Supersession'
          AND s.body->>(N||'supersedes') = a.body->>'@id')
  ), ARRAY[]::text[]);
END;
$function$
;
CREATE OR REPLACE FUNCTION ckp._composed_shapes(p_project text, p_exclude text DEFAULT NULL)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  v_core int; v_kernel int; v_comp int; v_mod int;
  v_iri  text;
  v_cnt  int;
BEGIN
  v_core   := pgrdf.add_graph('urn:ckp:core');
  -- 0.4.79 -- CORE-ONLY IS A REAL STATE. Composition is the act of unioning a
  -- kernel's own graph and its sealed Adoptions INTO core. With no kernel there
  -- is nothing to union, so the surface simply IS core -- returned directly
  -- rather than copied into an invented urn:ckp:<somebody>/shapes/composed.
  -- Reads and validation work here; sealing refuses in _derived_stamps.
  IF p_project IS NULL OR btrim(p_project) = '' THEN
    RETURN v_core;
  END IF;
  v_kernel := pgrdf.add_graph(format('urn:ckp:%s/kernel/ck', p_project));
  v_comp   := pgrdf.add_graph(format('urn:ckp:%s/shapes/composed', p_project));
  PERFORM pgrdf.clear_graph(v_comp);
  PERFORM pgrdf.copy_graph(v_core,   v_comp);
  PERFORM pgrdf.copy_graph(v_kernel, v_comp);
  -- A2: every graph a sealed unsuperseded Adoption names joins the surface.
  -- Module-IRI-is-graph-IRI: the adopts value IS the graph. Fail CLOSED on a
  -- dangling or empty reference — a vanished module silently narrowing the
  -- gate is un-enforcement nobody would see.
  FOREACH v_iri IN ARRAY ckp._adopted_graphs(p_project) LOOP
    -- 0.4.73 — THE CURE IS EXEMPT FROM THE POISON IT REMOVES. p_exclude names
    -- the ONE graph a core#Supersession being sealed right now is about to
    -- un-adopt (derived by ckp.seal from the candidate itself, never caller-
    -- supplied). Without this, a dangling adoption DEADLOCKS its project: every
    -- seal composes, composition raises on the dangling graph, and the raise's
    -- own remedy — "seal a Supersession" — is itself a seal. Measured live:
    -- ontosys, poisoned within hours of germinating, could not reach its cure;
    -- s68's victim project proves both halves. The exclusion is content-honest:
    -- skipping a graph the Supersession removes narrows nothing the resulting
    -- surface should still carry — and for the dangling case the graph is
    -- empty anyway. Fail-closed stands for every other seal.
    CONTINUE WHEN p_exclude IS NOT NULL AND v_iri = p_exclude;
    v_mod := pgrdf.add_graph(v_iri);
    SELECT count(*) INTO v_cnt
      FROM pgrdf.sparql(format('SELECT ?s WHERE { GRAPH <%s> { ?s ?p ?o } } LIMIT 1', v_iri));
    IF v_cnt = 0 THEN
      RAISE EXCEPTION 'ckp._composed_shapes: adopted module graph % is absent or empty — a sealed Adoption names it, so composing without it would silently narrow the enforcement surface. Load the module graph or seal a Supersession (the Supersession seal itself is exempt from this check for the graph it removes).', v_iri;
    END IF;
    -- 0.4.61: pin the graph's canonical digest at FIRST composition. Verification
    -- happens in adoption.check / the oracle, never here — B4's rule: a report
    -- may be wrong cheaply, a gate may not, and a false drift-positive in the
    -- hot path would refuse every seal for the project. Detection, declared.
    -- 0.4.67: the pin carries BOTH planes plus the structural counts. The copy
    -- digest detects in-store drift; the structural digest is what a party on
    -- ANOTHER store verifies against (three loads of one module share it); the
    -- counts (NodeShapes/properties/asserted) are the blank-node-immune third
    -- instrument — the 27+11+4=42 arithmetic, per module.
    -- 0.4.68: pin counts are ASSERTED-ONLY, distinct, and use the two named
    -- methods (F3): nodeshapes = asserted sh:NodeShape typing (11 wave, 4
    -- lexicon); properties = declared vocabulary properties (33, 17) — the
    -- fleet's 27+11+4 / 80+33+17 arithmetic, per module. The first cut read
    -- sh:path rows through SPARQL, which counts the inferred closure too.
    --
    -- 0.4.69 — DIGESTS AT THE DOOR, NEVER IN THE LOOP. This runs on EVERY seal
    -- (ckp.seal composes the surface it judges against), and ON CONFLICT DO
    -- NOTHING evaluates the VALUES first — so 0.4.67 silently computed both
    -- digests and two counts of every adopted module per seal and threw them
    -- away. The fleet's boundary rule ("if anyone proposes a fingerprint
    -- inside a hot step, that's the smell — admission happens once") caught
    -- its second defect in two days, this one in pgck's own day-old code. The
    -- pin is trust-on-FIRST-sight by definition: compute only when absent.
    IF EXISTS (SELECT 1 FROM ckp.adoption_pins ap WHERE ap.graph_iri = v_iri) THEN
      PERFORM pgrdf.copy_graph(v_mod, v_comp);
      CONTINUE;
    END IF;
    INSERT INTO ckp.adoption_pins(graph_iri, graph_digest, structural_digest, nodeshapes, properties, asserted)
    VALUES (v_iri, ckp._surface_digest(v_mod), ckp._structural_digest(v_mod),
      (SELECT count(DISTINCT q4.subject_id) FROM pgrdf._pgrdf_quads q4
         JOIN pgrdf._pgrdf_dictionary p4 ON p4.id = q4.predicate_id
         JOIN pgrdf._pgrdf_dictionary o4 ON o4.id = q4.object_id
        WHERE q4.graph_id = v_mod AND NOT q4.is_inferred
          AND p4.lexical_value = 'http://www.w3.org/1999/02/22-rdf-syntax-ns#type'
          AND o4.lexical_value = 'http://www.w3.org/ns/shacl#NodeShape'),
      (SELECT count(DISTINCT q6.subject_id) FROM pgrdf._pgrdf_quads q6
         JOIN pgrdf._pgrdf_dictionary p6 ON p6.id = q6.predicate_id
         JOIN pgrdf._pgrdf_dictionary o6 ON o6.id = q6.object_id
        WHERE q6.graph_id = v_mod AND NOT q6.is_inferred
          AND p6.lexical_value = 'http://www.w3.org/1999/02/22-rdf-syntax-ns#type'
          AND o6.lexical_value IN ('http://www.w3.org/2002/07/owl#DatatypeProperty',
                                   'http://www.w3.org/2002/07/owl#ObjectProperty',
                                   'http://www.w3.org/2002/07/owl#AnnotationProperty',
                                   'http://www.w3.org/1999/02/22-rdf-syntax-ns#Property')),
      (SELECT count(*) FROM pgrdf._pgrdf_quads q WHERE q.graph_id = v_mod AND NOT q.is_inferred))
    ON CONFLICT (graph_iri) DO NOTHING;
    PERFORM pgrdf.copy_graph(v_mod, v_comp);
  END LOOP;
  -- Entailment is per-graph and pgrdf.validate does not entail, so the closure
  -- is computed HERE, once, rather than depended on at validate time.
  PERFORM pgrdf.materialize(v_comp);
  RETURN v_comp;
END;
$function$
;

-- P0-D mechanism 2 (pgCK#27): the admitted-TYPE gate — a substrate lookup, NOT
-- a shape. SHACL is target-driven: a type no shape targets is validated by
-- nothing and returns conforms=true vacuously, so an invented type URN would
-- seal `verified:true` with an arbitrary body. No sh:closed and no ontology
-- edit catches this (measured on the bench: `ex:u1 a ex:Undeclared` ->
-- conforms=TRUE). The §4.4 generated-shape form (sh:closed over rdf:type with
-- sh:in of the admitted set) is blocked on pgRDF#102 (sh:in does not match IRI
-- value nodes) AND on the module/Adoption vocabulary being adopted; until then
-- the lookup below IS the enforcement, reading the SAME composed surface the
-- gate validates against (never a second procedural authority elsewhere).
--
-- Admitted = the composed shapes graph DECLARES the type: some shape targets it
-- (sh:targetClass) OR it is a declared rdfs:Class / owl:Class. A declared class
-- with no shape is admitted (declared, just unconstrained); an invented URN that
-- is neither targeted nor declared is refused.
CREATE OR REPLACE FUNCTION ckp._type_admitted(p_type text, p_project text, p_comp integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE v_comp_iri text; v_board_iri text; v_ask text; v_q text;
BEGIN
  IF p_type IS NULL OR position(':' in p_type) = 0 THEN
    RETURN false;   -- no resolvable type is not an admitted type
  END IF;
  -- 0.4.42: the #46 TRANSITIONAL ALLOWANCE IS DELETED. It read "tolerate it until
  -- #46 re-points the body construction, at which point the board path becomes
  -- non-vacuously validated". While it stood, R2 was open on the write path — seal
  -- consults this function, so a v3.7 type reached the SHACL gate, was targeted by
  -- no shape, took a VACUOUS conforms:true and sealed. An undeclared type is now
  -- refused whatever namespace it carries.
  --
  -- 0.4.51 — CORRECTION, and it is this file's own claim being withdrawn. 0.4.42
  -- also asserted here that "urn:ckp:board/{Task,Goal,Edge,Message} now carry
  -- shapes in the project kernel graph", i.e. that its exit condition was met.
  -- THEY DO NOT. Those four are declared in exactly one place,
  -- examples/example.kernel.ttl, which no module can load — import_module knows
  -- {task, goal} and both are retired. Measured fleet-wide, twice, by two
  -- parties: zero rows mention urn:ckp:board/Edge in any graph. The board
  -- defaults are removed from edge.create and notify in this same version, so
  -- the claim is not merely corrected, its subject is gone.
  --
  -- The lesson is R1 turned on our own comments: a sentence asserting a gate is
  -- a claim, and an unverified claim in a comment is the same defect class as an
  -- unenforced constraint in a shape. It survived because nobody re-ran it.
  -- Admitted = the type is DECLARED (a shape targets it, or it is a declared
  -- class) anywhere the kernel loaded: the composed core+ck surface OR the
  -- project board. Reads the same surfaces the gate/self-test consult — never
  -- a second authority. An invented URN in none of them is refused.
  --
  -- 0.4.51 — THE SCOPE WAS NEVER ENFORCED, AND THAT IS THE WHOLE GATE.
  -- This asked ONE query shaped
  --     ASK { GRAPH ?g { …UNION…UNION… } FILTER(?g IN (<comp>, <board>)) }
  -- and pgrdf DOES NOT APPLY THAT FILTER under the UNION. Measured live
  -- (PASS-30 §1): the identical ASK restricted to a graph that does not exist
  -- returns TRUE for a module-declared class, and returns TRUE for <http://ex/T>,
  -- a type declared only in urn:sh:probe — a five-triple SHACL scratch graph.
  -- So a TEST FIXTURE WIDENED THE PRODUCTION TYPE GATE, and every type declared
  -- anywhere on the substrate was admitted for every kernel.
  --
  -- The consequence is the state pgCK.MCP filed as F10. The type gate read the
  -- whole store while the shape gate read the composed surface, so a class the
  -- store declares and the surface does not shape was ADMITTED and then judged
  -- by nothing — SHACL is target-driven, so validation never ran, and the seal
  -- omitted conformsToShape honestly. Three correct components, two of them
  -- reading different stores.
  --
  -- The same FILTER on a plain BGP is REJECTED as untranslatable; only the UNION
  -- form drops it silently. So the one shape pgCK shipped is the one shape that
  -- fails open, with no log line. The fix does not argue with the engine: it
  -- issues ONE CONSTANT-GRAPH ASK PER SURFACE and combines them HERE, where the
  -- combination is plpgsql and cannot be optimised away. A graph that does not
  -- exist answers false rather than raising (measured), so the board arm is safe
  -- for every project that never imported one.
  v_comp_iri  := pgrdf.graph_iri(p_comp);
  v_board_iri := format('urn:ckp:%s/kernel/board', p_project);
  v_q := $q$
    PREFIX sh:   <http://www.w3.org/ns/shacl#>
    PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
    PREFIX owl:  <http://www.w3.org/2002/07/owl#>
    ASK WHERE { GRAPH <%1$s> {
      { ?s sh:targetClass <%2$s> } UNION { <%2$s> a rdfs:Class } UNION { <%2$s> a owl:Class }
    } }
  $q$;
  SELECT COALESCE(j->>'_ask', j->>'boolean') INTO v_ask
  FROM pgrdf.sparql(format(v_q, v_comp_iri, p_type)) j LIMIT 1;
  IF COALESCE(v_ask, 'false') = 'true' THEN
    RETURN true;
  END IF;
  SELECT COALESCE(j->>'_ask', j->>'boolean') INTO v_ask
  FROM pgrdf.sparql(format(v_q, v_board_iri, p_type)) j LIMIT 1;
  RETURN COALESCE(v_ask, 'false') = 'true';
END;
$function$
;

-- 0.4.51 — ONE definition of "which properties does this type declare".
--
-- Four call sites resolved this inline and THEY DID NOT AGREE. create_typed,
-- ckp.query and update_typed read urn:ckp:<proj>/kernel/ck; validate_instance
-- read urn:ckp:<proj>/shapes/composed. So `instance.validate` and
-- `instance.create` mapped the SAME JSON to DIFFERENT property IRIs, which is
-- validate ⟺ seal (R3/G3) broken one layer beneath the gate everyone was
-- watching: validate could resolve `reason` to ckp:reason while create minted
-- <type-namespace>reason, and the caller is told its body conformed.
--
-- The kernel-graph-only read is also the trap that springs on adoption. A
-- module type's shape may require a FOREIGN property — wave:FindingShape
-- requires rdfs:label and ckp:reason — and neither is in the kernel graph, so
-- the map came back empty and both keys fell through to the type's own
-- namespace. Harmless only for as long as nothing gates the type. See PASS-30
-- §4: emission and shape move in one act.
--
-- Composed FIRST, kernel LAST, so a kernel's own declaration wins over a stale
-- composed copy of it and the module/core paths are still resolvable. Never
-- fewer entries than the old read; the caller's fallback is unchanged for what
-- neither graph declares.
--
-- p_composed exists for ONE declared exception: ckp.query uses this map to
-- REFUSE undeclared filter keys, so widening it there would newly refuse reads
-- that resolve today (e.g. filtering on a substrate-stamped key no shape
-- declares). That is a tightening other components have not asked for, so it is
-- held here as a named argument with a reason rather than taken silently. Flip
-- it when the read surface is ready, in its own act.
CREATE OR REPLACE FUNCTION ckp._propmap(p_type text, p_project text, p_composed boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  v_map jsonb := '{}'::jsonb;
  v_g   text;
  v_gs  text[];
  -- 0.4.60 — ANCESTORS INCLUDED. The gate validates the candidate against
  -- shapes targeting the type AND its ancestors (the parent-closure stamp is
  -- exactly what makes ParticipantShape reach a wave#Component), but this map
  -- read only shapes targeting the type itself. So core#participantKind was
  -- REQUIRED by the gate and ABSENT from surface.declared — measured
  -- independently by pgrdf-mcp ("the declared map and the gate disagree about
  -- the contract", three refusals to learn it) and by pgRDF. The composed
  -- graph is materialized, so subClassOf closure is present as direct triples;
  -- both branches are self-contained (branch-local — the #114-safe form).
  v_q   text := $q$
    PREFIX sh:   <http://www.w3.org/ns/shacl#>
    PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
    SELECT ?path WHERE { GRAPH <%1$s> {
      { ?s sh:targetClass <%2$s> ; sh:property ?p . ?p sh:path ?path }
      UNION
      { <%2$s> rdfs:subClassOf ?anc . ?s sh:targetClass ?anc ; sh:property ?p . ?p sh:path ?path }
    } }
  $q$;
BEGIN
  IF p_type IS NULL OR btrim(p_type) = '' THEN
    RETURN v_map;
  END IF;
  v_gs := CASE WHEN p_composed
               THEN ARRAY[format('urn:ckp:%s/shapes/composed', p_project),
                          format('urn:ckp:%s/kernel/ck', p_project)]
               ELSE ARRAY[format('urn:ckp:%s/kernel/ck', p_project)] END;
  FOREACH v_g IN ARRAY v_gs LOOP
    SELECT v_map || COALESCE(jsonb_object_agg(regexp_replace(path, '^.*[/#]', ''), path), '{}'::jsonb)
      INTO v_map
    FROM (
      SELECT DISTINCT j->>'path' AS path
        FROM pgrdf.sparql(format(v_q, v_g, p_type)) AS j
       WHERE j->>'path' IS NOT NULL
    ) p;
  END LOOP;
  RETURN v_map;
  -- (ancestors included since 0.4.60 — see v_q above)
END;
$function$
;

-- 0.4.59 — STAMP PROJECTION: the sealed spine becomes SPARQL-visible.
--
-- pgRDF's v0.6.30 spec §4.4 states the contract this implements: seals land
-- through the door → stamps projected into instances graphs → the fence census
-- (judged-or-fenced, the MINUS-pair pgRDF proved) runs CONTINUOUSLY over RDF.
-- Until now sealed instances were relational-only (pgck-mcp's CL-A3, filed as
-- F20: "sealed instances are not in RDF, so this question is not expressible as
-- an affordance today"), which forced every oracle signal into a pgck-only
-- built-in — the exact SQL escape hatch pgRDF's §4.6 wants gone, because a
-- built-in cannot be adopted by another kernel while a SPARQL affordance can.
--
-- What is projected: the instance's @id as subject, rdf:type, and every
-- top-level IRI-keyed property of the SEALED body — which includes the four
-- stamps, since seal merges them before storage. Additive, never clearing: RDF
-- set semantics dedupe re-seals. A projection failure WARNs loudly and never
-- aborts the seal — a refusal is the gate's job; killing the write over a
-- mirror is the transport-death class PASS-29 closed. Drift between store and
-- mirror is repaired (and thereby detected) by the wave.project rebuild verb.
CREATE OR REPLACE FUNCTION ckp._project_instance_spine(p_id text, p_body jsonb, p_project text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  v_g    bigint;
  v_subj text;
  v_ttl  text := '';
  v_key  text;
  v_val  jsonb;
  v_el   jsonb;
  v_type text := p_body->>'type';
BEGIN
  v_subj := COALESCE(NULLIF(p_body->>'@id',''), '');
  IF v_subj !~ '^[A-Za-z][A-Za-z0-9+.-]*:' THEN
    v_subj := 'urn:ckp:'||p_project||'/inst/'||ckp._slug(p_id);
  END IF;
  IF v_type IS NOT NULL AND position(':' in v_type) > 0 THEN
    v_ttl := v_ttl || format('<%s> a <%s> .%s', v_subj, v_type, chr(10));
  END IF;
  FOR v_key, v_val IN SELECT key, value FROM jsonb_each(p_body) LOOP
    CONTINUE WHEN v_key !~ '^(https?://|urn:)';
    IF jsonb_typeof(v_val) = 'array' THEN
      FOR v_el IN SELECT * FROM jsonb_array_elements(v_val) LOOP
        v_ttl := v_ttl || ckp._spine_triple(v_subj, v_key, v_el);
      END LOOP;
    ELSIF jsonb_typeof(v_val) IN ('string','number','boolean') THEN
      v_ttl := v_ttl || ckp._spine_triple(v_subj, v_key, v_val);
    END IF;   -- objects are payload structure, not spine
  END LOOP;
  IF v_ttl = '' THEN RETURN; END IF;
  -- 0.4.64 — SAME deterministic id as project_instance_label's trigger. Two
  -- registration paths for one IRI meant first-writer-wins: when a seal's spine
  -- projection auto-registered <p>/instances at a low id first, the trigger's
  -- deterministic add_graph raised, its swallow hid it, and the label search
  -- index silently went dark (s32: governed match found 0 of 3). One IRI, one
  -- id formula, both writers.
  v_g := 1300000000 + (abs(hashtext(format('urn:ckp:%s/instances', p_project))) % 90000000);
  PERFORM pgrdf.add_graph(v_g, format('urn:ckp:%s/instances', p_project));
  PERFORM pgrdf.parse_turtle(v_ttl, v_g, 'urn:ckp:spine#');
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'ckp._project_instance_spine: % (instance % sealed and ledgered; the RDF mirror is behind — run wave.project to rebuild)', SQLERRM, p_id;
END;
$function$
;

-- One triple, one place: IRI-looking string values become IRI objects, all else
-- a quoted literal with backslash/quote/newline escaped. Numbers and booleans
-- stay plain literals — the census needs existence, not xsd fidelity.
CREATE OR REPLACE FUNCTION ckp._spine_triple(p_subj text, p_pred text, p_val jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE v_s text;
BEGIN
  IF jsonb_typeof(p_val) = 'string' THEN
    v_s := p_val #>> '{}';
    IF v_s ~ '^(https?://|urn:|ckp://)[^[:space:]"<>{}|\\^`]+$' THEN
      RETURN format('<%s> <%s> <%s> .%s', p_subj, p_pred, v_s, chr(10));
    END IF;
    v_s := replace(replace(v_s, '\', '\\'), '"', '\"');
    v_s := replace(replace(v_s, chr(10), '\n'), chr(13), '\n');
    RETURN format('<%s> <%s> "%s" .%s', p_subj, p_pred, v_s, chr(10));
  END IF;
  RETURN format('<%s> <%s> "%s" .%s', p_subj, p_pred, p_val #>> '{}', chr(10));
END;
$function$
;

-- The rebuild: clears the mirror and re-projects EVERY sealed instance of the
-- calling project. Doubles as the drift detector — mirror ≠ rebuild is the
-- finding. Registered as wave.project.
CREATE OR REPLACE FUNCTION ckp.wave_project_spine(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  v_proj text := ckp._project();
  v_g bigint; v_n int := 0; r record;
BEGIN
  v_g := 1300000000 + (abs(hashtext(format('urn:ckp:%s/instances', v_proj))) % 90000000);
  PERFORM pgrdf.add_graph(v_g, format('urn:ckp:%s/instances', v_proj));
  PERFORM pgrdf.clear_graph(v_g);
  FOR r IN SELECT id, body FROM ckp.instances ORDER BY ts_created LOOP
    PERFORM ckp._project_instance_spine(r.id, r.body, v_proj);
    v_n := v_n + 1;
  END LOOP;
  RETURN jsonb_build_object('ok', true, 'kernel', v_proj,
    'graph', 'urn:ckp:'||v_proj||'/instances', 'projected', v_n,
    'note', 'the sealed spine is now SPARQL-visible: rdf:type + every IRI-keyed property incl. the four stamps. The fence census is the MINUS-pair over this graph — sealedAtEpoch MINUS conformsToShape.');
END;
$function$
;

-- 0.4.63 — WAVE.SIGNALS (né wave.oracle, 0.4.58 — renamed before it ever
-- shipped in a tag: "oracle" is Oracle Corp's strongest mark in exactly our
-- product class, and the verb never prophesied anything anyway — it DERIVES
-- signals from sealed facts, so the accurate name and the cautious name are
-- the same name). Signals are DERIVED from
-- sealed facts, never asserted; the pass boundary is a query, never a memory.
--
-- The question it answers: WHAT GOES ON THIS PASS, AND WHAT GOES ON THE NEXT?
-- The rule, encoded rather than remembered:
--   THIS pass  = facts stamped with its number (discoveredAtPass / resolvedAtPass
--                / ruledAtPass / opAtPass / rebasedAtPass / forPass), plus the
--                epochs those acts advanced. Closed when its Index is sealed and
--                its Confirmations reference re-run gates.
--   NEXT pass  = whatever `next` returns AT INDEX-SEAL TIME: open findings,
--                pending unretired proposals, operations addressed to this
--                component and not yet answered. Nobody decides the carry-over
--                by memory; the queue IS the derivation.
--   THIS wave  = everything bound to one root digest (wave:Statement bindsRoot).
--                The NEXT wave begins when the root moves — never mid-root.
--
-- Facts are relational (sealed instances), so this is a built-in, not a SPARQL
-- affordance — the F20 limit, stated by pgck-mcp: sealed instances are not in
-- RDF yet. When stamp projection lands, each signal becomes a governed SPARQL
-- read and this function retires into compatibility.
CREATE OR REPLACE FUNCTION ckp.wave_signals(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  C text := 'https://conceptkernel.org/ontology/v3.11/core#';
  W text := 'https://conceptkernel.org/ontology/v3.11/wave#';
  v_proj  text := ckp._project();
  v_pass  int  := (p_payload->>'pass')::int;
  -- component alias convention: c-<project, dashes stripped> (c-pgck, c-pgckmcp);
  -- override with {component} where the convention doesn't hold (ck-lib-js → c-cklib).
  v_comp  text := COALESCE(p_payload->>'component', W||'c-'||replace(v_proj,'-',''));
  v_epoch int  := COALESCE((SELECT epoch FROM ckp.kernel_epoch WHERE kernel = v_proj), 0);
  v_this jsonb; v_next jsonb; v_sig jsonb;
BEGIN
  -- THIS PASS — everything stamped with the number, any of the six stamps.
  IF v_pass IS NOT NULL THEN
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'id', i.id,
        'type', regexp_replace(i.body->>'type','^.*[/#]',''),
        'by',   i.body->>(C||'producedBy'),
        'judged', (i.body ? (C||'conformsToShape'))) ORDER BY i.ts_created), '[]'::jsonb)
      INTO v_this
    FROM ckp.instances i
    WHERE COALESCE((i.body->>(W||'discoveredAtPass'))::numeric, -1) = v_pass
       OR COALESCE((i.body->>(W||'resolvedAtPass'))::numeric,  -1) = v_pass
       OR COALESCE((i.body->>(W||'ruledAtPass'))::numeric,     -1) = v_pass
       OR COALESCE((i.body->>(W||'opAtPass'))::numeric,        -1) = v_pass
       OR COALESCE((i.body->>(W||'rebasedAtPass'))::numeric,   -1) = v_pass
       OR i.body->>(W||'forPass') = W||'pass-'||v_pass;
  END IF;

  -- THE NEXT-PASS QUEUE — derived, so carry-over is never a memory exercise.
  v_next := jsonb_build_object(
    'openFindings', (SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'id', i.id,
        'label', left(COALESCE(i.body->>'http://www.w3.org/2000/01/rdf-schema#label',
                               i.body->>(W||'label')), 140),
        'by', i.body->>(C||'producedBy')) ORDER BY i.ts_created), '[]'::jsonb)
      FROM ckp.instances i
      WHERE i.body->>'type' = W||'Finding' AND i.body->>(W||'findingState') = 'open'),
    'pendingProposals', (SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'id', i.id, 'about', i.body->>(C||'about'), 'op', i.body->>(C||'proposalOp'),
        'by', i.body->>(C||'createdBy')) ORDER BY i.ts_created), '[]'::jsonb)
      FROM ckp.instances i
      WHERE i.body->>'type' = C||'Proposal'
        AND i.body->>(C||'proposalState') = 'pending'
        AND NOT i.body ? (C||'retiredAtEpoch')),
    'inbox', (SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'id', i.id, 'opKind', i.body->>(W||'opKind'),
        'from', i.body->>(C||'producedBy')) ORDER BY i.ts_created), '[]'::jsonb)
      FROM ckp.instances i
      WHERE i.body->>'type' = W||'Operation'
        -- 0.4.62: opTarget has no canonical spelling — components address this
        -- kernel as its wave alias, its kernel URN, or its kernel/ck graph. Two
        -- escalations from ck-dev sat unseen for a day because this matched the
        -- alias alone. Same defect family as the intoProject spellings.
        AND i.body->>(W||'opTarget') IN (v_comp,
              'urn:ckp:'||v_proj||'/kernel', 'urn:ckp:'||v_proj||'/kernel/ck')));

  -- SIGNALS — health counts a third party can recompute. Never one boolean.
  v_sig := jsonb_build_object(
    'unjudged',       (SELECT count(*) FROM ckp.instances i
                       WHERE COALESCE((i.body->>(C||'sealedAtEpoch'))::numeric, -1) >= 1
                         AND NOT i.body ? (C||'conformsToShape')),
    'preEnforcement', (SELECT count(*) FROM ckp.instances i
                       WHERE NOT i.body ? (C||'sealedAtEpoch')),
    'anonymousSeals', (SELECT count(*) FROM ckp.instances i
                       WHERE i.body->>(C||'createdBy') LIKE 'urn:ckp:participant:anon%'),
    'openFindings',   (SELECT count(*) FROM ckp.instances i
                       WHERE i.body->>'type' = W||'Finding'
                         AND i.body->>(W||'findingState') = 'open'),
    'pendingProposalsFleet', (SELECT count(*) FROM ckp.instances i
                       WHERE i.body->>'type' = C||'Proposal'
                         AND i.body->>(C||'proposalState') = 'pending'
                         AND NOT i.body ? (C||'retiredAtEpoch')),
    -- 0.4.65 (§5b): the agreements guarding this kernel's seal-exit. A guard
    -- two parties agreed to must be READABLE by the third who meets it.
    'obligations',    (SELECT COALESCE(jsonb_agg(jsonb_build_object(
                         'obligation', o.obligation,
                         'targetType', regexp_replace(o.target_type,'^.*[/#]',''),
                         'check', o.check_name,
                         'sinceEpoch', o.added_epoch) ORDER BY o.obligation), '[]'::jsonb)
                       FROM ckp.proof_obligations o
                       WHERE o.active AND o.project = v_proj));

  RETURN jsonb_build_object(
    'ok', true, 'kernel', v_proj, 'component', v_comp, 'epoch', v_epoch,
    'pass', v_pass, 'thisPass', COALESCE(v_this, '[]'::jsonb),
    'next', v_next, 'signals', v_sig,
    -- 0.4.71 — R-11 (pgRDF I9): every list-shaped reply states its
    -- completeness, and this census is INCOMPLETE BY CONSTRUCTION until its
    -- measured blind spots close. Three legitimate arrivals were missed in one
    -- day; a reader who treats this as the whole wire builds on absence.
    'completeness', jsonb_build_object(
      'verdict', 'INCOMPLETE — blind spots declared below',
      'blindSpots', jsonb_build_array(
        'thisPass matches only the six *AtPass stamps and forPass — an unstamped fact (e.g. a Confirmation) is invisible here',
        'inbox matches opTarget in three spellings of THIS component — an Operation addressed to another component, or a fourth spelling, is invisible',
        'openFindings/pendingProposals are fleet-wide, but Passes and Epochs of other projects are not surfaced',
        'no acknowledgement lifecycle: answered Operations remain in inbox forever'),
      'counters', ckp._engine_counters()),
    'boundary', 'THIS pass = facts stamped with its number + the epochs they advanced; closed at Index seal. NEXT pass = this `next` object AT close — derived, never remembered. NEXT wave = when bindsRoot moves. unjudged means sealedAtEpoch>=1 with conformsToShape ABSENT: admitted, ledgered, judged by nothing — the fence.');
END;
$function$
;

-- 0.4.51 — THE CHECKER SURFACE, as verbs rather than as scratch scripts.
--
-- PASS-30 answered four questions with hand-written psql probes: is this type
-- admitted and by WHICH graph · which admitted types does no shape target · what
-- does this type declare · what does this transport segment resolve to and why.
-- Each answer mattered; none of them was re-runnable by the party who needed it,
-- and none was a fact. A check that lives in a scratch directory is a second
-- enforcement surface with worse provenance than the first.
--
-- These four read the SAME functions the gate reads — _type_admitted, _propmap,
-- _project, _composed_shapes — never a parallel implementation. That is the
-- whole point: a probe that re-implements the gate tests the probe.

CREATE OR REPLACE FUNCTION ckp.surface_typecheck(p_payload jsonb, p_project text DEFAULT NULL)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  v_proj text := COALESCE(p_project, ckp._project());
  v_type text := COALESCE(p_payload->>'type', p_payload->>'@type');
  v_comp int;
  v_ci   text; v_bi text; v_q text; v_a text;
  v_in_comp bool := false; v_in_board bool := false;
BEGIN
  IF v_type IS NULL OR btrim(v_type) = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'type_required',
      'hint', 'surface.typecheck {"type": "<class IRI>"} — answers whether THIS kernel admits it, and by which graph');
  END IF;
  -- 0.4.81 — REFUSE A CURIE INSTEAD OF ANSWERING VACUOUSLY. `ckp:Project` is a
  -- prefixed name, not an IRI; the composed surface holds only absolute IRIs, so
  -- it matched nothing and this verb replied `declared: {}` / `admitted: false`
  -- — a confident answer that the type is unknown, about a type the gate judges
  -- every day. A caller learns a FALSE contract and cannot tell it from a real
  -- absence. An absolute IRI here carries :// or begins urn: ; anything else is
  -- a prefix this substrate never expands.
  IF v_type IS NOT NULL AND v_type NOT LIKE '%://%' AND v_type NOT LIKE 'urn:%' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'type_is_a_curie', 'type', v_type,
      'hint', 'this looks like a prefixed name (CURIE), not an IRI. Nothing expands prefixes here — pass the absolute IRI, e.g. https://conceptkernel.org/ontology/v3.11/core#Project rather than ckp:Project.');
  END IF;
  v_comp := ckp._composed_shapes(v_proj);
  v_ci := pgrdf.graph_iri(v_comp);
  v_bi := format('urn:ckp:%s/kernel/board', v_proj);
  v_q  := $q$
    PREFIX sh:   <http://www.w3.org/ns/shacl#>
    PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
    PREFIX owl:  <http://www.w3.org/2002/07/owl#>
    ASK WHERE { GRAPH <%1$s> {
      { ?s sh:targetClass <%2$s> } UNION { <%2$s> a rdfs:Class } UNION { <%2$s> a owl:Class }
    } }
  $q$;
  SELECT COALESCE(j->>'_ask', j->>'boolean') INTO v_a
    FROM pgrdf.sparql(format(v_q, v_ci, v_type)) j LIMIT 1;
  v_in_comp := COALESCE(v_a,'false') = 'true';
  SELECT COALESCE(j->>'_ask', j->>'boolean') INTO v_a
    FROM pgrdf.sparql(format(v_q, v_bi, v_type)) j LIMIT 1;
  v_in_board := COALESCE(v_a,'false') = 'true';
  RETURN jsonb_build_object(
    'ok', true,
    'kernel', v_proj,
    'type', v_type,
    -- the gate's OWN answer, not a re-implementation of it
    'admitted', ckp._type_admitted(v_type, v_proj, v_comp),
    'via', CASE WHEN v_in_comp THEN 'composed' WHEN v_in_board THEN 'board' ELSE null END,
    'shaped', (SELECT count(*) > 0 FROM pgrdf.sparql(format(
       'PREFIX sh: <http://www.w3.org/ns/shacl#> SELECT ?s WHERE { GRAPH <%s> { ?s sh:targetClass <%s> } }',
       v_ci, v_type))),
    'surface', v_ci,
    'surfaceDigest', ckp._surface_digest(v_comp),
    'epoch', COALESCE((SELECT epoch FROM ckp.kernel_epoch WHERE kernel = v_proj), 0),
    -- SHAPED is the half that decides whether a seal is GATED. Admitted-but-
    -- unshaped seals verified:true and conformsToShape ABSENT, which is P13's
    -- "no outcome recorded by omission" happening inside the record.
    'note', 'admitted says the type may seal; shaped says a seal would be JUDGED. Admitted and not shaped means conformsToShape will be absent.');
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp.surface_unshaped(p_project text DEFAULT NULL)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  v_proj text := COALESCE(p_project, ckp._project());
  v_comp int; v_ci text; v_rows jsonb;
BEGIN
  v_comp := ckp._composed_shapes(v_proj);
  v_ci   := pgrdf.graph_iri(v_comp);
  -- 0.4.52 — THE ANTI-JOIN IS DONE HERE, NOT IN A FILTER THE ENGINE IGNORES.
  --
  -- The obvious form is one query with FILTER NOT EXISTS { ?sh sh:targetClass ?c }.
  -- It is SILENTLY DROPPED — same family as the FILTER(?g IN …) defect this
  -- version's _type_admitted exists to fix. Measured within minutes of shipping
  -- it: surface.vacuity returned 55 rows including core#Kernel and wave#Finding,
  -- while surface.typecheck reported shaped:true for both. Two answers from one
  -- surface, and the one that was WRONG was the checker.
  --
  -- So this pass built the exact defect it was written to detect, in the tool
  -- meant to detect it — a check that cannot fail the thing it claims. It is
  -- recorded rather than quietly corrected because "the negative control caught
  -- it" is only worth something if the near-miss is also on the record.
  --
  -- Two plain queries, difference taken in SQL. No FILTER anywhere. If the engine
  -- ever drops one of THESE, the result is empty rather than everything — the
  -- failure direction matters, and this one fails closed.
  SELECT COALESCE(jsonb_agg(c ORDER BY c), '[]'::jsonb) INTO v_rows FROM (
    SELECT j->>'c' AS c FROM pgrdf.sparql(format($q$
      PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
      PREFIX owl:  <http://www.w3.org/2002/07/owl#>
      SELECT DISTINCT ?c WHERE { GRAPH <%1$s> { { ?c a rdfs:Class } UNION { ?c a owl:Class } } }
    $q$, v_ci)) j
    EXCEPT
    SELECT k->>'c' FROM pgrdf.sparql(format($q$
      PREFIX sh: <http://www.w3.org/ns/shacl#>
      SELECT DISTINCT ?c WHERE { GRAPH <%1$s> { ?sh sh:targetClass ?c } }
    $q$, v_ci)) k
  ) d;
  RETURN jsonb_build_object(
    'ok', true, 'kernel', v_proj, 'surface', v_ci,
    'epoch', COALESCE((SELECT epoch FROM ckp.kernel_epoch WHERE kernel = v_proj), 0),
    'surfaceDigest', ckp._surface_digest(v_comp),
    'unshaped', v_rows,
    'count', jsonb_array_length(v_rows),
    'note', 'a class this surface DECLARES that no shape TARGETS. An instance of one seals with conformsToShape absent — admitted, ledgered, and judged by nothing. owl:Thing/owl:Nothing are structural and expected.');
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp.surface_declared(p_payload jsonb, p_project text DEFAULT NULL)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  v_proj text := COALESCE(p_project, ckp._project());
  v_type text := COALESCE(p_payload->>'type', p_payload->>'@type');
BEGIN
  IF v_type IS NULL OR btrim(v_type) = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'type_required',
      'hint', 'surface.declared {"type": "<class IRI>"} — the property contract, so a caller can learn it WITHOUT writing');
  END IF;
  -- 0.4.81 — REFUSE A CURIE INSTEAD OF ANSWERING VACUOUSLY. `ckp:Project` is a
  -- prefixed name, not an IRI; the composed surface holds only absolute IRIs, so
  -- it matched nothing and this verb replied `declared: {}` / `admitted: false`
  -- — a confident answer that the type is unknown, about a type the gate judges
  -- every day. A caller learns a FALSE contract and cannot tell it from a real
  -- absence. An absolute IRI here carries :// or begins urn: ; anything else is
  -- a prefix this substrate never expands.
  IF v_type IS NOT NULL AND v_type NOT LIKE '%://%' AND v_type NOT LIKE 'urn:%' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'type_is_a_curie', 'type', v_type,
      'hint', 'this looks like a prefixed name (CURIE), not an IRI. Nothing expands prefixes here — pass the absolute IRI, e.g. https://conceptkernel.org/ontology/v3.11/core#Project rather than ckp:Project.');
  END IF;
  -- The same map create and validate resolve keys through. A caller reading this
  -- and a caller writing a body cannot disagree, because there is one map.
  RETURN jsonb_build_object(
    'ok', true, 'kernel', v_proj, 'type', v_type,
    'declared', ckp._propmap(v_type, v_proj),
    'kernelGraphOnly', ckp._propmap(v_type, v_proj, false),
    'note', 'declared = the composed surface ∪ this kernel graph, which is what the gate judges against. kernelGraphOnly is what the create path read before 0.4.51 — a difference between them is a property that WOULD have been minted into the type namespace and refused.');
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp.project_resolve(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  CANON text := '^[a-z0-9]+(-[a-z0-9]+)*$';
  v_seg text := COALESCE(p_payload->>'segment', ckp._project());
  v_ex  jsonb;
BEGIN
  -- 0.4.56: ASK THE RESOLVER, DO NOT RE-DERIVE IT. This used to infer the clause
  -- from the outcome and got it wrong the moment a clause was added — reporting
  -- "the one CANONICAL sealed kernel" for a resolution that came off a kernel
  -- GRAPH, with sealedKernelsMatching [] printed beneath it. The explanation is
  -- now a field of the decision, so the two cannot drift.
  PERFORM set_config('ckp.project', v_seg, true);
  BEGIN
    v_ex := ckp._project_explain();
  EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('ok', true, 'segment', v_seg, 'resolves', null,
      'refused', true, 'canonical', (v_seg ~ CANON), 'reason', SQLERRM,
      'note', 'a refusal IS the result. One kernel has one spelling; this name resolves to none or to more than one.');
  END;
  RETURN jsonb_build_object('ok', true, 'segment', v_seg,
    'resolves', v_ex->>'project', 'clause', v_ex->>'clause',
    'canonical', (v_seg ~ CANON), 'matched', COALESCE(v_ex->'hits', '[]'::jsonb),
    'note', 'the answer AND the reason come from ckp._project_explain itself, never a copy of its rules.');
END;
$function$
;

-- 0.4.71 — the engine's silent-incompleteness counters, guarded. NULL means the
-- engine cannot answer, and per R-11 a caller must then say UNKNOWN — never
-- complete. Used by the census verbs to compute per-call deltas.
CREATE OR REPLACE FUNCTION ckp._engine_counters()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE v jsonb;
BEGIN
  BEGIN
    SELECT jsonb_build_object(
      'truncations', (pgrdf.stats()->>'path_depth_truncations')::bigint,
      'filtersDropped', (pgrdf.stats()->>'filter_clauses_dropped')::bigint)
    INTO v;
  EXCEPTION WHEN OTHERS THEN
    RETURN NULL;
  END;
  RETURN v;
END;
$function$
;

-- 0.4.61 — adoption.check: is any adopted module still what it was at first
-- sight, and is the sealed pin verifiable at all? Answers ck-dev's Cluster-F
-- defect (defect-1786649168553127000: a sourceDigest of 64 zeros composes) the
-- honest way: per adopted module, the FILE-BYTE sourceDigest is reported as
-- verifiable:false with the reason (triples cannot recompute file bytes — that
-- verification belongs to whatever loads the file), and the GRAPH digest is
-- compared against the pin taken at first composition, so a swapped or drifted
-- module is DETECTED from adoption onward. Reports, never gates (B4).
CREATE OR REPLACE FUNCTION ckp.adoption_check(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  N text := 'https://conceptkernel.org/ontology/v3.11/core#';
  v_proj text := ckp._project();
  v_iri  text;
  v_rows jsonb := '[]'::jsonb;
  v_pin  text; v_now text; v_drift boolean := false;
  -- 0.4.71 — pgRDF#118 CONSUMED: since engine 0.6.31 the loader records the
  -- exact input bytes' sha256 on _pgrdf_graphs (turtle funnel; staged/bulk/
  -- nquads do not yet — the boundary their PR states). When the column exists,
  -- the sealed Adoption's file-byte sourceDigest stops being decorative: it is
  -- COMPARED against what the loader measured. Guarded: on an older engine
  -- the fields read null and verifiable stays false with the old reason.
  v_has_src boolean := EXISTS (SELECT 1 FROM information_schema.columns
    WHERE table_schema='pgrdf' AND table_name='_pgrdf_graphs' AND column_name='source_sha256');
  v_src text; v_loads int; v_sealed_src text;
BEGIN
  FOREACH v_iri IN ARRAY ckp._adopted_graphs(v_proj) LOOP
    SELECT graph_digest INTO v_pin FROM ckp.adoption_pins WHERE graph_iri = v_iri;
    v_now := ckp._surface_digest(pgrdf.add_graph(v_iri));
    IF v_pin IS NOT NULL AND v_pin <> v_now THEN v_drift := true; END IF;
    v_src := NULL; v_loads := NULL;
    IF v_has_src THEN
      SELECT g.source_sha256, g.source_loads INTO v_src, v_loads
        FROM pgrdf._pgrdf_graphs g WHERE g.iri = v_iri;
    END IF;
    SELECT a.body->>(N||'sourceDigest') INTO v_sealed_src FROM ckp.instances a
      WHERE a.body->>'type' = N||'Adoption' AND a.body->>(N||'adopts') = v_iri
      ORDER BY a.ts_created DESC LIMIT 1;
    v_rows := v_rows || jsonb_build_object(
      'module', v_iri,
      'graphDigestNow', v_now,
      'graphDigestPinned', v_pin,
      'drifted', (v_pin IS NOT NULL AND v_pin <> v_now),
      -- 0.4.67: the structural plane, reported beside the copy plane. This is
      -- the value a party on ANOTHER store compares (finding-1786716790912211000:
      -- no consumer read path exposed a composed module's digest — this is that
      -- path, both planes, counts included). NULL structural pin = pinned
      -- before the structural plane existed; re-pins at next fresh composition.
      'structuralDigestNow', ckp._structural_digest(pgrdf.add_graph(v_iri)),
      'structuralDigestPinned', (SELECT p.structural_digest FROM ckp.adoption_pins p WHERE p.graph_iri = v_iri),
      'counts', (SELECT jsonb_build_object('nodeshapes', p.nodeshapes, 'properties', p.properties, 'asserted', p.asserted)
                   FROM ckp.adoption_pins p WHERE p.graph_iri = v_iri),
      'sourceDigest', (SELECT a.body->>(N||'sourceDigest') FROM ckp.instances a
                        WHERE a.body->>'type' = N||'Adoption'
                          AND a.body->>(N||'adopts') = v_iri
                        ORDER BY a.ts_created DESC LIMIT 1),
      'sourceRecorded',  v_src,
      'sourceLoads',     v_loads,
      'sourceDigestVerifiable', (v_src IS NOT NULL),
      'sourceDigestMatch', CASE WHEN v_src IS NULL OR v_sealed_src IS NULL THEN NULL
                                ELSE (v_src = v_sealed_src) END,
      -- 0.4.72: the why names ROW-state separately from ENGINE-capability —
      -- 0.4.71's two-branch text blamed the engine for a null that only meant
      -- "this graph predates recording or took an unrecorded path" (measured
      -- live: verdict said recording exists while row-why said it did not).
      'why', CASE WHEN v_src IS NOT NULL
        THEN 'the LOADER measured these bytes (pgRDF#118, engine >= 0.6.31): sourceRecorded is the sha256 of the exact input the parser consumed, sourceLoads > 1 self-reports that whole-graph byte identity no longer holds. sourceDigestMatch compares the sealed Adoption claim against the loader record — false is a finding, null means one side is absent.'
        WHEN v_has_src
        THEN 'this ENGINE records loader-side digests (pgRDF#118), but THIS graph has no record — loaded before recording existed, or via an unrecorded path (staged/bulk/nquads, the pgRDF#120 coverage boundary). A re-load through the turtle funnel would record. The null is the row''s history, not the engine''s capability.'
        ELSE 'sourceDigest is a FILE-BYTE sha256; a graph cannot recompute file bytes, and this engine does not record loader-side digests (pgRDF#118 lands at 0.6.31). The substrate''s halves: the COPY pin detects in-store drift; the STRUCTURAL pin survives reload. Equal structural digests are evidence, not proof; unequal ARE proof of difference.' END);
  END LOOP;
  RETURN jsonb_build_object('ok', true, 'kernel', v_proj,
    'modules', v_rows, 'drifted', v_drift,
    'completeness', jsonb_build_object(
      'verdict', CASE WHEN v_has_src THEN 'complete for recorded loads'
                      ELSE 'UNKNOWN — engine predates loader-side recording' END,
      'counters', ckp._engine_counters()),
    'note', 'drifted:true means an adopted module''s graph no longer matches its first-composition pin — the module was swapped or edited under an unsuperseded Adoption. A legitimate update arrives as a NEW Adoption + Supersession, which re-pins.');
END;
$function$
;

-- 0.4.67 — surface.grounding: the three-digest-plane census of this kernel's
-- ground, as a verb (a check that is not a verb does not exist). Per graph in
-- the kernel's world — composed surface, own kernel graph, every adopted
-- module — the existential census (ground/bnode triples, distinct blanks), the
-- COPY digest (this store's bytes, moves on reload), the STRUCTURAL digest
-- (survives reload, fleet algorithm), and the blank-node-immune counts. This is
-- how a kernel grounds itself in the founding graphs and how a brought graph is
-- examined at the door before adoption (the §14.3 admission contract's
-- fingerprint gate, at pgck's door).
CREATE OR REPLACE FUNCTION ckp.surface_grounding(p_payload jsonb, p_project text DEFAULT NULL)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  v_proj text := COALESCE(p_project, ckp._project());
  v_iris text[];
  v_iri  text;
  v_g    bigint;
  v_rows jsonb := '[]'::jsonb;
BEGIN
  -- an explicit {iri} examines ONE graph (the brought-graph admission read);
  -- with no payload the kernel's whole ground is censused.
  IF COALESCE(btrim(p_payload->>'iri'),'') <> '' THEN
    v_iris := ARRAY[p_payload->>'iri'];
  ELSE
    v_iris := ARRAY[format('urn:ckp:%s/shapes/composed', v_proj),
                    format('urn:ckp:%s/kernel/ck', v_proj)]
              || ckp._adopted_graphs(v_proj);
  END IF;
  FOREACH v_iri IN ARRAY v_iris LOOP
    v_g := pgrdf.add_graph(v_iri);
    v_rows := v_rows || (
      SELECT jsonb_build_object(
        'iri', v_iri,
        'asserted',        count(*),
        -- 0.4.76 — the entailed plane, reported rather than filtered away. Every
        -- other count here is asserted-only BY DESIGN; this one is its complement,
        -- so a caller can see whether the reasoner has ever run over this graph
        -- without borrowing an instrument it does not have.
        'inferred',        (SELECT count(*) FROM pgrdf._pgrdf_quads qi
                             WHERE qi.graph_id = v_g AND qi.is_inferred),
        'groundTriples',   count(*) FILTER (WHERE s.term_type <> 2 AND o.term_type <> 2),
        'bnodeTriples',    count(*) FILTER (WHERE s.term_type = 2 OR o.term_type = 2),
        'distinctBnodes',  (SELECT count(DISTINCT d) FROM (
                              SELECT q2.subject_id d FROM pgrdf._pgrdf_quads q2
                                JOIN pgrdf._pgrdf_dictionary s2 ON s2.id = q2.subject_id
                               WHERE q2.graph_id = v_g AND NOT q2.is_inferred AND s2.term_type = 2
                              UNION
                              SELECT q3.object_id FROM pgrdf._pgrdf_quads q3
                                JOIN pgrdf._pgrdf_dictionary o3 ON o3.id = q3.object_id
                               WHERE q3.graph_id = v_g AND NOT q3.is_inferred AND o3.term_type = 2) u),
        'copyDigest',       ckp._surface_digest(v_g),
        'structuralDigest', ckp._structural_digest(v_g),
        -- 0.4.68 — COUNTS NAME THEIR METHOD (F3: two shape counts disagreed in
        -- the same instant because neither named its method; this verb shipped
        -- a third). Measured on the founding graphs, three methods, three
        -- numbers: declared vocabulary properties 80/33/17 (the fleet's
        -- arithmetic), asserted property shapes 107/44/10, sh:path rows with
        -- inferred = a fourth. All counts here are ASSERTED-ONLY and distinct.
        'nodeshapes', (SELECT count(DISTINCT q4.subject_id) FROM pgrdf._pgrdf_quads q4
           JOIN pgrdf._pgrdf_dictionary p4 ON p4.id = q4.predicate_id
           JOIN pgrdf._pgrdf_dictionary o4 ON o4.id = q4.object_id
          WHERE q4.graph_id = v_g AND NOT q4.is_inferred
            AND p4.lexical_value = 'http://www.w3.org/1999/02/22-rdf-syntax-ns#type'
            AND o4.lexical_value = 'http://www.w3.org/ns/shacl#NodeShape'),
        'propertyShapes', (SELECT count(DISTINCT q5.subject_id) FROM pgrdf._pgrdf_quads q5
           JOIN pgrdf._pgrdf_dictionary p5 ON p5.id = q5.predicate_id
          WHERE q5.graph_id = v_g AND NOT q5.is_inferred
            AND p5.lexical_value = 'http://www.w3.org/ns/shacl#path'),
        'declaredProperties', (SELECT count(DISTINCT q6.subject_id) FROM pgrdf._pgrdf_quads q6
           JOIN pgrdf._pgrdf_dictionary p6 ON p6.id = q6.predicate_id
           JOIN pgrdf._pgrdf_dictionary o6 ON o6.id = q6.object_id
          WHERE q6.graph_id = v_g AND NOT q6.is_inferred
            AND p6.lexical_value = 'http://www.w3.org/1999/02/22-rdf-syntax-ns#type'
            AND o6.lexical_value IN ('http://www.w3.org/2002/07/owl#DatatypeProperty',
                                     'http://www.w3.org/2002/07/owl#ObjectProperty',
                                     'http://www.w3.org/2002/07/owl#AnnotationProperty',
                                     'http://www.w3.org/1999/02/22-rdf-syntax-ns#Property')))
      FROM pgrdf._pgrdf_quads q
      JOIN pgrdf._pgrdf_dictionary s ON s.id = q.subject_id
      JOIN pgrdf._pgrdf_dictionary o ON o.id = q.object_id
      WHERE q.graph_id = v_g AND NOT q.is_inferred);
  END LOOP;
  RETURN jsonb_build_object('ok', true, 'kernel', v_proj, 'graphs', v_rows,
    'planes', 'FILE digests pin published bytes (verify with shasum against the sidecar). copyDigest pins THIS store''s bytes and moves on every reload — in-store drift detection only, never cross-bench identity. structuralDigest survives reload (first-degree blank-node signatures, the fleet algorithm) — what a third party recomputes from the published modules. Counts are the blank-node-immune instrument and NAME THEIR METHOD: nodeshapes (asserted sh:NodeShape typing; 42 = 27 core + 11 wave + 4 lexicon fully adopted) · declaredProperties (asserted owl/rdf property declarations; 130 = 80 + 33 + 17) · propertyShapes (asserted distinct sh:path subjects). asserted counts ASSERTED-ONLY quads; inferred (0.4.76) counts ENTAILED quads — the reasoner''s output for this graph, whole and NOT deduplicated against asserted, so asserted+inferred is the store total. A count without its method is not a number (F3).',
    'inferredNote', 'inferred = 0 on a POPULATED graph is a positive finding, not an absence of data: nothing has ever been derived from those facts. lexicon#Pattern declares that membership is INFERRED from the symptom and never asserted, so a lexicon teaching cannot be earned on a graph whose inferred count is 0.',
    'verdictAsymmetry', 'unequal structural digests PROVE two graphs differ; equal ones are strong evidence of isomorphism and NOT proof (not RDFC-1.0). Never upgrade ISOMORPHIC_LIKELY to identical.');
END;
$function$
;

-- 0.4.72 — fleet.adoptions: the cross-kernel adoption matrix as a verb (vision
-- §2.1, scope reduced to exactly what neither shapes nor obligations can see:
-- facts spanning kernels). Every unsuperseded Adoption fleet-wide, with the
-- validity of its REFERENCE checked mechanically — the census that caught
-- ontosys by hand becomes re-runnable by anyone. A report, never a gate.
CREATE OR REPLACE FUNCTION ckp.fleet_adoptions(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  N text := 'https://conceptkernel.org/ontology/v3.11/core#';
  v_rows jsonb;
  v_bad  int;
BEGIN
  SELECT COALESCE(jsonb_agg(row ORDER BY row->>'intoProject', row->>'adopts'), '[]'::jsonb),
         COALESCE(sum(CASE WHEN (row->>'malformed')::boolean THEN 1 ELSE 0 END), 0)
    INTO v_rows, v_bad
  FROM (
    SELECT jsonb_build_object(
      'adoption',   a.id,
      'intoProject', a.body->>(N||'intoProject'),
      'adopts',      a.body->>(N||'adopts'),
      'sealedBy',    a.body->>(N||'createdBy'),
      'graphQuads',  (SELECT count(*) FROM pgrdf._pgrdf_quads q
                        JOIN pgrdf._pgrdf_graphs g ON g.graph_id = q.graph_id
                       WHERE g.iri = a.body->>(N||'adopts') AND NOT q.is_inferred),
      'malformed',   NOT EXISTS (SELECT 1 FROM pgrdf._pgrdf_quads q2
                        JOIN pgrdf._pgrdf_graphs g2 ON g2.graph_id = q2.graph_id
                       WHERE g2.iri = a.body->>(N||'adopts') AND NOT q2.is_inferred),
      'structuralPin', (SELECT p.structural_digest FROM ckp.adoption_pins p
                         WHERE p.graph_iri = a.body->>(N||'adopts'))) AS row
    FROM ckp.instances a
    WHERE a.body->>'type' = N||'Adoption'
      AND NOT EXISTS (SELECT 1 FROM ckp.instances s
                       WHERE s.body->>'type' = N||'Supersession'
                         AND s.body->>(N||'supersedes') = a.body->>'@id')
  ) sub;
  RETURN jsonb_build_object('ok', true,
    'adoptions', v_rows,
    'malformedCount', v_bad,
    'note', 'malformed:true = the adopts IRI names NO non-empty graph in this store — a judged Adoption composing NOTHING (module-IRI-is-graph-IRI; the namespace-instead-of-graph and blank-adopts classes). The cure is Supersession + a fresh Adoption naming the module GRAPH IRI. Per-kernel enforcement of this exists as the adopts-resolves obligation, adopted by agreement.',
    'completeness', jsonb_build_object(
      'verdict', 'complete for sealed, unsuperseded Adoptions in this store',
      'counters', ckp._engine_counters()));
END;
$function$
;

-- 0.4.72 — surface.explain: the shape teaches its PROSE, not just its contract
-- (SAH3000's lesson: no door verb read rdfs:comment — the teaching was
-- reachable only by hand-written SPARQL, which is a check that is not a verb).
-- For a type: its class comment plus every declared property with its comment.
-- Asserted-only, from the composed surface — what the gate judges is what the
-- prose explains.
CREATE OR REPLACE FUNCTION ckp.surface_explain(p_payload jsonb, p_project text DEFAULT NULL)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  v_proj text := COALESCE(p_project, ckp._project());
  v_type text := COALESCE(p_payload->>'type', p_payload->>'@type');
  v_comp bigint;
  v_map  jsonb;
  v_props jsonb;
BEGIN
  IF v_type IS NULL OR btrim(v_type) = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'type_required',
      'hint', 'surface.explain {"type": "<class IRI>"} — the declared contract WITH its teaching prose');
  END IF;
  -- 0.4.81 — REFUSE A CURIE INSTEAD OF ANSWERING VACUOUSLY. `ckp:Project` is a
  -- prefixed name, not an IRI; the composed surface holds only absolute IRIs, so
  -- it matched nothing and this verb replied `declared: {}` / `admitted: false`
  -- — a confident answer that the type is unknown, about a type the gate judges
  -- every day. A caller learns a FALSE contract and cannot tell it from a real
  -- absence. An absolute IRI here carries :// or begins urn: ; anything else is
  -- a prefix this substrate never expands.
  IF v_type IS NOT NULL AND v_type NOT LIKE '%://%' AND v_type NOT LIKE 'urn:%' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'type_is_a_curie', 'type', v_type,
      'hint', 'this looks like a prefixed name (CURIE), not an IRI. Nothing expands prefixes here — pass the absolute IRI, e.g. https://conceptkernel.org/ontology/v3.11/core#Project rather than ckp:Project.');
  END IF;
  v_comp := ckp._composed_shapes(v_proj);
  v_map  := ckp._propmap(v_type, v_proj);
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'name', k, 'path', v_map->>k,
           'comment', (SELECT o.lexical_value FROM pgrdf._pgrdf_quads q
                         JOIN pgrdf._pgrdf_dictionary s ON s.id = q.subject_id
                         JOIN pgrdf._pgrdf_dictionary p ON p.id = q.predicate_id
                         JOIN pgrdf._pgrdf_dictionary o ON o.id = q.object_id
                        WHERE q.graph_id = v_comp AND NOT q.is_inferred
                          AND s.lexical_value = v_map->>k
                          AND p.lexical_value = 'http://www.w3.org/2000/01/rdf-schema#comment'
                        LIMIT 1)) ORDER BY k), '[]'::jsonb)
    INTO v_props
  FROM jsonb_object_keys(v_map) k;
  RETURN jsonb_build_object('ok', true, 'type', v_type, 'kernel', v_proj,
    'comment', (SELECT o.lexical_value FROM pgrdf._pgrdf_quads q
                  JOIN pgrdf._pgrdf_dictionary s ON s.id = q.subject_id
                  JOIN pgrdf._pgrdf_dictionary p ON p.id = q.predicate_id
                  JOIN pgrdf._pgrdf_dictionary o ON o.id = q.object_id
                 WHERE q.graph_id = v_comp AND NOT q.is_inferred
                   AND s.lexical_value = v_type
                   AND p.lexical_value = 'http://www.w3.org/2000/01/rdf-schema#comment'
                 LIMIT 1),
    'properties', v_props,
    'note', 'comments are read from the COMPOSED surface, asserted-only — what the gate judges is what this prose explains. A property with a null comment is declared but untaught; that gap is the module author''s, and now it is visible.');
END;
$function$
;

-- P0-E (pgCK#28): a deterministic digest of a shapes graph — sha256 over the
-- s|p|o triples in sorted order. Re-derivable by anyone re-running it against
-- the same graph, so a Materialization's surfaceDigest is a CHECKABLE claim
-- ("re-derive the surface at that epoch"), not a trusted number. 64 lowercase
-- hex, matching ckp:surfaceDigest's sh:pattern. 0.4.67 names its plane: this is
-- the COPY digest (blank-node labels included — parse-scoped); its
-- reload-surviving sibling is ckp._structural_digest.
CREATE OR REPLACE FUNCTION ckp._surface_digest(p_graph bigint)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE v_iri text; v_concat text;
BEGIN
  v_iri := pgrdf.graph_iri(p_graph);
  SELECT COALESCE(string_agg(
           (j->>'s')||'|'||(j->>'p')||'|'||(j->>'o'), chr(10)
           ORDER BY (j->>'s'), (j->>'p'), (j->>'o')), '')
    INTO v_concat
  FROM pgrdf.sparql(format(
    'SELECT ?s ?p ?o WHERE { GRAPH <%s> { ?s ?p ?o } }', v_iri)) j;
  RETURN encode(digest(convert_to(v_concat, 'UTF8'), 'sha256'), 'hex');
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp._structural_digest(p_graph bigint)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
-- 0.4.67 — THE STRUCTURAL PLANE (§5b alignment, finding-1786862028710113000).
--
-- _surface_digest is the COPY plane: sha256 over rendered lines with blank-node
-- LABELS included, so it moves on every reload and no third party can recompute
-- it from published files. This is the plane that survives: each blank node is
-- replaced by a signature over its own incident triples (itself marked _:a,
-- every other blank node flattened to _:z), so the digest depends on the shape
-- a node sits in and never on the label it happened to receive.
--
-- THE ALGORITHM IS THE FLEET'S, byte-for-byte — method label pgrdf-fd1-sha256,
-- owned by the engine since pgRDF v0.6.34 as pgrdf.structural_digest(). (An
-- earlier revision of this comment cited "pgrdf_fingerprint", a function that
-- existed in no schema — the exact folklore-citation class pgRDF's L7 measured;
-- corrected 2026-08-26. Delegating this body to the engine is FINAL-HANDOVER B1.)
--   ground     = sorted lines with no blank node, joined by \n, sha256
--   sig(b)     = sha256 of b's incident lines (self→_:a, other→_:z), sorted
--   bnode      = sha256 of the sorted signature hexes, joined by \n
--   structural = sha256( ground_text || '\n--\n' || signature_hexes )
-- ACCEPTANCE, measured 2026-08-16: three independent loads of the v3.11 core
-- (bench urn:ckp:core, bench urn:ckp:core/v3.11, test-rig urn:ckp:core) carry
-- three different byte digests and ONE structural digest, 9a791c6c3d6d07cb… —
-- reproduced by this function against the client-side tool's published pins.
--
-- HONEST LIMITS, never to be flattened: this is FIRST-DEGREE hashing, not
-- RDFC-1.0 — equal digests are strong evidence of isomorphism, NOT proof
-- (symmetric blank-node structures can collide); unequal digests ARE proof of
-- difference. ASSERTED ONLY — inferred triples re-derive and are a check
-- value, never content.
--
-- INTERIM SEAT: reads the engine's quad/dictionary tables directly because the
-- public SPARQL surface cannot exclude inferred triples. The coupling is pinned
-- by the co-shipped bundle and fails LOUD on schema drift; pgRDF#117
-- (pgrdf.graph_digest, RDFC-1.0) retires this function's body.
DECLARE
  v_ground text;
  v_sigs   text;
BEGIN
  IF to_regclass('pgrdf._pgrdf_quads') IS NULL OR to_regclass('pgrdf._pgrdf_dictionary') IS NULL THEN
    RAISE EXCEPTION 'ckp._structural_digest: the engine''s quad/dictionary tables are not where the pinned bundle put them — refusing rather than inventing a digest (interim seat; pgRDF#117 is the lasting one)';
  END IF;
  WITH t AS (
    SELECT x.subject_id sid, x.object_id oid, s.term_type st, o.term_type ot,
      CASE s.term_type WHEN 1 THEN '<'||s.lexical_value||'>' WHEN 2 THEN '_:'||s.lexical_value
        ELSE '"'||replace(replace(s.lexical_value, chr(92), chr(92)||chr(92)), '"', chr(92)||'"')||'"' END AS sr,
      CASE p.term_type WHEN 1 THEN '<'||p.lexical_value||'>' WHEN 2 THEN '_:'||p.lexical_value
        ELSE '"'||replace(replace(p.lexical_value, chr(92), chr(92)||chr(92)), '"', chr(92)||'"')||'"' END AS pr,
      CASE o.term_type WHEN 1 THEN '<'||o.lexical_value||'>' WHEN 2 THEN '_:'||o.lexical_value
        ELSE '"'||replace(replace(replace(o.lexical_value, chr(92), chr(92)||chr(92)), '"', chr(92)||'"'), chr(10), chr(92)||'n')||'"'
          || coalesce('@'||o.language_tag,
               CASE WHEN dt.lexical_value IS NOT NULL AND dt.lexical_value <> 'http://www.w3.org/2001/XMLSchema#string'
                    THEN '^^<'||dt.lexical_value||'>' END, '') END AS orr
    FROM pgrdf._pgrdf_quads x
    JOIN pgrdf._pgrdf_dictionary s ON s.id = x.subject_id
    JOIN pgrdf._pgrdf_dictionary p ON p.id = x.predicate_id
    JOIN pgrdf._pgrdf_dictionary o ON o.id = x.object_id
    LEFT JOIN pgrdf._pgrdf_dictionary dt ON dt.id = o.datatype_iri_id
    WHERE x.graph_id = p_graph AND NOT x.is_inferred
  ),
  ground AS (
    SELECT string_agg(sr||' '||pr||' '||orr||' .', E'\n' ORDER BY (sr||' '||pr||' '||orr||' .') COLLATE "C") AS g
    FROM t WHERE st <> 2 AND ot <> 2
  ),
  bnodes AS (
    SELECT DISTINCT sid AS b FROM t WHERE st = 2
    UNION SELECT DISTINCT oid FROM t WHERE ot = 2
  ),
  incident AS (
    SELECT b.b,
      CASE WHEN t.st=2 THEN CASE WHEN t.sid=b.b THEN '_:a' ELSE '_:z' END ELSE t.sr END
      ||' '||t.pr||' '||
      CASE WHEN t.ot=2 THEN CASE WHEN t.oid=b.b THEN '_:a' ELSE '_:z' END ELSE t.orr END
      ||' .' AS nline
    FROM bnodes b JOIN t ON (t.st=2 AND t.sid=b.b) OR (t.ot=2 AND t.oid=b.b)
  ),
  sigs AS (
    SELECT encode(digest(convert_to(string_agg(nline, E'\n' ORDER BY nline COLLATE "C"),'UTF8'),'sha256'),'hex') AS sig
    FROM incident GROUP BY b
  )
  SELECT COALESCE((SELECT g FROM ground), ''),
         COALESCE((SELECT string_agg(sig, E'\n' ORDER BY sig COLLATE "C") FROM sigs), '')
    INTO v_ground, v_sigs;
  RETURN encode(digest(convert_to(v_ground||E'\n--\n'||v_sigs, 'UTF8'), 'sha256'), 'hex');
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp._envelope(p_id text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
  SELECT jsonb_build_object('id', i.id, 'type', i.body->>'type', 'body', i.body,
    'verified', ckp.verify(i.id),
    'proof_digest', (SELECT digest FROM ckp.proof p WHERE p.about=i.id ORDER BY p.id DESC LIMIT 1),
    'ts', i.ts_created)
  FROM ckp.instances i WHERE i.id = p_id
$function$
;

CREATE OR REPLACE FUNCTION ckp._epsilon_materialize(p_concept text, p_scope jsonb, p_formula text, p_epoch bigint)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  MP   text := 'urn:ckp:mat/';
  wm   bigint := ckp._source_watermark(p_scope);
  giri text := 'urn:ckp:phenotype/'||ckp._slug(p_concept)||'/'||p_epoch||'/'||wm;
  ttl  text := '';
  sqltext text;
  r record;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(p_concept||':'||p_epoch||':'||wm, 0));
  IF EXISTS (SELECT 1 FROM ckp.phenotype_ptr WHERE concept=p_concept AND epoch=p_epoch AND watermark=wm) THEN
    RETURN (SELECT graph_iri FROM ckp.phenotype_ptr WHERE concept=p_concept);
  END IF;
  -- evaluate the sealed formula per in-scope item (dynamic SQL over the sealed expression)
  sqltext := format(
    'SELECT i.id AS id, (%s) AS c FROM ckp.instances i WHERE ($1->>''type'' IS NULL OR i.body->>''type''=$1->>''type'') '
    'AND ($1->>''about'' IS NULL OR i.body->>($1->>''about_prop'')=$1->>''about'')', p_formula);
  FOR r IN EXECUTE sqltext USING p_scope LOOP
    ttl := ttl || '<urn:ckp:mat:'||ckp._slug(r.id)||'> <'||MP||'contrib> "'||r.c
                || '"^^<http://www.w3.org/2001/XMLSchema#decimal> ; <'||MP||'contrib_abs> "'||abs(r.c)
                || '"^^<http://www.w3.org/2001/XMLSchema#decimal> . ';
  END LOOP;
  PERFORM pgrdf.parse_turtle(ttl, pgrdf.add_graph(giri), MP);
  RETURN giri;
END $function$
;

CREATE OR REPLACE FUNCTION ckp._graph_apply(p_src_graph integer, p_dst_graph integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
BEGIN
  PERFORM pgrdf.copy_graph(p_src_graph, p_dst_graph);
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp._ledger_read(p_instance_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
BEGIN
  RETURN jsonb_build_object(
    'id', p_instance_id,
    'ledger', COALESCE((SELECT jsonb_agg(jsonb_build_object(
                'seq', seq, 'prev_seq', prev_seq, 'body_sha256', body_sha256, 'ts', ts) ORDER BY seq)
              FROM ckp.ledger WHERE instance_id = p_instance_id), '[]'::jsonb),
    'proof', (SELECT jsonb_build_object('digest', digest, 'method', method, 'verified_at', verified_at)
              FROM ckp.proof WHERE about = p_instance_id ORDER BY id DESC LIMIT 1));
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp._materialize(p_graph integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
BEGIN
  PERFORM pgrdf.materialize(p_graph);
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp._op_to_ttl(p_prop jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  C          text := 'https://conceptkernel.org/ontology/v3.11/core#';
  v_iri_re   text := '^[A-Za-z][A-Za-z0-9+.:#/_-]*$';
  v_state_re text := '^[A-Za-z][A-Za-z0-9_-]*$';            -- state names (no quote/space)
  v_op       text := p_prop->>(C||'proposalOp');
  v_detail   jsonb := COALESCE(p_prop->'proposalDetail', '{}'::jsonb);
  v_class    text;
  v_path     text;
  v_min      int;
  v_dtype    text;
  v_dt_line  text := '';
  v_map      jsonb;
  v_fs       text;
  v_ts       text;
  v_ttl      text;
  -- 0.4.67 — NAMED SHAPES, NEVER BRACKETS. The `[ a sh:NodeShape … ]` form
  -- minted an anonymous NodeShape into the KERNEL graph — a blank node in the
  -- doctrine. That breaks two things at once: the doctrine stops being
  -- byte-pinnable (existential-free is the fleet rule, measured 22/22 ground
  -- on this kernel), and a shape nobody can name can never be superseded by
  -- name. Caught by the rule BEFORE any governed add_class ever fired on a
  -- live kernel — the first prevented defect of the alignment. The shape IRI
  -- is deterministic (project + local names + an 8-hex discriminator over the
  -- full IRIs), so re-applying the same op re-emits the same subject.
  -- Project segment from the SEALED producedBy — server-derived, never parsed
  -- from a caller field.
  v_seg      text := (regexp_match(COALESCE(p_prop->>(C||'producedBy'),''), '^urn:ckp:([^/]+)/kernel'))[1];
  v_shape    text;
BEGIN
  IF v_op = 'add_property' THEN
    v_class := v_detail->>'targetClass';
    v_path  := v_detail->>'path';
    IF v_class IS NULL OR v_class !~ v_iri_re THEN
      RAISE EXCEPTION 'add_property: targetClass must be an IRI, got %', v_class; END IF;
    IF v_path IS NULL OR v_path !~ v_iri_re THEN
      RAISE EXCEPTION 'add_property: path must be an IRI, got %', v_path; END IF;
    BEGIN
      v_min := COALESCE((v_detail->>'minCount')::int, 1);
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'add_property: minCount must be an integer, got %', v_detail->>'minCount'; END;
    v_dtype := v_detail->>'datatype';
    IF v_dtype IS NOT NULL THEN
      IF v_dtype !~ v_iri_re THEN RAISE EXCEPTION 'add_property: datatype must be an IRI, got %', v_dtype; END IF;
      v_dt_line := ' ; sh:datatype <'||v_dtype||'>';
    END IF;
    IF v_seg IS NULL THEN
      RAISE EXCEPTION 'add_property: cannot derive the project segment from the proposal''s producedBy — a shape must be NAMED into a kernel graph, never anonymous'; END IF;
    v_shape := format('urn:ckp:%s/shape/%s--%s--%s', v_seg,
                      ckp._slug(regexp_replace(v_class,'^.*[/#:]','')),
                      ckp._slug(regexp_replace(v_path,'^.*[/#:]','')),
                      left(md5(v_class||'|'||v_path),8));
    -- the PROPERTY shape is named too — `sh:property [ … ]` would put the
    -- blank node right back into the doctrine through the inner bracket.
    RETURN '@prefix sh: <http://www.w3.org/ns/shacl#> .'||chr(10)||
           '<'||v_shape||'> a sh:NodeShape ; sh:targetClass <'||v_class||'> ; '||
           'sh:property <'||v_shape||'/p> .'||chr(10)||
           '<'||v_shape||'/p> sh:path <'||v_path||'> ; sh:minCount '||v_min::text||v_dt_line||' .';

  ELSIF v_op = 'add_class' THEN
    v_class := COALESCE(v_detail->>'class', v_detail->>'targetClass', p_prop->>(C||'about'));
    IF v_class IS NULL OR v_class !~ v_iri_re THEN
      RAISE EXCEPTION 'add_class: class must be an IRI, got %', v_class; END IF;
    -- detail.properties[] WAS ACCEPTED AND SILENTLY DROPPED. The op emitted one
    -- quad (<class> a owl:Class) and reported graph_changed:true, so a caller
    -- who declared constraints got a class carrying none and no complaint --
    -- the same family as detail/proposalDetail and the inert epoch. Reported by
    -- pgCK.MCP against urn:ckp:pgck-mcp/type/ToolProjection: two property
    -- shapes sent, one quad applied, nothing validatable.
    --
    -- Emit the NodeShape too, with the same per-property gate add_property uses.
    -- A malformed property is REFUSED here, never dropped: silently narrowing a
    -- shape is un-enforcement nobody sees.
    IF v_seg IS NULL THEN
      RAISE EXCEPTION 'add_class: cannot derive the project segment from the proposal''s producedBy — a shape must be NAMED into a kernel graph, never anonymous'; END IF;
    v_shape := format('urn:ckp:%s/shape/%s--%s', v_seg,
                      ckp._slug(regexp_replace(v_class,'^.*[/#:]','')),
                      left(md5(v_class),8));
    v_ts := ''; v_ttl := '';
    IF jsonb_typeof(v_detail->'properties') = 'array' THEN
      FOR v_map IN SELECT jsonb_array_elements(v_detail->'properties') LOOP
        v_path := v_map->>'path';
        IF v_path IS NULL OR v_path !~ v_iri_re THEN
          RAISE EXCEPTION 'add_class: property path must be an IRI, got %', v_path; END IF;
        BEGIN
          v_min := COALESCE((v_map->>'minCount')::int, 1);
        EXCEPTION WHEN OTHERS THEN
          RAISE EXCEPTION 'add_class: property minCount must be an integer, got %', v_map->>'minCount'; END;
        v_dtype := v_map->>'datatype';
        v_dt_line := '';
        IF v_dtype IS NOT NULL THEN
          IF v_dtype !~ v_iri_re THEN
            RAISE EXCEPTION 'add_class: property datatype must be an IRI, got %', v_dtype; END IF;
          v_dt_line := ' ; sh:datatype <'||v_dtype||'>';
        END IF;
        -- named property shapes (…/p0, /p1, …): the inner bracket was the
        -- other half of the bnode emission — see the DECLARE note.
        v_fs := v_shape||'/p'||left(md5(v_path),8);
        v_ts := v_ts||' ; sh:property <'||v_fs||'>';
        v_ttl := v_ttl||'<'||v_fs||'> sh:path <'||v_path||'> ; sh:minCount '||v_min::text||v_dt_line||' .'||chr(10);
      END LOOP;
    END IF;
    IF v_ts = '' THEN
      -- bare declaration: a building block for a following add_property. NOTE it
      -- is admitted the moment it lands (_type_admitted accepts `a owl:Class`),
      -- so until a shape targets it an instance of this type validates
      -- VACUOUSLY. That window is a doctrine question, not a projector bug.
      RETURN '@prefix owl: <http://www.w3.org/2002/07/owl#> .'||chr(10)||
             '<'||v_class||'> a owl:Class .';
    END IF;
    -- 0.4.71 — A SHAPE CAN BE LOCKED AND ENFORCED: detail.closed = true emits
    -- sh:closed with sh:ignoredProperties, so an undeclared key REFUSES at the
    -- gate instead of minting into the type namespace. The default ignore list
    -- is the substrate envelope — rdf:type, the four server stamps,
    -- participant, and the board timestamps — because those are derived onto
    -- every candidate and a closed shape that forgets them refuses EVERYTHING
    -- (the total-write-outage-presenting-as-bad-data class). Callers extend it
    -- via detail.ignoredProperties (IRIs, gated). Closing a FLEET type demands
    -- the same care through governance: enumerate its client-stamped envelope
    -- first, or the close is a denial of service dressed as rigor.
    IF COALESCE(v_detail->>'closed','false') = 'true' THEN
      v_fs := ' <http://www.w3.org/1999/02/22-rdf-syntax-ns#type>'
            ||' <'||C||'createdBy> <'||C||'producedBy> <'||C||'sealedAtEpoch>'
            ||' <'||C||'conformsToShape> <'||C||'participant>'
            ||' <urn:ckp:board/created_at> <urn:ckp:board/created_by>';
      IF jsonb_typeof(v_detail->'ignoredProperties') = 'array' THEN
        FOR v_path IN SELECT jsonb_array_elements_text(v_detail->'ignoredProperties') LOOP
          IF v_path !~ v_iri_re THEN
            RAISE EXCEPTION 'add_class: ignoredProperties entry must be an IRI, got %', v_path; END IF;
          v_fs := v_fs||' <'||v_path||'>';
        END LOOP;
      END IF;
      v_ts := v_ts||' ; sh:closed true ; sh:ignoredProperties ('||v_fs||' )';
    END IF;
    RETURN '@prefix owl: <http://www.w3.org/2002/07/owl#> .'||chr(10)||
           '@prefix sh: <http://www.w3.org/ns/shacl#> .'||chr(10)||
           '<'||v_class||'> a owl:Class .'||chr(10)||
           '<'||v_shape||'> a sh:NodeShape ; sh:targetClass <'||v_class||'>'||v_ts||' .'||chr(10)||
           v_ttl;

  ELSIF v_op = 'set_transition_map' THEN
    v_class := v_detail->>'targetClass';
    v_map   := v_detail->'map';
    IF v_class IS NULL OR v_class !~ v_iri_re THEN
      RAISE EXCEPTION 'set_transition_map: targetClass must be an IRI, got %', v_class; END IF;
    IF v_map IS NULL OR jsonb_typeof(v_map) <> 'object' THEN
      RAISE EXCEPTION 'set_transition_map: map must be an object {from:[to,…]}'; END IF;
    v_ttl := '@prefix ckp: <'||C||'> .'||chr(10);
    FOR v_fs IN SELECT jsonb_object_keys(v_map) LOOP
      IF v_fs !~ v_state_re THEN RAISE EXCEPTION 'set_transition_map: bad from-state %', v_fs; END IF;
      IF jsonb_typeof(v_map->v_fs) <> 'array' THEN
        RAISE EXCEPTION 'set_transition_map: map[%] must be an array of to-states', v_fs; END IF;
      FOR v_ts IN SELECT jsonb_array_elements_text(v_map->v_fs) LOOP
        IF v_ts !~ v_state_re THEN RAISE EXCEPTION 'set_transition_map: bad to-state %', v_ts; END IF;
        v_ttl := v_ttl || '<'||v_class||'> ckp:allowsTransition '||
                 '[ ckp:fromState "'||v_fs||'" ; ckp:toState "'||v_ts||'" ] .'||chr(10);
      END LOOP;
    END LOOP;
    RETURN v_ttl;

  END IF;
  -- Ops without a shape projection yet (modify_shape_constraint, set_quorum,
  -- set_materialize_policy) leave the graph unchanged here; add_affordance with a query
  -- is handled by ckp.apply's register step. Translators land as each is built.
  RETURN NULL;
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp._parent_closure_ttl(p_type text, p_subj text, p_graph integer)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE v_ttl text := ''; j jsonb;
BEGIN
  IF p_type IS NULL OR p_graph IS NULL THEN RETURN ''; END IF;
  FOR j IN SELECT * FROM pgrdf.sparql(format($q$
      PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
      SELECT DISTINCT ?parent WHERE {
        GRAPH <%s> { <%s> rdfs:subClassOf+ ?parent }
        FILTER(isIRI(?parent)) }
    $q$, (SELECT iri FROM pgrdf._pgrdf_graphs WHERE graph_id = p_graph), p_type))
  LOOP
    v_ttl := v_ttl || '<'||p_subj||'> a <'||(j->>'parent')||'> .'||chr(10);
  END LOOP;
  RETURN v_ttl;
END;
$function$
;

-- pgCK#41 — the substrate-derived instance stamp. Salvaged from the bench WIP
-- (it lived only in the pgck.localhost database, in no git ref) and re-pointed
-- v3.8 -> v3.11. Emits the four properties ckp:InstanceShape requires of every
-- Instance: producedBy (the processing kernel), createdBy (the verified
-- participant, resolved by seal step 0 — never from the payload),
-- sealedAtEpoch (the kernel's epoch at seal), conformsToShape (the declared
-- shape targeting the type, resolved from the SAME graph the gate validates
-- against; absent => omitted rather than invented).
-- #59: ONE derivation, TWO renderings. Deriving the four stamps separately for
-- the gate (Turtle) and the store (JSON) is the two-registries defect class this
-- substrate has already shipped twice; two producers of the same value drift,
-- and the drift is invisible because each side validates alone.
CREATE OR REPLACE FUNCTION ckp._derived_stamps(p_subj text, p_type text, p_project text, p_participant text, p_shapes_graph integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  N     text := 'https://conceptkernel.org/ontology/v3.11/core#';
  v_ep  int;
  v_shp text;
  v_giri text;
  v_out jsonb := '{}'::jsonb;
BEGIN
  IF p_subj IS NULL OR p_type IS NULL THEN RETURN '{}'::jsonb; END IF;

  -- 0.4.79 -- M2 IS NOT OPTIONAL. producedBy names the kernel whose law governs
  -- this fact. With no kernel named this built 'urn:ckp:'||NULL||'/kernel/ck',
  -- and before clause 0 it built urn:ckp:demo/kernel/ck -- a jurisdiction that
  -- was never germinated. A fact governed by nobody is worse than a refused one.
  IF p_project IS NULL OR btrim(p_project) = '' THEN
    RAISE EXCEPTION 'ckp.seal: no kernel named, so this fact cannot carry M2 (producedBy) -- and a fact must say whose law governs it. The law IS loaded and readable: surface.declared, surface.typecheck and instance.validate all answer core-only. To seal, name your kernel: SELECT set_config(''ckp.project'', ''<your-kernel>'', true), or germinate one. (Until 0.4.79 this silently landed in the project ''demo'', whose kernel graph is empty.)';
  END IF;

  -- producedBy — the kernel that processed this instance. Server-derived.
  v_out := v_out || jsonb_build_object(N||'producedBy', 'urn:ckp:'||p_project||'/kernel/ck');

  -- createdBy — the resolved participant. Never from the payload; the caller's
  -- own claim was stripped before this ran.
  IF p_participant IS NOT NULL THEN
    v_out := v_out || jsonb_build_object(N||'createdBy', p_participant);
  END IF;

  -- sealedAtEpoch — the producing kernel's epoch at seal. Carried as a JSON
  -- number so a re-projection of the stored body yields xsd:integer, which is
  -- what InstanceShape declares.
  SELECT epoch INTO v_ep FROM ckp.kernel_epoch WHERE kernel = p_project;
  v_out := v_out || jsonb_build_object(N||'sealedAtEpoch', to_jsonb(COALESCE(v_ep,0)));

  -- conformsToShape — the declared shape that targets this type, resolved from the
  -- same graph the gate validates against. Absent => omitted rather than invented.
  IF p_shapes_graph IS NOT NULL THEN
    SELECT iri INTO v_giri FROM pgrdf._pgrdf_graphs WHERE graph_id = p_shapes_graph;
    SELECT j->>'s' INTO v_shp FROM pgrdf.sparql(format($q$
        PREFIX sh: <http://www.w3.org/ns/shacl#>
        SELECT ?s WHERE { GRAPH <%s> { ?s sh:targetClass <%s> } } LIMIT 1
      $q$, v_giri, p_type)) j;
    IF v_shp IS NOT NULL THEN
      v_out := v_out || jsonb_build_object(N||'conformsToShape', v_shp);
    END IF;
  END IF;
  RETURN v_out;
END;
$function$
;
CREATE OR REPLACE FUNCTION ckp._stamps_to_ttl(p_subj text, p_stamps jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  N     text := 'https://conceptkernel.org/ontology/v3.11/core#';
  v_ttl text := '';
BEGIN
  IF p_subj IS NULL OR p_stamps IS NULL OR p_stamps = '{}'::jsonb THEN RETURN ''; END IF;

  IF p_stamps ? (N||'producedBy') THEN
    v_ttl := v_ttl || '<'||p_subj||'> <'||N||'producedBy> <'||(p_stamps->>(N||'producedBy'))||'> .'||chr(10);
  END IF;
  IF p_stamps ? (N||'createdBy') THEN
    v_ttl := v_ttl || '<'||p_subj||'> <'||N||'createdBy> <'||(p_stamps->>(N||'createdBy'))||'> .'||chr(10);
  END IF;
  IF p_stamps ? (N||'sealedAtEpoch') THEN
    v_ttl := v_ttl || '<'||p_subj||'> <'||N||'sealedAtEpoch> '||(p_stamps->>(N||'sealedAtEpoch'))||' .'||chr(10);
  END IF;
  IF p_stamps ? (N||'conformsToShape') THEN
    v_ttl := v_ttl || '<'||p_subj||'> <'||N||'conformsToShape> <'||(p_stamps->>(N||'conformsToShape'))||'> .'||chr(10);
  END IF;
  RETURN v_ttl;
END;
$function$
;
CREATE OR REPLACE FUNCTION ckp._derived_stamp_ttl(p_subj text, p_type text, p_project text, p_participant text, p_shapes_graph integer)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
BEGIN
  RETURN ckp._stamps_to_ttl(
    p_subj,
    ckp._derived_stamps(p_subj, p_type, p_project, p_participant, p_shapes_graph));
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp._phenotype_fresh(p_concept text, p_epoch bigint, p_watermark bigint)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
  SELECT EXISTS (SELECT 1 FROM ckp.phenotype_ptr
    WHERE concept=p_concept AND epoch=p_epoch AND watermark=p_watermark
      AND (valid_until IS NULL OR now() <= valid_until))
$function$
;

CREATE OR REPLACE FUNCTION ckp._phenotype_gc()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE n int := 0; r record;
BEGIN
  FOR r IN SELECT g.iri FROM pgrdf._pgrdf_graphs g
           WHERE g.iri LIKE 'urn:ckp:phenotype/%' AND g.iri NOT IN (SELECT graph_iri FROM ckp.phenotype_ptr) LOOP
    PERFORM pgrdf.drop_graph(r.iri); n := n+1;
  END LOOP; RETURN n;
END $function$
;

CREATE OR REPLACE FUNCTION ckp._phenotype_publish(p_concept text, p_graph_iri text, p_epoch bigint, p_watermark bigint, p_valid_until timestamp with time zone)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
  INSERT INTO ckp.phenotype_ptr(concept,graph_iri,epoch,watermark,valid_until,built_at)
  VALUES (p_concept,p_graph_iri,p_epoch,p_watermark,p_valid_until,now())
  ON CONFLICT (concept) DO UPDATE SET graph_iri=EXCLUDED.graph_iri, epoch=EXCLUDED.epoch,
    watermark=EXCLUDED.watermark, valid_until=EXCLUDED.valid_until, built_at=now()
$function$
;

CREATE OR REPLACE FUNCTION ckp._query(p_verb text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  N      text := 'urn:ckp:board/';
  p_type text := p_payload->>'type';
  p_kern text := p_payload->>'kernel';
  p_n    int  := COALESCE((p_payload->>'n')::int, (p_payload->>'limit')::int,
                          CASE WHEN p_verb='instances.last' THEN 10 ELSE 50 END);
BEGIN
  IF p_verb = 'instance.get' THEN
    RETURN jsonb_build_object('ok', true, 'instance', ckp._envelope(p_payload->>'id'));
  ELSIF p_verb = 'instances.count' THEN
    RETURN jsonb_build_object('ok', true, 'count', (
      SELECT count(*) FROM ckp.instances
      WHERE (p_type IS NULL OR body->>'type'=p_type OR body->>'type' LIKE '%'||p_type)
        AND (p_kern IS NULL OR body->>(N||'target_kernel')=p_kern)));
  ELSE  -- instances.list / instances.last
    RETURN jsonb_build_object('ok', true, 'count', (
        SELECT count(*) FROM ckp.instances
        WHERE (p_type IS NULL OR body->>'type'=p_type OR body->>'type' LIKE '%'||p_type)
          AND (p_kern IS NULL OR body->>(N||'target_kernel')=p_kern)),
      'instances', COALESCE((
        SELECT jsonb_agg(ckp._envelope(id) ORDER BY ts DESC)
        FROM (SELECT id, ts_created ts FROM ckp.instances
          WHERE (p_type IS NULL OR body->>'type'=p_type OR body->>'type' LIKE '%'||p_type)
            AND (p_kern IS NULL OR body->>(N||'target_kernel')=p_kern)
          ORDER BY ts_created DESC LIMIT p_n) s), '[]'::jsonb));
  END IF;
END;
$function$
;

