CREATE OR REPLACE FUNCTION ckp._report_summary(p_report jsonb)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT string_agg(
           regexp_replace(v->>'sourceConstraintComponent','.*shacl#','')
           || CASE WHEN v->>'resultPath' IS NOT NULL
                   THEN ' on '||regexp_replace(v->>'resultPath','.*[#/]','') ELSE '' END
           || COALESCE(' ('||(v->>'resultMessage')||')',''), '; ')
  FROM jsonb_array_elements(COALESCE(p_report->'results','[]'::jsonb)) v;
$function$
;

CREATE OR REPLACE FUNCTION ckp._resolve_id(p_ref text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE v_id text;
BEGIN
  IF p_ref IS NULL OR btrim(p_ref) = '' THEN RETURN NULL; END IF;
  -- a bare id that exists resolves to itself (the common path — bare-id callers unchanged).
  IF EXISTS (SELECT 1 FROM ckp.instances WHERE id = p_ref) THEN RETURN p_ref; END IF;
  -- a stamped @id (the form create returns + reach/link accept) -> that instance's bare id.
  SELECT id INTO v_id FROM ckp.instances WHERE body->>'@id' = p_ref LIMIT 1;
  IF v_id IS NOT NULL THEN RETURN v_id; END IF;
  -- the deterministic urn:ckp:instance:<id> fallback _resolve_ref mints -> <id> if real.
  IF p_ref LIKE 'urn:ckp:instance:%' THEN
    v_id := substring(p_ref from '^urn:ckp:instance:(.*)$');
    IF v_id IS NOT NULL AND EXISTS (SELECT 1 FROM ckp.instances WHERE id = v_id) THEN RETURN v_id; END IF;
  END IF;
  -- no match: return as-is (provenance stays hollow, exactly as today — never a false positive).
  RETURN p_ref;
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp._resolve_ref(p_ref text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE v_iri text;
BEGIN
  IF p_ref IS NULL OR btrim(p_ref) = '' THEN RETURN NULL; END IF;
  -- already an absolute IRI (has a scheme — urn:…, ckp://…, https://…): use as-is.
  IF position(':' in p_ref) > 0 THEN RETURN p_ref; END IF;
  -- bare id: the instance's stamped @id is the IRI link + reach agree on.
  SELECT body->>'@id' INTO v_iri FROM ckp.instances WHERE id = p_ref;
  IF v_iri IS NOT NULL AND position(':' in v_iri) > 0 THEN RETURN v_iri; END IF;
  -- known instance without a stamped @id: a stable, deterministic fallback IRI.
  IF EXISTS (SELECT 1 FROM ckp.instances WHERE id = p_ref) THEN
    RETURN 'urn:ckp:instance:' || p_ref;
  END IF;
  RETURN NULL;   -- unknown bare id: unresolvable; caller decides (reach -> [], link -> no quad).
END;
$function$
;

