CREATE OR REPLACE FUNCTION ckp.adopt_kernel_ttl(p_ttl text, p_project text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  v_iri   text := format('urn:ckp:%s/kernel/ck', p_project);
  v_g     bigint;
  v_quads bigint;
BEGIN
  IF p_ttl IS NULL OR btrim(p_ttl) = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'ttl_required');
  END IF;
  -- get-or-create the project's CK-loop graph (after ckp.boot has claimed the reserved
  -- core/kernel ids, so the IRI-variant add_graph never steals id 1/2 — the s34 lesson).
  v_g := pgrdf.add_graph(v_iri);
  BEGIN
    v_quads := pgrdf.parse_turtle(p_ttl, v_g, v_iri || '#');
  EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('ok', false, 'error', 'parse_error', 'detail', SQLERRM);
  END;
  PERFORM pgrdf.materialize(v_g);
  RETURN jsonb_build_object('ok', true, 'project', p_project, 'ck_iri', v_iri,
                            'kernel_graph', v_g, 'quads', v_quads);
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp.apply(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  C           text := 'https://conceptkernel.org/ontology/v3.11/core#';
  v_about     text := p_payload->>'about';
  v_proj      text := ckp._project();
  v_prop      jsonb;
  v_pid       text;
  v_op        text;
  v_quorum    int;
  v_approvals int;
  v_epoch     int;
  v_new_body  jsonb;
  v_ttl       text;
  v_ga        jsonb;
  v_applied   jsonb := jsonb_build_object('graph_changed', false);
BEGIN
  IF v_about IS NULL OR v_about !~ '^[A-Za-z][A-Za-z0-9+.:#/_-]*$' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_about', 'about', v_about);
  END IF;
  SELECT id, body INTO v_pid, v_prop FROM ckp.instances
    WHERE body->>'@id' = v_about AND body->>'type' = C||'Proposal';
  IF v_prop IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'unknown_proposal', 'about', v_about);
  END IF;
  IF v_prop->>(C||'proposalState') <> 'pending' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'proposal_not_pending', 'state', v_prop->>(C||'proposalState'));
  END IF;
  v_quorum := COALESCE((v_prop->>(C||'requiresQuorum'))::int, 1);
  -- 0.4.62 — QUORUM IS DISTINCT ACCOUNTABLE PARTIES. This counted VOTES: one
  -- identity voting twice was two approvals, and ckp.seal mints a FRESH
  -- anon:<uuid> per unattributed call, so N naked-path seals presented as N
  -- distinct parties — one psql caller could manufacture any quorum (ck-dev's
  -- finding-1786732252462817000; measured unexploited, 3 anon votes on 3
  -- proposals). Now: distinct createdBy, anon:* excluded — an identity nobody
  -- can be held to cannot be a party to a decision. The three historical
  -- anon-applied proposals stand as fenced history, not precedent.
  SELECT count(DISTINCT body->>(C||'createdBy')) INTO v_approvals FROM ckp.instances
    WHERE body->>'type' = C||'Vote' AND body->>(C||'about') = v_about AND body->>(C||'voteValue') = 'approve'
      AND COALESCE(body->>(C||'createdBy'),'') NOT LIKE 'urn:ckp:participant:anon:%';
  IF v_approvals < v_quorum THEN
    RETURN jsonb_build_object('ok', false, 'error', 'quorum_not_met', 'approvals', v_approvals, 'quorum', v_quorum);
  END IF;

  v_op := v_prop->>(C||'proposalOp');

  -- 4a. GRAPH APPLY (shape ops) — translate the op into the kernel graph (the §5.2 EFFECT).
  BEGIN
    v_ttl := ckp._op_to_ttl(v_prop);
  EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('ok', false, 'error', 'op_translate_failed', 'detail', SQLERRM);
  END;
  IF v_ttl IS NOT NULL THEN
    v_ga := ckp.apply_shape_ttl(v_ttl, v_proj);
    IF (v_ga->>'ok') IS DISTINCT FROM 'true' THEN
      RETURN jsonb_build_object('ok', false, 'error', 'graph_apply_failed', 'detail', v_ga);
    END IF;
    v_applied := jsonb_build_object('graph_changed', true, 'applied_quads', v_ga->'applied_quads');
  END IF;

  -- 4b. CASCADE — epoch advance, and it MUST produce a sealed Materialization
  --     (P0-E, pgCK#28). The epoch is not a counter: the bump recompiles the
  --     plan surface (compile_plans + plan_cache_clear inside bump_epoch), and
  --     the rebuild is SEALED as a first-class ckp:Materialization that
  --     produces a ckp:Epoch carrying the surface digest. All in THIS txn: if
  --     the Materialization or Epoch fails its shape gate, the whole apply
  --     rolls back — a bumped epoch with no valid Materialization cannot
  --     commit. "Show me the Materialization that produced this epoch, and
  --     re-derive the surface at that epoch" is answerable from the seals.
  DECLARE
    -- this project's epoch, not a fixed kernel's: reading one kernel's epoch
    -- while bumping another's makes every other kernel restart from 1.
    v_from   int := COALESCE((SELECT epoch FROM ckp.kernel_epoch WHERE kernel = v_proj), 1);
    v_comp_e int;
    v_srcd   text;
    v_surfd  text;
    v_kiri   text := format('urn:ckp:%s/kernel/ck', v_proj);
    v_eiri   text;
    v_miri   text;
  BEGIN
    -- bump THIS project's epoch. Hard-coded, it advanced one kernel's epoch on
    -- every apply by anyone, so every other kernel's epoch never moved and its
    -- plans were recompiled under a name it does not own.
    v_epoch := ckp.bump_epoch(v_proj);           -- recompiles plans + clears cache (same txn)
    v_comp_e := ckp._composed_shapes(v_proj);    -- rebuild the enforcement surface from the new shapes
    v_srcd  := ckp._surface_digest(pgrdf.add_graph(v_kiri));   -- the governed source shapes
    v_surfd := ckp._surface_digest(v_comp_e);                  -- the enforcement surface produced
    v_eiri  := format('urn:ckp:%s/epoch/%s', v_proj, v_epoch);
    v_miri  := format('urn:ckp:%s/materialization/%s', v_proj, v_epoch);
    -- the Epoch resource: the position, named by the digest of its surface.
    -- 0.4.67: TWO digest planes, each named for what it pins. surfaceDigest is
    -- the COPY plane — this store's bytes, what surface.check compares in-store
    -- and what the digest-match obligation consults; it moves on reload and is
    -- never cross-bench identity. structuralDigest is the plane that survives
    -- reload (first-degree bnode-signature algorithm, fleet-shared) — the one a
    -- third party CAN recompute from the published modules, and the one a
    -- cross-store verifier cites. Nobody minted early: this key ships in the
    -- same act as the code that derives it.
    PERFORM ckp.seal('epoch-'||v_proj||'-'||v_epoch, jsonb_build_object(
      'type', C||'Epoch', '@id', v_eiri,
      C||'epoch', to_jsonb(v_epoch),
      C||'surfaceDigest', v_surfd,
      C||'structuralDigest', ckp._structural_digest(v_comp_e)));
    -- the Materialization: the sealed rebuild that produced that epoch.
    PERFORM ckp.seal('mat-'||v_proj||'-'||v_epoch, jsonb_build_object(
      'type', C||'Materialization', '@id', v_miri,
      C||'materializes', v_kiri,
      C||'fromEpoch', to_jsonb(v_from),
      C||'toEpoch', to_jsonb(v_epoch),
      C||'sourceDigest', v_srcd,
      C||'surfaceDigest', v_surfd,
      C||'producesEpoch', v_eiri));
  END;

  -- 4c. QUERY AFFORDANCE (Tier 2 3/3b) — an add_affordance carrying query text is compiled into
  --     ckp.plans + registered plane='query', keyed to the new epoch (governed, sealed).
  IF v_op = 'add_affordance' AND (v_prop->'proposalDetail' ? 'query') THEN
    BEGIN
      PERFORM ckp.register_query_affordance(v_prop, v_proj, v_epoch);
      v_applied := v_applied || jsonb_build_object('query_affordance', v_prop->'proposalDetail'->>'verb');
    EXCEPTION WHEN OTHERS THEN
      RETURN jsonb_build_object('ok', false, 'error', 'affordance_register_failed', 'detail', SQLERRM);
    END;
  END IF;

  -- 4d. PROOF OBLIGATION (0.4.65, §5b) — the seal-exit dual of 4c: where
  --     add_affordance opens a dispatch entry, add_proof_obligation closes the
  --     seal's exit with a check every future seal of the target type must
  --     satisfy. The registry row is the projected change (P0-E honoured);
  --     removal travels the same governed road with detail.active=false.
  IF v_op = 'add_proof_obligation' THEN
    BEGIN
      PERFORM ckp.register_proof_obligation(v_prop, v_proj, v_epoch);
      v_applied := v_applied || jsonb_build_object('proof_obligation', v_prop->'proposalDetail'->>'obligation',
                                                   'obligation_active', COALESCE(v_prop->'proposalDetail'->>'active','true'));
    EXCEPTION WHEN OTHERS THEN
      RETURN jsonb_build_object('ok', false, 'error', 'obligation_register_failed', 'detail', SQLERRM);
    END;
  END IF;

  v_new_body := v_prop || jsonb_build_object(C||'proposalState', 'applied', C||'appliedEpoch', v_epoch::text);
  PERFORM ckp.seal(v_pid, v_new_body);

  RETURN jsonb_build_object('ok', true, 'proposal', v_about, 'state', 'applied', 'epoch', v_epoch,
                            'op', v_op, 'approvals', v_approvals, 'applied', v_applied,
                            'verified', ckp.verify(v_pid));
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp.apply_shape_ttl(p_ttl text, p_project text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  C             text := 'https://conceptkernel.org/ontology/v3.11/core#';
  v_scratch_iri text := 'urn:ckp:apply:'||pg_backend_pid();
  v_scratch     int;
  v_kernel      int;
  v_quads       bigint;
  v_forbidden   jsonb;
BEGIN
  v_scratch := pgrdf.add_graph(v_scratch_iri);
  PERFORM pgrdf.clear_graph(v_scratch);
  BEGIN
    v_quads := pgrdf.parse_turtle(p_ttl, v_scratch, 'urn:ckp:apply#');
  EXCEPTION WHEN OTHERS THEN
    PERFORM pgrdf.clear_graph(v_scratch);
    RETURN jsonb_build_object('ok', false, 'error', 'parse_error', 'detail', SQLERRM);
  END;

  -- META-FENCE — admit ontology-meta predicates (rdf/rdfs/owl/sh) PLUS the three sealed
  -- governance transition predicates (allowsTransition/fromState/toState). Every other
  -- predicate (instance data, foreign triples) is fence-rejected. The op TTL is pgCK-built
  -- and field-validated; this fence is the defence-in-depth backstop.
  SELECT jsonb_agg(DISTINCT j->>'p') INTO v_forbidden
  FROM pgrdf.sparql(format($q$
    SELECT ?p WHERE { GRAPH <%s> { ?s ?p ?o }
      FILTER( !STRSTARTS(STR(?p), "http://www.w3.org/1999/02/22-rdf-syntax-ns#")
           && !STRSTARTS(STR(?p), "http://www.w3.org/2000/01/rdf-schema#")
           && !STRSTARTS(STR(?p), "http://www.w3.org/2002/07/owl#")
           && !STRSTARTS(STR(?p), "http://www.w3.org/ns/shacl#")
           && STR(?p) != "%sallowsTransition"
           && STR(?p) != "%sfromState"
           && STR(?p) != "%stoState" ) }
  $q$, v_scratch_iri, C, C, C)) j;
  IF v_forbidden IS NOT NULL THEN
    PERFORM pgrdf.clear_graph(v_scratch);
    RETURN jsonb_build_object('ok', false, 'error', 'fence_violation', 'forbidden_predicates', v_forbidden);
  END IF;

  v_kernel := pgrdf.add_graph(format('urn:ckp:%s/kernel/ck', p_project));
  PERFORM ckp._graph_apply(v_scratch, v_kernel);
  PERFORM pgrdf.materialize(v_kernel);
  PERFORM pgrdf.clear_graph(v_scratch);
  RETURN jsonb_build_object('ok', true, 'applied_quads', v_quads, 'kernel_graph', v_kernel);
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp.bump_epoch(p_kernel text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE v_epoch integer;
BEGIN
  INSERT INTO ckp.kernel_epoch(kernel, epoch) VALUES (p_kernel, 1) ON CONFLICT (kernel) DO NOTHING;
  UPDATE ckp.kernel_epoch SET epoch = epoch + 1 WHERE kernel = p_kernel RETURNING epoch INTO v_epoch;
  PERFORM ckp.compile_plans(p_kernel);   -- recompile at the new epoch (same txn)
  PERFORM pgrdf.plan_cache_clear();       -- invalidate the engine SPARQL plan cache (same txn)
  RETURN v_epoch;
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp.compile_plans(p_kernel text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  v_epoch integer;
  v_n     integer := 0;
  r       record;
BEGIN
  INSERT INTO ckp.kernel_epoch(kernel, epoch) VALUES (p_kernel, 1) ON CONFLICT (kernel) DO NOTHING;
  SELECT epoch INTO v_epoch FROM ckp.kernel_epoch WHERE kernel = p_kernel;

  FOR r IN
    SELECT * FROM (VALUES
      ('instance.get',
        '{"kind":"sql","statement":"SELECT body FROM ckp.instances WHERE id = $1","params":["id"]}'::jsonb),
      ('instance.count',
        '{"kind":"sql","statement":"SELECT count(*) AS n FROM ckp.instances","params":[]}'::jsonb)
    ) AS cat(verb, plan)
  LOOP
    INSERT INTO ckp.plans(kernel, verb, epoch, plan)
      VALUES (p_kernel, r.verb, v_epoch, r.plan)
      ON CONFLICT (kernel, verb, epoch) DO UPDATE SET plan = EXCLUDED.plan, compiled_at = now();
    v_n := v_n + 1;
  END LOOP;
  RETURN v_n;
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp.compute_publish_subject(p_type_uri text, p_project text DEFAULT NULL)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
  -- The subject names the kernel that PRODUCED the fact. This was
  -- 'event.kernel.pgck.%s.sealed' -- a literal -- so every kernel's events
  -- landed on one subject and a browser subscribed to its own kernel saw
  -- nothing. Same defect as dispatch resolving every caller under one name
  -- (0.4.46/47), on the OUTBOUND path, where it is invisible from inside:
  -- the publish succeeds, it just arrives somewhere nobody is listening.
  --
  -- DEFAULT rather than a second overload: three of today's defects were an
  -- overload pair drifting apart, and one CREATE with a default cannot.
  -- STABLE, not IMMUTABLE -- it depends on ckp._project() when not told.
  SELECT format(
    'event.kernel.%s.%s.sealed',
    COALESCE(NULLIF(p_project, ''), ckp._project()),
    COALESCE(
      NULLIF(regexp_replace(COALESCE(p_type_uri, ''), '^.*[/#]', ''), ''),
      'Instance'
    )
  );
$function$
;

CREATE OR REPLACE FUNCTION ckp.concept_match(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  v_term   text := p_payload->>'term';
  v_proj   text := ckp._project();
  v_limit  int  := LEAST(GREATEST(COALESCE((p_payload->>'limit')::int, 10), 1), 100);
  v_term_esc text;
  v_plan   jsonb;
  v_stmt   text;
  v_rows   jsonb;
BEGIN
  IF v_term IS NULL OR length(v_term) < 1 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_term', 'term', v_term);
  END IF;

  -- the GOVERNED query: latest-epoch concept.match plan.
  -- PLAN RESOLUTION = your own first, then the substrate floor. A plan the
  -- calling project registered wins; otherwise fall back to the one seeded at
  -- install, which belongs to no kernel because install runs before any kernel
  -- exists. Reading ONLY the floor made every project share one kernel's plans;
  -- reading ONLY v_proj made the seeded substrate verbs unreachable for
  -- everyone (smoke-s4 s32). Both halves are needed until the seed itself stops
  -- naming a kernel.
  SELECT plan INTO v_plan FROM ckp.plans
   WHERE kernel IN (v_proj, 'pgck') AND verb = 'concept.match'
   ORDER BY (kernel = v_proj) DESC, epoch DESC LIMIT 1;

  IF v_plan IS NOT NULL AND v_plan->>'kind' = 'sparql' THEN
    -- BIND (not reject): escape the term for the SPARQL string literal so any term is contained —
    -- an injection-shaped term becomes a literal that matches nothing (never breaks the query).
    v_term_esc := replace(replace(replace(v_term, '\', '\\'), '"', '\"'), chr(10), '\n');
    v_stmt := replace(v_plan->>'statement', '$graph$', format('urn:ckp:%s/instances', v_proj));
    v_stmt := replace(v_stmt, '$term$', v_term_esc);
    -- run + RANK in pgCK (exact > prefix > contains; the governed query supplies the matches).
    SELECT jsonb_agg(jsonb_build_object('id', id, 'label', lbl, 'rank', rnk) ORDER BY rnk, lbl)
      INTO v_rows
    FROM (
      SELECT j->>'id' AS id, j->>'label' AS lbl,
        CASE WHEN lower(j->>'label') = lower(v_term)         THEN 1
             WHEN lower(j->>'label') LIKE lower(v_term)||'%' THEN 2
             ELSE 3 END AS rnk
      FROM pgrdf.sparql(v_stmt) j
      LIMIT v_limit
    ) t;
    RETURN jsonb_build_object('ok', true, 'term', v_term, 'governed', true,
                              'count', COALESCE(jsonb_array_length(v_rows), 0),
                              'candidates', COALESCE(v_rows, '[]'::jsonb));
  END IF;

  -- fallback: the legacy in-table label search (no governed plan present).
  SELECT jsonb_agg(jsonb_build_object('id', id, 'label', lbl, 'rank', rnk) ORDER BY rnk, lbl)
  INTO v_rows FROM (
    SELECT id, lbl,
      CASE WHEN lower(lbl) = lower(v_term)         THEN 1
           WHEN lower(lbl) LIKE lower(v_term)||'%' THEN 2
           ELSE 3 END AS rnk
    FROM (
      SELECT id, COALESCE(body->>'rdfs:label',
                          body->>'urn:ckp:board/title',
                          body->>'title') AS lbl
      FROM ckp.instances
    ) s
    WHERE lbl ILIKE '%'||v_term||'%'
    ORDER BY rnk
    LIMIT v_limit
  ) t;
  RETURN jsonb_build_object('ok', true, 'term', v_term, 'governed', false,
                            'count', COALESCE(jsonb_array_length(v_rows), 0),
                            'candidates', COALESCE(v_rows, '[]'::jsonb));
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp.create_typed(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  -- 0.4.51: read the SAME payload shapes ckp.validate_instance reads. It did
  -- COALESCE(p_payload->'body', p_payload) and this did not, so a nested
  -- {body:{type,…}} VALIDATED and then failed to CREATE — validate ⟺ seal
  -- broken at the envelope, one level above where it was broken at the
  -- property map. Both are closed in this version, in the same act, because
  -- fixing one and not the other just moves the disagreement.
  v_in      jsonb := CASE WHEN jsonb_typeof(p_payload->'body') = 'object'
                            AND ((p_payload->'body') ? 'type')
                          THEN p_payload->'body' ELSE p_payload END;
  v_type    text := v_in->>'type';
  v_proj    text := ckp._project();
  -- F-A / P0-C (pgCK#26): identity is SERVER-DERIVED from the verified
  -- connection (the ckp.requester GUC the trusted ingress sets from the
  -- NATS-verified bearer), NEVER the client payload. A payload {sub} is
  -- ignored — it cannot forge created_by or the participant claim. This is
  -- the same rule task.create and notify already carry; the generic path
  -- was the last reader of payload sub (measured: s58's instance.create
  -- case sealed participant:attacker before this fix).
  v_sub     text := current_setting('ckp.requester', true);
  N         text := 'urn:ckp:board/';       -- v3.7 core NS (gate + task.create)
  v_core    text[] := ARRAY['lifecycle_state'];                       -- recognized core keys → core NS
  v_local   text;
  v_ns      text;
  v_iid     text;
  v_propmap jsonb;
  v_body    jsonb;
  v_key     text;
  v_val     jsonb;
  v_keyiri  text;
BEGIN
  IF v_type IS NULL OR btrim(v_type) = '' THEN
    -- 0.4.51 — ABSENT is not the same as PRESENT-BUT-NOT-READABLE-HERE, and the
    -- old error said the first when the second was true. A caller following
    -- JSON-LD habit sends {"@type": …} and is told it gave no type; a caller
    -- nesting {"type": …, "body": {…}} is told the same. Both then re-send the
    -- one field they already sent. pgCK.MCP lost two calls to exactly this
    -- (F9) before reading the spec. Name the shape instead of the field.
    IF p_payload ? '@type' OR (jsonb_typeof(p_payload->'body') = 'object'
                               AND ((p_payload->'body') ? '@type')) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'type_not_readable_here',
        'hint', 'a type WAS supplied, in a position this verb does not read. Accepted: FLAT {"type": "<class IRI>", "<prop>": …}, or nested {"body": {"type": …, "<prop>": …}} — the same two shapes instance.validate reads. NOT accepted: @type, which is never read.');
    END IF;
    RETURN jsonb_build_object('ok', false, 'error', 'type_required',
      'hint', 'the payload is flat: {"type": "<class IRI>", "<prop>": …}');
  END IF;
  IF position(':' in v_type) = 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'type_must_be_iri',
      'hint', 'instance.create {type} must be the full class IRI the kernel declares (sh:targetClass), e.g. urn:ckp:<project>/type/Ship');
  END IF;

  v_local := regexp_replace(v_type, '^.*[/#]', '');
  v_ns    := regexp_replace(v_type, '[^/#]*$', '');
  v_iid   := lower(v_local) || '-' || (extract(epoch from clock_timestamp())*1e9)::bigint::text;

  -- 0.4.51: the SAME map validate_instance uses. It read the kernel graph while
  -- validate read composed, so validate and create could resolve one JSON key to
  -- two different IRIs. See ckp._propmap.
  v_propmap := ckp._propmap(v_type, v_proj);

  v_body := jsonb_build_object('type', v_type, '@id', 'ckp://' || v_local || '#' || v_iid);
  FOR v_key, v_val IN SELECT key, value FROM jsonb_each(v_in)
  LOOP
    CONTINUE WHEN v_key IN ('type', 'sub', '@id', 'participant');     -- control keys, not data (sub/participant: identity is never payload)
    IF position(':' in v_key) > 0 THEN
      v_keyiri := v_key;                                             -- already a full IRI: pass through
    ELSIF v_propmap ? v_key THEN
      v_keyiri := v_propmap->>v_key;                                 -- declared localname -> its path IRI
    ELSIF v_key = ANY(v_core) THEN
      v_keyiri := N || v_key;                                        -- v3.7 core key -> core NS (gate + task.create)
    ELSE
      v_keyiri := v_ns || v_key;                                     -- other undeclared -> under the type's NS
    END IF;
    v_body := v_body || jsonb_build_object(v_keyiri, v_val);         -- `->` value: preserves number/bool/object types
  END LOOP;

  v_body := v_body || jsonb_build_object(
    'urn:ckp:board/created_at',
    to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'));
  IF v_sub IS NOT NULL THEN
    -- created_by from the VERIFIED requester (same shape as task.create), and
    -- the participant claim seal maps to core#participant — also verified.
    v_body := v_body || jsonb_build_object(
      N||'created_by', 'urn:ckp:participant:'||ckp._slug(v_sub),
      'participant', jsonb_build_object('sub', v_sub));
  END IF;

  PERFORM ckp.seal(v_iid, v_body);

  -- 0.4.72: the guidance band rides the reply. ckp.seal parked any
  -- Warning/Info-severity results in a txn-local GUC (cleared at each seal
  -- start); surfacing them here is what makes warning-shapes GUIDANCE instead
  -- of noise — sealed, and told why the fleet would prefer it shaped better.
  RETURN jsonb_build_object('ok', true, 'id', v_iid, 'type', v_type,
    'verified', ckp.verify(v_iid),
    'proof_digest', (SELECT digest FROM ckp.proof WHERE about = v_iid ORDER BY id DESC LIMIT 1))
    || CASE WHEN NULLIF(current_setting('ckp.last_warnings', true), '') IS NOT NULL
            THEN jsonb_build_object('warnings', current_setting('ckp.last_warnings', true)::jsonb)
            ELSE '{}'::jsonb END;
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('ok', false, 'error', SQLERRM);
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp.declared_predicates(p_project text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
  SELECT COALESCE(jsonb_agg(DISTINCT p), '[]'::jsonb)
  FROM (
    SELECT j->>'p' AS p
    FROM pgrdf.sparql(format($q$
      PREFIX sh: <http://www.w3.org/ns/shacl#>
      SELECT ?p WHERE { GRAPH <urn:ckp:%s/kernel/ck> { ?s sh:property ?prop . ?prop sh:path ?p } }
    $q$, p_project)) j
    WHERE j->>'p' IS NOT NULL
  ) d;
$function$
;

CREATE OR REPLACE FUNCTION ckp.derived_dispersion(p_concept text, p_scope jsonb, p_formula text, p_epoch bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE MP text := 'urn:ckp:mat/'; wm bigint := ckp._source_watermark(p_scope); giri text; net numeric; vol numeric;
BEGIN
  IF NOT ckp._phenotype_fresh(p_concept, p_epoch, wm) THEN
    giri := ckp._epsilon_materialize(p_concept, p_scope, p_formula, p_epoch);
    PERFORM ckp._phenotype_publish(p_concept, giri, p_epoch, wm, now()+interval '1 hour');
  END IF;
  giri := (SELECT graph_iri FROM ckp.phenotype_ptr WHERE concept=p_concept);
  -- SRF-in-COALESCE is disallowed; read each SUM in a scalar subquery (FROM), COALESCE the scalar.
  net := COALESCE((SELECT (j->>'v')::numeric FROM pgrdf.sparql(
        'SELECT (SUM(?c) AS ?v) WHERE { GRAPH <'||giri||'> { ?s <'||MP||'contrib> ?c } }') AS j), 0);
  vol := COALESCE((SELECT (j->>'v')::numeric FROM pgrdf.sparql(
        'SELECT (SUM(?c) AS ?v) WHERE { GRAPH <'||giri||'> { ?s <'||MP||'contrib_abs> ?c } }') AS j), 0);
  RETURN jsonb_build_object('ok',true,'net',net,'volume',vol);
END $function$
;

CREATE OR REPLACE FUNCTION ckp.derived_sum(p_concept text, p_scope jsonb, p_formula text, p_epoch bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE MP text := 'urn:ckp:mat/'; wm bigint := ckp._source_watermark(p_scope); giri text; v numeric;
BEGIN
  IF NOT ckp._phenotype_fresh(p_concept, p_epoch, wm) THEN
    giri := ckp._epsilon_materialize(p_concept, p_scope, p_formula, p_epoch);
    PERFORM ckp._phenotype_publish(p_concept, giri, p_epoch, wm, now()+interval '1 hour');
  END IF;
  giri := (SELECT graph_iri FROM ckp.phenotype_ptr WHERE concept=p_concept);
  -- pgrdf.sparql is SETOF jsonb; a SRF is not allowed directly in COALESCE, so read it in a
  -- scalar subquery (SUM returns one row) and COALESCE the scalar (0 when the graph is empty).
  v := COALESCE((SELECT (j->>'v')::numeric FROM pgrdf.sparql(
        'SELECT (SUM(?c) AS ?v) WHERE { GRAPH <'||giri||'> { ?s <'||MP||'contrib> ?c } }') AS j), 0);
  RETURN jsonb_build_object('ok',true,'value',v);
END $function$
;

CREATE OR REPLACE FUNCTION ckp.dict_intern(p_iri text)
 RETURNS TABLE(handle bigint, v bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  v_handle bigint;
  v_v      bigint;
BEGIN
  IF p_iri IS NULL OR length(p_iri) = 0 THEN
    RAISE EXCEPTION 'ckp.dict_intern: iri must be non-empty';
  END IF;

  SELECT d.handle, d.v INTO v_handle, v_v
  FROM ckp.dictionary d WHERE d.iri = p_iri;

  IF v_handle IS NOT NULL THEN
    RETURN QUERY SELECT v_handle, v_v;
    RETURN;
  END IF;

  v_handle := nextval('ckp.dictionary_handle_seq');
  v_v      := nextval('ckp.dictionary_v_seq');

  INSERT INTO ckp.dictionary (handle, iri, v)
  VALUES (v_handle, p_iri, v_v);

  -- Hand-off to the Rust bgworker: NATS publisher LISTENs on this channel and
  -- emits event.kernel.Dictionary.v_bumped { from: v-1, to: v, delta: [...] }
  PERFORM pg_notify(
    'ckp_dict_v_bumped',
    json_build_object('handle', v_handle, 'iri', p_iri, 'v', v_v)::text
  );

  RETURN QUERY SELECT v_handle, v_v;
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp.dispatch(p_verb text, p_kernel_urn text, p_payload jsonb, p_identity text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  res jsonb;
BEGIN
  -- Transitional minimal surface (CI-A-2). The full §2.2 fail-fast order lands in
  -- CI-B/CI-C/CI-D; here we prove the locked door is usable as definer.
  CASE p_verb
    WHEN 'instances.count' THEN
      res := jsonb_build_object('ok', true, 'count', (SELECT count(*) FROM ckp.instances));
    WHEN 'instance.verify' THEN
      res := jsonb_build_object('ok', true, 'id', p_payload->>'id',
                                'verified', ckp.verify(p_payload->>'id'));
    ELSE
      -- unknown verb -> the delegation seam (becomes a sealed-delegation fact in CI-B-4).
      res := jsonb_build_object('ok', false, 'delegate', true,
                                'error', 'verb not governed yet (CI-B): ' || p_verb);
  END CASE;
  RETURN res || jsonb_build_object('kernel', p_kernel_urn);
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp.surface_check(p_project text DEFAULT NULL)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  N        text := 'https://conceptkernel.org/ontology/v3.11/core#';
  v_proj   text := COALESCE(p_project, ckp._project());
  v_kiri   text;
  v_epoch  int;
  v_ep_iri text;
  v_pin_surf text;
  v_pin_src  text;
  v_comp   int;
  v_act_surf text;
  v_act_src  text;
  v_kquads int;
  v_shapes int;
  v_mods   jsonb := '[]'::jsonb;
  v_iri    text;
  v_n      int;
  v_find   jsonb := '[]'::jsonb;
  v_state  text;
BEGIN
  -- 0.4.81 — CORE-ONLY SHORT-CIRCUIT. With no kernel named there is no kernel
  -- graph to name, and building 'urn:ckp:'||NULL||'/kernel/ck' produced a NULL
  -- IRI that reached pgrdf.sparql as a parse error — the check crashed on
  -- exactly the state it was taught to call healthy. (Caught by s72, which is
  -- the argument for writing the gate with the change rather than after it.)
  IF v_proj IS NULL THEN
    v_comp := ckp._composed_shapes(NULL);          -- the surface IS core
    RETURN jsonb_build_object(
      'ok', true, 'kernel', NULL, 'state', 'core-only', 'epoch', 0,
      'epoch_resource', NULL,
      'surface', jsonb_build_object('pinned', NULL, 'actual', ckp._surface_digest(v_comp), 'match', NULL),
      'source',  jsonb_build_object('pinned', NULL, 'actual', NULL, 'match', NULL),
      'kernel_graph', NULL,
      'composed_nodeshapes', (SELECT count(*) FROM pgrdf.sparql(format(
         'PREFIX sh: <http://www.w3.org/ns/shacl#> SELECT ?s WHERE { GRAPH <%s> { ?s a sh:NodeShape } }',
         pgrdf.graph_iri(v_comp)))),
      'modules', '[]'::jsonb,
      'findings', '[]'::jsonb,
      'note', 'no kernel named: the law is loaded and readable (surface.declared, surface.typecheck, instance.validate all answer), and sealing refuses on M2. A complete state, not a fault.',
      'healthy', true);
  END IF;

  v_kiri  := 'urn:ckp:'||v_proj||'/kernel/ck';
  v_epoch := COALESCE((SELECT epoch FROM ckp.kernel_epoch WHERE kernel = v_proj), 0);

  -- What the ledger says the surface was, at the epoch in force.
  SELECT i.body->>'@id', i.body->>(N||'surfaceDigest')
    INTO v_ep_iri, v_pin_surf
  FROM ckp.instances i
  WHERE i.body->>'type' = N||'Epoch'
    AND i.body->>(N||'producedBy') = v_kiri
    AND (i.body->>(N||'epoch'))::int = v_epoch
  ORDER BY i.ts_created DESC LIMIT 1;

  SELECT i.body->>(N||'sourceDigest') INTO v_pin_src
  FROM ckp.instances i
  WHERE i.body->>'type' = N||'Materialization'
    AND i.body->>(N||'producesEpoch') = v_ep_iri
  ORDER BY i.ts_created DESC LIMIT 1;

  -- What it is now.
  v_comp     := ckp._composed_shapes(v_proj);
  v_act_surf := ckp._surface_digest(v_comp);
  v_act_src  := ckp._surface_digest(pgrdf.add_graph(v_kiri));

  SELECT count(*) INTO v_kquads
    FROM pgrdf.sparql(format('SELECT ?s WHERE { GRAPH <%s> { ?s ?p ?o } }', v_kiri));
  SELECT count(*) INTO v_shapes
    FROM pgrdf.sparql(format('PREFIX sh:<http://www.w3.org/ns/shacl#> SELECT ?s WHERE { GRAPH <%s> { ?s a sh:NodeShape } }',
                             (SELECT iri FROM pgrdf._pgrdf_graphs WHERE graph_id = v_comp)));

  -- Every adopted module: present and non-empty, or named as missing.
  FOREACH v_iri IN ARRAY ckp._adopted_graphs(v_proj) LOOP
    SELECT count(*) INTO v_n
      FROM pgrdf.sparql(format('SELECT ?s WHERE { GRAPH <%s> { ?s ?p ?o } }', v_iri));
    v_mods := v_mods || jsonb_build_array(jsonb_build_object('iri', v_iri, 'quads', v_n, 'present', v_n > 0));
    IF v_n = 0 THEN
      v_find := v_find || jsonb_build_array('adopted module is ABSENT or EMPTY: '||v_iri);
    END IF;
  END LOOP;

  -- Findings. Each names what was measured, never a guess at the cause.
  -- 0.4.81 — STATE IS NOT HEALTH, and an empty kernel graph means different
  -- things in each state. A brand-new install reported `healthy:false` with a
  -- "wipe signature" on a machine where nothing had ever happened: the check
  -- could not tell NEVER EXISTED from WAS DESTROYED, and a diagnostic that is
  -- false on every correct day-one install is the twin of one that can never
  -- fail — nobody trusts it, so it cannot do its job.
  --
  --   core-only   no kernel named. The surface IS core. Complete and correct:
  --               the law is readable, sealing refuses on M2. NOT a fault.
  --   named       a project resolves but no ckp:Kernel is sealed. Germination
  --               is the open next act.
  --   germinated  a Kernel is sealed. NOW an empty graph is a real wipe.
  IF v_proj IS NULL THEN
    v_state := 'core-only';
  ELSIF EXISTS (SELECT 1 FROM ckp.instances
                 WHERE body->>'type' = 'https://conceptkernel.org/ontology/v3.11/core#Kernel'
                   AND body->>'@id'  = 'urn:ckp:'||v_proj||'/kernel') THEN
    v_state := 'germinated';
  ELSE
    v_state := 'named';
  END IF;

  IF v_kquads = 0 AND v_state = 'germinated' THEN
    v_find := v_find || jsonb_build_array(
      'kernel graph '||v_kiri||' is EMPTY while a ckp:Kernel IS sealed for this project — '||
      'the enforcement surface is composed WITHOUT the kernel''s own shapes. This is the '||
      '2026-08-10 wipe signature: something that existed is gone.');
  END IF;
  IF v_shapes = 0 THEN
    v_find := v_find || jsonb_build_array(
      'composed surface carries ZERO NodeShapes — every gate is vacuous; refuse to trust any conformance result');
  END IF;
  IF v_pin_surf IS NULL AND v_state = 'germinated' AND v_epoch > 0 THEN
    -- Only a fault once the kernel HAS governed: an epoch advanced without
    -- sealing what was in force. Before that, unpinned is the pre-governance
    -- state, reported below as `state`, not as a finding.
    v_find := v_find || jsonb_build_array(
      'epoch '||v_epoch||' is in force but no ckp:Epoch seals its digest — an apply advanced the epoch without recording the surface, so drift is undetectable');
  ELSIF v_pin_surf IS DISTINCT FROM v_act_surf THEN
    v_find := v_find || jsonb_build_array(
      'SURFACE DRIFT: the composed surface differs from the digest epoch '||v_epoch||' sealed. '||
      'Either the surface changed outside a governed apply (adoption, a direct graph write, or a wipe), '||
      'or an apply failed to reseal. Pinned '||left(v_pin_surf,12)||'… actual '||left(v_act_surf,12)||'…');
  END IF;
  IF v_pin_src IS NOT NULL AND v_pin_src IS DISTINCT FROM v_act_src THEN
    v_find := v_find || jsonb_build_array(
      'SOURCE DRIFT: the kernel graph differs from the sourceDigest its Materialization sealed. '||
      'Pinned '||left(v_pin_src,12)||'… actual '||left(v_act_src,12)||'…');
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'kernel', v_proj,
    'state', v_state,
    'epoch', v_epoch,
    'epoch_resource', v_ep_iri,
    'surface', jsonb_build_object('pinned', v_pin_surf, 'actual', v_act_surf,
                                  'match', v_pin_surf IS NOT DISTINCT FROM v_act_surf),
    'source',  jsonb_build_object('pinned', v_pin_src,  'actual', v_act_src,
                                  'match', v_pin_src IS NOT DISTINCT FROM v_act_src),
    'kernel_graph', jsonb_build_object('iri', v_kiri, 'quads', v_kquads, 'empty', v_kquads = 0),
    'composed_nodeshapes', v_shapes,
    'modules', v_mods,
    'findings', v_find,
    'note', CASE v_state
      WHEN 'core-only'  THEN 'no kernel named: the law is loaded and readable, sealing refuses on M2. A complete state, not a fault.'
      WHEN 'named'      THEN 'a project resolves but no ckp:Kernel is sealed — germination is the open next act.'
      ELSE 'a ckp:Kernel is sealed for this project.' END,
    'healthy', jsonb_array_length(v_find) = 0);
END;
$function$
;
CREATE OR REPLACE FUNCTION ckp.integrity_check(p_project text DEFAULT NULL)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  N      text := 'https://conceptkernel.org/ontology/v3.11/core#';
  v_proj text := COALESCE(p_project, ckp._project());
  v_comp int;
  v_giri text;
  v_find jsonb := '[]'::jsonb;
  v_total int; v_unattr int; v_vac int; v_vac_new int;
  r record;
BEGIN
  v_comp := ckp._composed_shapes(v_proj);
  SELECT iri INTO v_giri FROM pgrdf._pgrdf_graphs WHERE graph_id = v_comp;

  SELECT count(*) INTO v_total FROM ckp.instances;

  -- 1. ATTRIBUTION over sealed rows. InstanceShape requires createdBy; a stored
  -- row without it predates 0.4.33 or bypassed the seal. Named, not assumed.
  SELECT count(*) INTO v_unattr FROM ckp.instances
   WHERE NOT (body ? (N||'createdBy'));
  IF v_unattr > 0 THEN
    v_find := v_find || jsonb_build_array(
      v_unattr||' sealed row(s) carry no ckp:createdBy — unattributable work (pre-0.4.33 seals)');
  END IF;

  -- 2. VACUOUS SEALS. conformsToShape is omitted rather than invented when no
  -- shape targeted the candidate, so its absence IS the vacuity signal.
  -- Pre-governance rows (sealedAtEpoch 0) are SCARS: sealed before the root was in
  -- force, unfixable by construction (nothing is ever unsealed), and legitimate
  -- history under the S5 ruling — fence, never backfill. They are reported under
  -- `historical`, NOT as findings: a check that can never go green trains its
  -- reader to ignore it, which is how a real defect gets missed. A vacuous seal at
  -- epoch >= 1 is a live defect and IS a finding.
  SELECT count(*) INTO v_vac FROM ckp.instances
   WHERE NOT (body ? (N||'conformsToShape'))
     AND COALESCE((body->>(N||'sealedAtEpoch'))::int, 0) = 0;
  SELECT count(*) INTO v_vac_new FROM ckp.instances
   WHERE NOT (body ? (N||'conformsToShape'))
     AND COALESCE((body->>(N||'sealedAtEpoch'))::int, 0) > 0;
  IF v_vac_new > 0 THEN
    v_find := v_find || jsonb_build_array(
      v_vac_new||' row(s) sealed AT epoch >= 1 carry no ckp:conformsToShape — they passed a gate '||
      'that targeted nothing. Post-adoption vacuity is a defect, not history.');
  END IF;

  -- 3. G-1 PROPER: cross-node references the gate cannot check. Each is reported
  -- with its subject so the finding is actionable, never a bare count.
  FOR r IN
    SELECT i.id, i.body->>(N||'derivedBy') AS ref FROM ckp.instances i
     WHERE i.body->>'type' = N||'Affordance' AND i.body ? (N||'derivedBy')
       AND NOT EXISTS (SELECT 1 FROM ckp.instances m
                        WHERE m.body->>'type' = N||'Materialization'
                          AND m.body->>'@id' = i.body->>(N||'derivedBy'))
       AND NOT EXISTS (SELECT 1 FROM ckp.instances s
                        WHERE s.body->>'type' = N||'Supersession'
                          AND s.body->>(N||'supersedes') = i.body->>'@id')
  LOOP
    v_find := v_find || jsonb_build_array(
      'DANGLING derivedBy: affordance '||r.id||' names '||r.ref||' — no sealed Materialization. '||
      'The root says a hand-registered action cannot hide; body locality means the gate cannot enforce it.');
  END LOOP;

  FOR r IN
    SELECT i.id, i.body->>(N||'inShape') AS ref FROM ckp.instances i
     WHERE i.body->>'type' = N||'Affordance' AND i.body ? (N||'inShape')
       AND ckp._affordance_schema(i.body->>(N||'inShape'), v_comp) IS NULL
       -- withdrawal is a sealed act (Supersession), never a delete: a superseded
       -- affordance is out of force and must not keep raising.
       AND NOT EXISTS (SELECT 1 FROM ckp.instances s
                        WHERE s.body->>'type' = N||'Supersession'
                          AND s.body->>(N||'supersedes') = i.body->>'@id')
  LOOP
    v_find := v_find || jsonb_build_array(
      'UNRESOLVABLE inShape: affordance '||r.id||' names '||r.ref||' — not in the composed surface, '||
      'so no input contract can be derived for it.');
  END LOOP;

  FOR r IN
    SELECT i.id, i.body->>(N||'adopts') AS ref FROM ckp.instances i
     WHERE i.body->>'type' = N||'Adoption' AND i.body ? (N||'adopts')
       AND NOT EXISTS (SELECT 1 FROM ckp.instances m
                        WHERE m.body->>'type' = N||'Module'
                          AND m.body->>'@id' = i.body->>(N||'adopts'))
  LOOP
    v_find := v_find || jsonb_build_array(
      'ADOPTION without a sealed Module: '||r.id||' adopts '||r.ref||' — the digest it claims to '||
      'pin is not on the ledger.');
  END LOOP;

  -- 4. The §4.5 worked examples: a Grant must target an Organ, a Membership must
  -- hold a Role. Zero rows today; the check exists so the first wrong one is seen.
  FOR r IN
    SELECT i.id, i.body->>(N||'permTarget') AS ref FROM ckp.instances i
     WHERE i.body->>'type' = N||'Grant' AND i.body ? (N||'permTarget')
       AND NOT EXISTS (SELECT 1 FROM ckp.instances o
                        WHERE o.body->>'@id' = i.body->>(N||'permTarget')
                          AND o.body->>'type' IN (N||'Organ', N||'CK', N||'TOOL', N||'DATA'))
  LOOP
    v_find := v_find || jsonb_build_array('GRANT targets a non-Organ: '||r.id||' -> '||r.ref);
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true, 'kernel', v_proj,
    'sealed_rows', v_total,
    'unattributed', v_unattr,
    'historical', jsonb_build_object('pre_governance_vacuous_seals', v_vac,
      'note', 'sealed before the root was in force; unfixable and legitimate — fence, never backfill'),
    'vacuous_seals_live', v_vac_new,
    'findings', v_find,
    'healthy', jsonb_array_length(v_find) = 0);
END;
$function$
;
CREATE OR REPLACE FUNCTION ckp.authority_of(p_participant text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  N      text := 'https://conceptkernel.org/ontology/v3.11/core#';
  P      text := 'urn:ckp:participant:';
  v_in   text := COALESCE(p_participant, NULLIF(current_setting('ckp.requester', true), ''));
  v_anon boolean := v_in IS NULL;
  v_urn  text; v_bare text; v_forms text[];
  v_mem jsonb; v_grants jsonb;
BEGIN
  IF v_anon THEN
    RETURN jsonb_build_object('ok', true, 'identity', NULL, 'identityCanonical', NULL,
      'tier', 'anonymous', 'memberships', '[]'::jsonb, 'grants', '[]'::jsonb,
      'note', 'anonymous tier: no verified identity, so no authority chain exists to resolve. '||
              'Transport grants (events-only, no publish) are minted at admission and are not '||
              'readable here — see SPEC.PGCK.IDENTITY-PATH.');
  END IF;

  -- Both spellings of one identity. The door supplies the bare uuid; sealed
  -- Memberships carry the urn: form. Neither is normalised away, because which
  -- one is canonical at the REQUESTER is a separate question from which one is
  -- stored, and this function must answer correctly under either answer.
  IF v_in LIKE P||'%' THEN
    v_urn := v_in;  v_bare := substring(v_in from length(P)+1);
  ELSE
    v_bare := v_in; v_urn := P||v_in;
  END IF;
  v_forms := ARRAY[v_urn, v_bare];

  SELECT jsonb_agg(jsonb_build_object('membership', m.body->>'@id',
                                      'memberOf',  m.body->>(N||'memberOf'),
                                      'holdsRole', m.body->>(N||'holdsRole')))
    INTO v_mem
  FROM ckp.instances m
  WHERE m.body->>'type' = N||'Membership'
    AND m.body->>(N||'memberIs') = ANY(v_forms);

  WITH held AS (
    SELECT r.body AS rbody, r.body->>'@id' AS role_iri
      FROM ckp.instances r
     WHERE r.body->>'type' = N||'Role'
       AND r.body->>'@id' IN (SELECT m.body->>(N||'holdsRole')
                                FROM ckp.instances m
                               WHERE m.body->>'type' = N||'Membership'
                                 AND m.body->>(N||'memberIs') = ANY(v_forms))
  ),
  via_role AS (
    SELECT g.body AS gbody, h.role_iri
      FROM held h
      CROSS JOIN LATERAL jsonb_array_elements_text(
             CASE jsonb_typeof(h.rbody->(N||'grant'))
               WHEN 'array'  THEN h.rbody->(N||'grant')
               WHEN 'string' THEN jsonb_build_array(h.rbody->(N||'grant'))
               ELSE '[]'::jsonb
             END) AS gi(iri)
      JOIN ckp.instances g
        ON g.body->>'@id' = gi.iri
       AND g.body->>'type' = N||'Grant'
  ),
  via_granted AS (
    SELECT g.body AS gbody, h.role_iri
      FROM held h
      JOIN ckp.instances g
        ON g.body->>'type' = N||'Grant'
       AND g.body->>(N||'grantedVia') = h.role_iri
  ),
  merged AS (
    SELECT DISTINCT ON (gbody->>'@id') gbody, role_iri
      FROM (SELECT * FROM via_role UNION ALL SELECT * FROM via_granted) u
     ORDER BY gbody->>'@id', role_iri
  )
  SELECT jsonb_agg(jsonb_build_object(
           'grant',      gbody->>'@id',
           'permTarget', gbody->>(N||'permTarget'),
           'permAction', gbody->>(N||'permAction'),
           'permDomain', gbody->>(N||'permDomain'),
           'permission', gbody->>(N||'permission'),
           'viaRole',    role_iri))
    INTO v_grants
    FROM merged;

  RETURN jsonb_build_object('ok', true,
    'identity', v_in, 'identityCanonical', v_urn, 'tier', 'verified',
    'memberships', COALESCE(v_mem, '[]'::jsonb),
    'grants', COALESCE(v_grants, '[]'::jsonb),
    'note', CASE
      WHEN v_mem IS NULL
        THEN 'no sealed Membership for this identity — the authority chain is EMPTY, which is '||
             'not the same as unchecked. Both the bare and urn:ckp:participant: spellings were '||
             'tried. Dispatch is currently governed by the transport tier and the role floor, '||
             'not by this chain.'
      WHEN v_grants IS NULL
        THEN 'this identity holds a Membership and a Role, and that Role reaches NO Grant. '||
             'The chain resolves and TERMINATES — reported as a result, not as silence.'
      ELSE NULL END);
END;
$function$
;
CREATE OR REPLACE FUNCTION ckp._dispatch_safe(p_verb text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  v_out jsonb;
BEGIN
  v_out := ckp.dispatch(p_verb, p_payload);
  RETURN v_out;
EXCEPTION
  WHEN OTHERS THEN
    -- The refusal is the RESULT. Carry the clause the gate named, plus SQLSTATE
    -- so a caller can tell a shape refusal from a transport fault, and keep the
    -- verb so a Trace-Id correlation still resolves. Never re-raise: re-raising
    -- is what killed the worker.
    --
    -- 0.4.71 — RESET THE ENGINE'S TERM CACHE after the aborted subtransaction.
    -- Any term FIRST-interned inside the abort is poisoned: it stores but SHACL
    -- cannot see it, so a caller's RETRY reusing the same fresh IRIs refuses
    -- with "MinCount not satisfied" on a field its body demonstrably carries.
    -- Measured three times on this wave (s56's flake class, s64's build, and
    -- pgck's own reconciliation seal taking three attempts); the suites carry
    -- per-file resets, but door callers had no protection until here — the
    -- catch block is the one place that KNOWS an abort just happened. Guarded:
    -- engines without the remedy skip silently, and a reset failure must never
    -- eat the refusal we owe the caller.
    BEGIN
      IF to_regprocedure('pgrdf.shmem_reset()') IS NOT NULL THEN
        PERFORM pgrdf.shmem_reset();
      END IF;
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    RETURN jsonb_build_object(
      'ok',      false,
      'refused', true,
      'verb',    p_verb,
      'sqlstate', SQLSTATE,
      'error',   SQLERRM
    );
END;
$function$;

COMMENT ON FUNCTION ckp._dispatch_safe(text, jsonb) IS
  'Transport-safe wrapper over ckp.dispatch. A gate refusal is returned as data '
  '({ok:false, refused:true, sqlstate, error}) instead of raising, because an '
  'unhandled RAISE inside the bgworker SPI call unwinds as a pgrx panic and '
  'terminates the worker — taking the auth-callout responder with it and closing '
  'the door for every client (measured 2026-08-11, pgck-bridge exit code 1).';

CREATE OR REPLACE FUNCTION ckp.germinate_kernel(p_project text, p_label text DEFAULT NULL,
                                                -- 0.4.81: DEFAULT NULL, not
                                                -- 'personal'. NULL is the ABSENCE
                                                -- itself; ProjectShape then refuses
                                                -- on minCount/sh:in and names the
                                                -- clause, instead of the substrate
                                                -- choosing a kind nobody asked for.
                                                p_kind text DEFAULT NULL)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  v_sub   text := NULLIF(current_setting('ckp.requester', true), '');
  v_owner text;
  v_label text := COALESCE(p_label, p_project);
  v_iri   text := format('urn:ckp:%s/kernel/ck', p_project);
  v_g     int;
  v_ttl   text;
  v_base  text := format('urn:ckp:%s', p_project);
  v_kid   text := format('urn:ckp:%s/kernel', p_project);
  v_pid   text := format('urn:ckp:project:%s', p_project);
BEGIN
  IF p_project IS NULL OR btrim(p_project) = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'project required');
  END IF;
  -- The transport segment is one NATS token. A dotted name can never be granted
  -- (configured_kernels drops it), so germinating one would build a kernel nobody
  -- can ever reach. Refuse at the door with the slug it should use.
  -- p_project is ONE transport segment, not an IRI. The metacharacter test alone
  -- let ':' and '/' through, so a caller passing the project URN
  -- ('urn:ckp:project:ck-lib-js') germinated a graph named
  -- <urn:ckp:urn:ckp:project:ck-lib-js/kernel/ck> -- structurally valid, and
  -- reachable by nobody. Measured on the bench: 22 asserted triples in exactly
  -- that graph. Require a bare segment; the metacharacter case keeps its own
  -- message because the slug is actionable there.
  IF p_project ~ '[.*> \t\r\n]' THEN
    RETURN jsonb_build_object('ok', false, 'refused', true,
      'error', format('kernel id %L carries a NATS subject metacharacter, so it can never be granted. Use %L.',
                      p_project, ckp._slug(p_project)));
  END IF;
  IF p_project !~ '^[a-z0-9]+(-[a-z0-9]+)*$' THEN
    RETURN jsonb_build_object('ok', false, 'refused', true,
      'error', format('kernel id %L is not canonical. A project name is lowercase, dashes optional, one transport segment -- use %L.',
                      p_project, ckp._slug(regexp_replace(p_project, '^.*[:/]', ''))));
  END IF;
  -- IDENTITY IS SERVER-DERIVED. No verified connection, no owner, no germination —
  -- fail closed rather than mint an unowned project or invent an owner.
  IF v_sub IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'refused', true,
      'error', 'germination requires a verified identity: ckp.ownedBy is stamped from the connection, never supplied. Anonymous callers cannot own a project.');
  END IF;
  v_owner := 'urn:ckp:participant:' || ckp._slug(v_sub);

  -- 1. the structure — Kernel + three organs, counted dependencies, gated authorities
  v_g := pgrdf.add_graph(v_iri);
  PERFORM pgrdf.clear_graph(v_g);
  v_ttl := format($ttl$
@prefix ckp:  <https://conceptkernel.org/ontology/v3.11/core#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
<%1$s/kernel> a ckp:Kernel ; rdfs:label %2$L ; ckp:epoch 0 ;
  ckp:inProject <%3$s> ;
  ckp:hasOrgan <%1$s/organ/ck> , <%1$s/organ/tool> , <%1$s/organ/data> .
<%1$s/organ/ck>   a ckp:Organ , ckp:CK   ; ckp:organKind "ck"   ; ckp:writeAuthority "governed-only" .
<%1$s/organ/tool> a ckp:Organ , ckp:TOOL ; ckp:organKind "tool" ; ckp:writeAuthority "readonly-on-ontology" ;
  ckp:dependsOn <%1$s/organ/ck> .
<%1$s/organ/data> a ckp:Organ , ckp:DATA ; ckp:organKind "data" ; ckp:writeAuthority "readwrite" ;
  ckp:dependsOn <%1$s/organ/ck> , <%1$s/organ/tool> .
$ttl$, v_base, v_label, v_pid);
  PERFORM pgrdf.parse_turtle(v_ttl, v_g, v_iri || '#');
  PERFORM pgrdf.materialize(v_g);
  GRANT ALL ON ALL TABLES    IN SCHEMA pgrdf TO ck_substrate;
  GRANT ALL ON ALL SEQUENCES IN SCHEMA pgrdf TO ck_substrate;

  -- 2. the Project — ownedBy STAMPED, never supplied. This is the triple a client
  --    cannot write and the reason germination is a governed verb at all.
  PERFORM ckp.seal(v_pid, jsonb_build_object(
    'type', 'https://conceptkernel.org/ontology/v3.11/core#Project',
    '@id',  v_pid,
    'http://www.w3.org/2000/01/rdf-schema#label', v_label,
    'https://conceptkernel.org/ontology/v3.11/core#projectKind', p_kind,
    'https://conceptkernel.org/ontology/v3.11/core#ownedBy', v_owner));

  -- 3. the Kernel as a SEALED, ATTRIBUTED fact — so the kernel exists in the ledger
  --    and not only as quads a stranger could have written.
  PERFORM ckp.seal(v_kid, jsonb_build_object(
    'type', 'https://conceptkernel.org/ontology/v3.11/core#Kernel',
    '@id',  v_kid,
    'http://www.w3.org/2000/01/rdf-schema#label', v_label,
    'https://conceptkernel.org/ontology/v3.11/core#epoch', 0,
    'https://conceptkernel.org/ontology/v3.11/core#inProject', v_pid,
    'https://conceptkernel.org/ontology/v3.11/core#hasOrgan',
      -- The organs live at <base>/organ/*, NOT <base>/kernel/organ/*. Both the
      -- graph above and pgCK's own kernel use the former; deriving these from
      -- v_kid (which already ends in /kernel) sealed a Kernel whose hasOrgan
      -- pointed at three resources that do not exist. KernelShape only counts
      -- them and checks nodeKind, so the gate passed and the drift was silent.
      jsonb_build_array(v_base||'/organ/ck', v_base||'/organ/tool', v_base||'/organ/data')));

  RETURN jsonb_build_object('ok', true, 'kernel', v_kid, 'graph', v_iri,
                            'project', v_pid, 'ownedBy', v_owner, 'organs', 3);
END;
$function$;

COMMENT ON FUNCTION ckp.germinate_kernel(text, text, text) IS
  'Governed germination. A client declares its STRUCTURE (Kernel + three organs); the '
  'substrate stamps WHO OWNS IT (ckp:ownedBy) from the verified connection, exactly as '
  'ckp:createdBy is derived — never from the payload. Refuses anonymously, and refuses a '
  'kernel id carrying a NATS subject metacharacter because such a kernel could never be '
  'granted. Replaces the pgRDF route, which lands correct structure that belongs to nobody.';

CREATE OR REPLACE FUNCTION ckp.dispatch(p_verb text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  N      text := 'urn:ckp:board/';
  RL     text := 'http://www.w3.org/2000/01/rdf-schema#label';
  req    jsonb := p_payload->'req';
  res    jsonb;
  v_proj text := ckp._project();
  -- 0.4.80 — NO MANUFACTURED KEY. This COALESCE substituted the literal
  -- 'pgck-localhost' whenever nothing was configured, so absence produced a
  -- shared secret instead of a refusal. The key now comes from ckp.config,
  -- minted per install; ckp.seal already refuses when it is missing, and that
  -- refusal is the point.
  v_idk  text := COALESCE(NULLIF(current_setting('ckp.identity_key', true), ''),
                          (SELECT v FROM ckp.config WHERE k = 'identity_key'));
  v_canon  text;   -- CI-B-2: canonical instance.* name (registry lookup key)
  v_aff    jsonb;  -- CI-B-1: the sealed affordance row (the registry IS the routing authority)
  v_legacy text;   -- CI-B-2: the legacy handler name (alias window)
BEGIN
  PERFORM set_config('ckp.project', v_proj, false);
  PERFORM set_config('ckp.identity_key', v_idk, false);

  -- CI-B-1/B-2 — the sealed registry is the SOLE routing authority. Resolve the canonical
  -- name + its sealed affordance row; an unregistered verb fails typed (unknown_affordance)
  -- with zero payload evaluation (no fallthrough); a delegate=true row is the Tier-2 tool
  -- seam; governance-plane verbs never execute here (proposal/vote/apply — CI-D). Otherwise
  -- resolve the legacy handler name (alias window) so the CASE below is unchanged and v0.3.0
  -- web2 keeps working.
  v_canon := ckp.verb_canon(p_verb);
  -- Resolve against the CALLING project, not a fixed kernel. This asked
  -- registry_lookup('pgck', ...) for every caller, so a verb registered by any
  -- other kernel was invisible and every non-pgck workspace got
  -- unknown_affordance. It looked correct only because the seed and the
  -- registrars were hard-coded to the same literal -- writer and reader wrong
  -- in the same direction. (smoke-s4 s41: registered under 's41-test',
  -- resolved under 'pgck'.)
  v_aff   := ckp.registry_lookup(v_proj, v_canon);
  IF v_aff IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'unknown_affordance', 'verb', p_verb)
      || jsonb_build_object('req', req);
  ELSIF COALESCE((v_aff->>'delegate')::boolean, false) THEN
    RETURN jsonb_build_object('ok', false, 'delegate', true, 'verb', p_verb,
      'error', 'verb delegated to tool tier: '||p_verb) || jsonb_build_object('req', req);
  ELSIF v_aff->>'plane' = 'governance' THEN
    -- CI-D: the governance plane routes to the sealed type-change verbs (propose/vote/apply).
    IF v_canon = 'kernel.propose_change' THEN
      RETURN ckp.propose_change(v_proj, p_payload) || jsonb_build_object('req', req);
    ELSIF v_canon = 'kernel.vote' THEN
      RETURN ckp.vote(p_payload) || jsonb_build_object('req', req);
    ELSIF v_canon = 'kernel.apply' THEN
      RETURN ckp.apply(p_payload) || jsonb_build_object('req', req);
    END IF;
    RETURN jsonb_build_object('ok', false, 'error', 'governance_plane_unavailable',
      'plane', 'governance', 'verb', p_verb, 'canonical', v_canon)
      || jsonb_build_object('req', req);
  -- Tier 2 (3/3b): a governed query affordance (SPARQL text sealed via the governance plane,
  -- compiled into ckp.plans at apply) routes here. The caller binds typed params only; the query
  -- text is the kernel's OWN sealed fact, never caller input.
  ELSIF v_aff->>'plane' = 'query' THEN
    RETURN ckp.run_query_affordance(v_canon, p_payload) || jsonb_build_object('req', req);
  -- Scoring-loop layer 3: a governed DERIVED-read affordance ({formula, scope} sealed via the
  -- governance plane, compiled into ckp.plans at apply) routes here. The caller binds only the
  -- concept; the formula is the kernel's OWN sealed fact. Returns the band-less {ok, value,
  -- scored, freshness} envelope — the role-floor-reachable read surface the scoring client calls.
  ELSIF v_aff->>'plane' = 'derived' THEN
    RETURN ckp.run_derived_affordance(v_canon, p_payload) || jsonb_build_object('req', req);
  END IF;
  -- CI-E-5: instance.query is the typed derived-QueryShape read (the legacy instances.list alias
  -- keeps its list behavior below — routed by the ORIGINAL verb, not the shared canonical).
  IF p_verb = 'instance.query' THEN
    RETURN ckp.query(p_payload) || jsonb_build_object('req', req);
  ELSIF p_verb = 'instance.reach' THEN
    RETURN ckp.reach(p_payload) || jsonb_build_object('req', req);
  ELSIF p_verb = 'instance.transition' THEN
    RETURN ckp.transition(p_payload) || jsonb_build_object('req', req);
  ELSIF p_verb = 'instance.snapshot' THEN
    RETURN ckp.snapshot(p_payload) || jsonb_build_object('req', req);
  ELSIF p_verb = 'concept.match' THEN
    RETURN ckp.concept_match(p_payload) || jsonb_build_object('req', req);
  ELSIF p_verb = 'instance.explain' THEN
    RETURN ckp.explain(p_payload) || jsonb_build_object('req', req);
  ELSIF p_verb = 'instance.retire' THEN
    RETURN ckp.retire(p_payload) || jsonb_build_object('req', req);
  ELSIF p_verb = 'instance.validate' THEN
    RETURN ckp.validate_instance(p_payload) || jsonb_build_object('req', req);
  -- Tier 2 (v0.4.4): generic typed create. A uniform {type:<class IRI>, …fields} body
  -- routes to the §4 generic path, which seals it against the kernel's OWN declared shape.
  -- The discriminator is a TOP-LEVEL `type`: the legacy concretion forms carry no top-level
  -- `type` (task.create -> {task:{…}}, kernel.create -> {name:…}). `name` is NOT a usable
  -- discriminator here — it is a perfectly ordinary property on a generic type — so a `{task}`
  -- body still wins (the established concretion path) but everything else with a `type` is generic.
  -- 0.4.51: `@type` and a nested `{body:{type}}` route here TOO, so the teaching
  -- refusal is reachable. Without this a caller following JSON-LD habit fell
  -- through to the task.create concretion and was told "kernel and title
  -- required" — an error about a verb it did not call, naming fields it never
  -- heard of. create_typed answers `type_not_readable_here` and names the two
  -- shapes that ARE read. Routing on a key it will then refuse is deliberate:
  -- the alternative is a correct-looking error from the wrong handler, which is
  -- the class of misdirection F9 filed.
  ELSIF p_verb = 'instance.create'
        AND (p_payload ? 'type' OR p_payload ? '@type'
             OR (p_payload ? 'body' AND ((p_payload->'body') ? 'type' OR (p_payload->'body') ? '@type')))
        AND NOT (p_payload ? 'task') THEN
    RETURN ckp.create_typed(p_payload) || jsonb_build_object('req', req);
  -- Tier 2 / v0.5 T4: generic typed update. instance.update with a `patch` sub-object patches
  -- by the type's declared properties (re-sealed); the legacy flat {id,…fields} form falls
  -- through to verb_to_legacy -> task.update.
  ELSIF p_verb = 'instance.update' AND (p_payload ? 'patch') THEN
    RETURN ckp.update_typed(p_payload) || jsonb_build_object('req', req);
  END IF;
  v_legacy := ckp.verb_to_legacy(p_verb, p_payload);

  CASE v_legacy

  -- ---- generic URN-addressed instance ops (the main goal) --------------
  WHEN 'instances.list', 'instances.last', 'instances.count', 'instance.get' THEN
    res := ckp._query(v_legacy, p_payload);

  -- ---- discovery -------------------------------------------------------
  -- B4: the surface in force, checked against the digests its epoch sealed.
  -- A READ, never a gate — a false positive here would take the substrate down,
  -- and legitimate drift exists. Findings name what was measured; empty = pass.
  WHEN 'surface.check' THEN
    res := ckp.surface_check(v_proj);

  -- B3: the store-level G-1 audit — the cross-node integrity body locality puts
  -- beyond the instance gate (§4.5). B1a: authority resolved by traversal, with
  -- an empty chain reported AS empty (persona spec §3).
  WHEN 'integrity.check' THEN
    res := ckp.integrity_check(v_proj);

  WHEN 'authority.mine' THEN
    res := ckp.authority_of(NULL);

  -- 0.4.51 — THE CHECKER SURFACE. Every one of these answered a question this
  -- kernel had to answer with a hand-written psql probe in PASS-30, which is a
  -- second surface by definition: a check that lives in someone's scratch
  -- directory cannot be re-run by the party who needs it, and it is not a fact.
  -- As governed verbs they are callable by any identity the kernel grants,
  -- their answers are attributable, and the negative control ships WITH the
  -- gate instead of beside it.
  WHEN 'wave.signals' THEN
    res := ckp.wave_signals(p_payload);

  -- one-version alias (0.4.63): routes, answers, and says where to go. Removed
  -- next release — nothing tagged ever carried the old name.
  WHEN 'wave.oracle' THEN
    res := ckp.wave_signals(p_payload)
        || jsonb_build_object('deprecated', 'wave.oracle is wave.signals; this alias is removed next release');

  WHEN 'adoption.check' THEN
    res := ckp.adoption_check(p_payload);

  WHEN 'wave.project' THEN
    res := ckp.wave_project_spine(p_payload);

  WHEN 'surface.typecheck' THEN
    res := ckp.surface_typecheck(p_payload, v_proj);

  WHEN 'surface.unshaped' THEN
    res := ckp.surface_unshaped(v_proj);

  WHEN 'surface.declared' THEN
    res := ckp.surface_declared(p_payload, v_proj);

  WHEN 'surface.grounding' THEN
    res := ckp.surface_grounding(p_payload, v_proj);

  WHEN 'surface.explain' THEN
    res := ckp.surface_explain(p_payload, v_proj);

  WHEN 'fleet.adoptions' THEN
    res := ckp.fleet_adoptions(p_payload);

  WHEN 'project.resolve' THEN
    res := ckp.project_resolve(p_payload);

  WHEN 'affordances' THEN
    -- B1 (pgCK#56): derived from SEALED ckp:Affordance instances of THIS kernel,
    -- carrying inShape resolved into a real input contract, retirement honoured,
    -- and the registry/sealed drift reported under `unsealed` rather than merged.
    -- Was: an unfiltered SPARQL scan of a graph nobody writes, which returned []
    -- for a substrate holding sealed affordances — reads as "no grants", means
    -- "nothing declared".
    res := ckp.affordances_of(v_proj);

  WHEN 'kernels.list' THEN
    res := jsonb_build_object('ok', true, 'kernels', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('name', COALESCE(body->>RL, regexp_replace(id,'^backlog:','')),
        'id', id, 'urn', 'ckp://Kernel#'||ckp._slug(COALESCE(body->>RL, regexp_replace(id,'^backlog:','')))) ORDER BY id)
      FROM ckp.instances WHERE body->>'type' = N||'Goal' AND id LIKE 'backlog:%'), '[]'::jsonb));

  WHEN 'provenance' THEN
    -- v0.4.15: id-form symmetry — resolve a bare-or-@id ref to the bare id the id-keyed
    -- tables use, so provenance(@id) is no longer a hollow envelope (matches reach/link/get).
    DECLARE tid text := ckp._resolve_id(p_payload->>'id');
    BEGIN
      -- 0.4.66: proofs are PLURAL since obligations (0.4.65). `proof` stays the
      -- byte-proof (the hmac row — what `verified` checks) so existing readers
      -- keep their meaning; `proofs` carries EVERY row, obligations included —
      -- "which agreed checks did this seal pass" must be readable at the door,
      -- or the obligation mark exists only for parties with table access.
      res := jsonb_build_object('ok', true, 'id', tid, 'verified', ckp.verify(tid),
        'body', (SELECT body FROM ckp.instances WHERE id=tid),
        'proof', (SELECT jsonb_build_object('digest',digest,'method',method,'verified_at',verified_at) FROM ckp.proof WHERE about=tid AND method='hmac+sha256' ORDER BY id DESC LIMIT 1),
        'proofs', COALESCE((SELECT jsonb_agg(jsonb_build_object('digest',digest,'method',method,'verified_at',verified_at) ORDER BY id) FROM ckp.proof WHERE about=tid),'[]'::jsonb),
        'ledger', COALESCE((SELECT jsonb_agg(jsonb_build_object('seq',seq,'prev_seq',prev_seq,'body_sha256',body_sha256,'ts',ts) ORDER BY seq) FROM ckp.ledger WHERE instance_id=tid),'[]'::jsonb));
    END;

  WHEN 'instance.verify' THEN
    res := jsonb_build_object('ok', true, 'id', p_payload->>'id', 'verified', ckp.verify(p_payload->>'id'));

  -- ---- participant input (kernel governs by sealing) -------------------
  WHEN 'participant.join' THEN
    res := jsonb_build_object('ok', true, 'sub', p_payload->>'name',
      'urn', 'urn:ckp:participant:'||ckp._slug(p_payload->>'name'));

  -- 0.4.43: germination as a GOVERNED act. kernel.create seals a board Goal and
  -- creates no kernel; the pgRDF route creates a correct kernel that belongs to
  -- nobody. This is the one that does both: client declares structure, substrate
  -- stamps ckp:ownedBy from the verified connection.
  WHEN 'kernel.germinate' THEN
    res := ckp.germinate_kernel(
             COALESCE(p_payload->>'project', p_payload->>'name'),
             p_payload->>'label',
             p_payload->>'projectKind');

  WHEN 'kernel.create' THEN
    DECLARE nm text := p_payload->>'name'; gid text;
    BEGIN
      IF nm IS NULL OR btrim(nm)='' THEN res := jsonb_build_object('ok',false,'error','kernel name required');
      ELSE
        gid := 'backlog:'||nm;
        PERFORM ckp.seal(gid, jsonb_build_object('type', N||'Goal', '@id', 'ckp://Goal#'||gid, N||'goal_id', gid,
          RL, nm, N||'title', nm, N||'created_at', to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"')));
        res := jsonb_build_object('ok',true,'kernel',nm,'id',gid);
      END IF;
    END;

  WHEN 'task.create' THEN
    DECLARE t jsonb := p_payload->'task'; k text := p_payload->'task'->>'target_kernel';
            -- F-A (pgCK#9/#10): identity is SERVER-DERIVED from the verified connection
            -- (the ckp.requester GUC the trusted ingress sets from the NATS-verified bearer),
            -- NEVER the client payload. A payload {sub} is ignored — it cannot forge created_by.
            sub text := current_setting('ckp.requester', true); tid text; qseq int; v_body jsonb;
    BEGIN
      IF k IS NULL OR (p_payload->'task'->>'title') IS NULL THEN
        res := jsonb_build_object('ok',false,'error','kernel and title required');
      ELSE
        SELECT COALESCE(MAX((i.body->>(N||'queue_seq'))::int),0)+1 INTO qseq
          FROM ckp.instances i WHERE i.body->>(N||'target_kernel')=k AND i.body->>'type'=N||'Task';
        tid := 'task-'||(extract(epoch from clock_timestamp())*1e9)::bigint::text;
        v_body := jsonb_build_object('type', N||'Task', '@id', 'ckp://Task#'||tid, N||'task_id', tid,
          N||'title', t->>'title', N||'part_of_goal', 'backlog:'||k, N||'target_kernel', k,
          N||'lifecycle_state', COALESCE(t->>'lifecycle_state','planned'),
          N||'priority', COALESCE(t->'priority','5'::jsonb), N||'queue_seq', to_jsonb(qseq),
          N||'created_at', to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'));
        IF sub IS NOT NULL THEN
          v_body := v_body || jsonb_build_object(N||'created_by','urn:ckp:participant:'||ckp._slug(sub),
                                             'participant', jsonb_build_object('sub', sub));
        END IF;
        PERFORM ckp.seal(tid, v_body);
        res := jsonb_build_object('ok',true,'id',tid,'verified',ckp.verify(tid),
          'proof_digest',(SELECT digest FROM ckp.proof WHERE about=tid ORDER BY id DESC LIMIT 1));
      END IF;
    EXCEPTION WHEN OTHERS THEN res := jsonb_build_object('ok',false,'error',SQLERRM);
    END;

  WHEN 'task.update' THEN
    DECLARE tid text := p_payload->>'id'; cur jsonb; v_fld text;
    BEGIN
      SELECT body INTO cur FROM ckp.instances WHERE id=tid;
      IF cur IS NULL THEN res := jsonb_build_object('ok',false,'error','instance not found');
      ELSE
        cur := cur - 'participant';
        -- Apply EVERY patchable task field the caller sent (closed allow-list = the task
        -- model's mutable properties; never arbitrary keys), preserving JSON type with ->
        -- not ->> so a number stays a number end-to-end. Pre-0.4.3 this hardcoded only
        -- lifecycle_state + priority — it silently dropped title (CK.Lib.Js report 2.1) and
        -- ->> coerced priority 1 → "1" (report 2.2).
        FOREACH v_fld IN ARRAY ARRAY['title','priority','lifecycle_state','part_of_goal','target_kernel'] LOOP
          IF p_payload ? v_fld THEN
            cur := cur || jsonb_build_object(N||v_fld, p_payload->v_fld);
          END IF;
        END LOOP;
        PERFORM ckp.seal(tid, cur);
        res := jsonb_build_object('ok',true,'id',tid,'verified',ckp.verify(tid),
          'proof_digest',(SELECT digest FROM ckp.proof WHERE about=tid ORDER BY id DESC LIMIT 1));
      END IF;
    EXCEPTION WHEN OTHERS THEN res := jsonb_build_object('ok',false,'error',SQLERRM);
    END;

  -- ---- board snapshot (web protocol verb the browser surfaces use) -------
  WHEN 'snapshot.board' THEN
    res := jsonb_build_object('ok', true,
      'kernels', (SELECT coalesce(jsonb_agg(jsonb_build_object('name', i.body->>(N||'title'), 'id', i.id)
                    ORDER BY i.body->>(N||'title')), '[]'::jsonb)
                  FROM ckp.instances i WHERE i.body->>'type' = N||'Goal'),
      'tasks', (SELECT coalesce(jsonb_agg(jsonb_build_object(
                  'id', i.id,
                  'title', i.body->>(N||'title'),
                  'target_kernel', i.body->>(N||'target_kernel'),
                  'part_of_goal', i.body->>(N||'part_of_goal'),
                  'lifecycle_state', i.body->>(N||'lifecycle_state'),
                  'priority', i.body->(N||'priority'),
                  'queue_seq', i.body->(N||'queue_seq'),
                  'created_by', i.body->>(N||'created_by'),
                  'proof_digest', (SELECT p.digest FROM ckp.proof p WHERE p.about = i.id ORDER BY p.id DESC LIMIT 1),
                  'verified', ckp.verify(i.id))
                  ORDER BY i.body->>(N||'target_kernel'), NULLIF(i.body->>(N||'queue_seq'),'')::int), '[]'::jsonb)
                FROM ckp.instances i WHERE i.body->>'type' = N||'Task'));

  -- ---- raw instance bodies — bulk replay for CKHexStore + corpus capture ---
  -- returns the literal IRI-keyed JSON-LD bodies (with @id + type), the shape a
  -- browser quad store ingests and a fixture corpus records (SPEC.CK.HEXSTORE Q4).
  WHEN 'snapshot.bodies' THEN
    DECLARE k text := p_payload->>'kernel';
    BEGIN
      res := jsonb_build_object('ok', true,
        'bodies', (SELECT coalesce(jsonb_agg(i.body ORDER BY i.id), '[]'::jsonb)
                   FROM ckp.instances i
                   WHERE k IS NULL OR i.body->>(N||'target_kernel') = k));
    END;

  -- ---- concept link (Edge) — captured so the structure is recoverable ---
  -- 0.4.51 — THE EDGE CLASS IS THE CALLER'S TO NAME, AND WAS A DEFAULT NOTHING
  -- DECLARED. This sealed N||'Edge' = urn:ckp:board/Edge unconditionally. That
  -- class is declared in ONE file, examples/example.kernel.ttl, which no module
  -- can load (import_module knows {task, goal}), so the path COULD NOT SEAL FOR
  -- ANY PARTICIPANT ON ANY KERNEL SURFACE, regardless of grants — measured by
  -- pgCK.MCP as F6 and re-measured here: SELECT ?g ?p WHERE { GRAPH ?g { ?s ?p
  -- <urn:ckp:board/Edge> } } returns ZERO ROWS fleet-wide.
  --
  -- Worse, 0.4.42's own comment in ckp._type_admitted asserted the exit
  -- condition was met — "urn:ckp:board/{Task,Goal,Edge,Message} now carry shapes
  -- in the project kernel graph". They do not. That sentence is deleted with
  -- this default; a comment claiming a gate is a claim, and R1 applies to
  -- claims about our own code exactly as it applies to shapes.
  --
  -- The kernel declares what an edge IS; the substrate refuses what violates
  -- that. So the class comes from the caller and the property IRIs follow ITS
  -- namespace — the same rule create_typed's fallback already uses. A caller
  -- that names no class is REFUSED with the reason, never sealed under a class
  -- nobody declared.
  WHEN 'edge.create' THEN
    DECLARE src text := p_payload->>'source'; pred text := p_payload->>'predicate';
            tgt text := p_payload->>'target'; eid text; topic text;
            v_etype text := NULLIF(btrim(COALESCE(p_payload->>'type','')), '');
            v_ens   text;
            v_dpred jsonb := ckp.declared_predicates(v_proj);   -- T2: declared predicate set
    BEGIN
      IF src IS NULL OR pred IS NULL OR tgt IS NULL THEN
        res := jsonb_build_object('ok',false,'error','source, predicate, target required');
      ELSIF v_etype IS NULL THEN
        res := jsonb_build_object('ok',false,'refused',true,'error','edge_type_required',
          'hint','instance.link requires {type}: the edge class THIS kernel declares (sh:targetClass or a declared rdfs:Class/owl:Class in its composed surface). There is no substrate default — the former one, urn:ckp:board/Edge, is declared by no loadable module and could never seal.');
      ELSIF position(':' in v_etype) = 0 THEN
        res := jsonb_build_object('ok',false,'refused',true,'error','type_must_be_iri',
          'hint','instance.link {type} must be the full class IRI, e.g. urn:ckp:<project>/type/Edge');
      ELSIF src = tgt THEN
        res := jsonb_build_object('ok',false,'error','no self-loops (v3.7 Edge rule)');
      -- T2 (v0.4.9): when the kernel declares predicates, the link predicate MUST be one of them;
      -- a kernel that declares none stays permissive (back-compat).
      ELSIF jsonb_array_length(v_dpred) > 0 AND NOT (v_dpred @> to_jsonb(pred)) THEN
        res := jsonb_build_object('ok',false,'error','undeclared_predicate','predicate',pred,'declared',v_dpred);
      ELSE
        v_ens := regexp_replace(v_etype, '[^/#]*$', '');    -- the declared class's namespace
        eid := 'edge:'||src||'.'||pred||'.'||tgt;
        topic := 'link.'||pred||'.'||src||'.'||tgt;
        PERFORM ckp.seal(eid, jsonb_build_object('type', v_etype, '@id', 'ckp://Edge#'||eid,
          v_ens||'source', src, v_ens||'predicate', pred, v_ens||'target', tgt, v_ens||'topic', topic,
          v_ens||'created_at', to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"')));
        -- Tier 2 (3/3a): also materialize the traversable quad so instance.reach finds
        -- this participant-created link (the Edge instance alone is not traversable).
        res := jsonb_build_object('ok',true,'id',eid,'type',v_etype,'topic',topic,'verified',ckp.verify(eid),
          'reachable', ckp.materialize_edge(src, pred, tgt, v_proj));
      END IF;
    EXCEPTION WHEN OTHERS THEN res := jsonb_build_object('ok',false,'error',SQLERRM);
    END;

  -- ---- a message over a link (the automated pigeon) — sealed = recoverable
  -- 0.4.51 — the SAME defect as edge.create, one class along, and untested by
  -- the party who found the first: this sealed N||'Message' = urn:ckp:board/
  -- Message, declared by no loadable module, so notify could not seal either.
  -- The class is the caller's to name; the property IRIs follow its namespace.
  WHEN 'notify' THEN
    DECLARE frm text := p_payload->>'from'; tgt text := p_payload->>'to';
            pred text := p_payload->>'predicate';
            -- F-A: server-derived identity (verified connection), never the payload (see task.create).
            bdy text := p_payload->>'body'; sub text := current_setting('ckp.requester', true); mid text; topic text; v_body jsonb;
            v_mtype text := NULLIF(btrim(COALESCE(p_payload->>'type','')), '');
            v_mns   text;
    BEGIN
      IF frm IS NULL OR tgt IS NULL OR bdy IS NULL THEN
        res := jsonb_build_object('ok',false,'error','from, to, body required');
      ELSIF v_mtype IS NULL THEN
        res := jsonb_build_object('ok',false,'refused',true,'error','message_type_required',
          'hint','notify requires {type}: the message class THIS kernel declares. There is no substrate default — the former one, urn:ckp:board/Message, is declared by no loadable module and could never seal.');
      ELSIF position(':' in v_mtype) = 0 THEN
        res := jsonb_build_object('ok',false,'refused',true,'error','type_must_be_iri',
          'hint','notify {type} must be the full class IRI, e.g. urn:ckp:<project>/type/Message');
      ELSE
        v_mns := regexp_replace(v_mtype, '[^/#]*$', '');
        mid := 'msg-'||(extract(epoch from clock_timestamp())*1e9)::bigint::text;
        topic := 'link.'||pred||'.'||frm||'.'||tgt;
        v_body := jsonb_build_object('type', v_mtype, '@id', 'ckp://Message#'||mid,
          v_mns||'from', frm, v_mns||'to', tgt, v_mns||'predicate', pred, v_mns||'body', bdy, v_mns||'topic', topic,
          v_mns||'created_at', to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'));
        IF sub IS NOT NULL THEN v_body := v_body || jsonb_build_object(v_mns||'created_by','urn:ckp:participant:'||ckp._slug(sub)); END IF;
        PERFORM ckp.seal(mid, v_body);
        res := jsonb_build_object('ok',true,'id',mid,'type',v_mtype,'topic',topic,'verified',ckp.verify(mid),
          'proof_digest',(SELECT digest FROM ckp.proof WHERE about=mid ORDER BY id DESC LIMIT 1));
      END IF;
    EXCEPTION WHEN OTHERS THEN res := jsonb_build_object('ok',false,'error',SQLERRM);
    END;

  -- ---- unknown verb = the Tier-2 tool-delegation seam ------------------
  ELSE
    res := jsonb_build_object('ok', false, 'delegate', true,
      'error', 'verb not governed in-kernel: '||p_verb);
  END CASE;

  RETURN res || jsonb_build_object('req', req);
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp.enqueue_materialize(p_concept text, p_scope jsonb, p_formula text, p_epoch bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE wm bigint := ckp._source_watermark(p_scope);
BEGIN
  INSERT INTO ckp.materialize_job(concept,scope,formula,epoch,watermark,phase)
  VALUES (p_concept,p_scope,p_formula,p_epoch,wm,'queued')
  ON CONFLICT (concept) DO UPDATE SET scope=EXCLUDED.scope, formula=EXCLUDED.formula,
    epoch=EXCLUDED.epoch, watermark=EXCLUDED.watermark, enqueued_at=now();
  RETURN jsonb_build_object('ok',true,'recompute_in_progress',true);
END $function$
;

CREATE OR REPLACE FUNCTION ckp.explain(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  v_id   text := p_payload->>'id';
  v_body jsonb;
  v_mat  jsonb;
BEGIN
  SELECT body INTO v_body FROM ckp.instances WHERE id = v_id;
  IF v_body IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'unknown_instance', 'id', v_id);
  END IF;
  -- direct-vs-inferred from the engine is_inferred column (graph-wide summary for the alpha;
  -- the per-node derivation chain is deferred — engine ask #1).
  BEGIN
    SELECT jsonb_build_object('direct',   count(*) FILTER (WHERE NOT is_inferred),
                              'inferred', count(*) FILTER (WHERE is_inferred))
    INTO v_mat FROM pgrdf._pgrdf_quads;
  EXCEPTION WHEN OTHERS THEN
    v_mat := jsonb_build_object('note', 'is_inferred available; counts unavailable: '||SQLERRM);
  END;
  RETURN jsonb_build_object('ok', true, 'id', v_id, 'materialization', v_mat,
                            'derivation_chain', 'deferred (engine ask #1)');
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp.has_grant(p_grantee text, p_perm text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$ SELECT EXISTS (SELECT 1 FROM ckp.grants WHERE grantee = p_grantee AND permission = p_perm); $function$
;

CREATE OR REPLACE FUNCTION ckp.ledger_to_outbox()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  v_body JSONB;
  v_proj TEXT;
BEGIN
  SELECT body INTO v_body FROM ckp.instances WHERE id = NEW.instance_id;
  IF v_body IS NULL THEN
    -- ledger row without a matching instance row should not happen
    -- (ckp.seal() inserts instance before ledger); skip rather than fail
    RETURN NEW;
  END IF;

  -- The producing kernel comes from the SEALED producedBy stamp
  -- (urn:ckp:<project>/kernel/ck) -- substrate-derived and unforgeable -- not
  -- from session state, which by trigger time may belong to another caller.
  v_proj := NULLIF(regexp_replace(
              COALESCE(v_body->>'https://conceptkernel.org/ontology/v3.11/core#producedBy',''),
              '^urn:ckp:(.*)/kernel/ck$', '\1'), '');
  IF v_proj IS NULL OR v_proj = v_body->>'https://conceptkernel.org/ontology/v3.11/core#producedBy' THEN
    v_proj := ckp._project();
  END IF;

  INSERT INTO ckp.outbox(ledger_seq, subject, payload, headers)
  VALUES (
    NEW.seq,
    ckp.compute_publish_subject(v_body->>'type', v_proj),
    convert_to(v_body::text, 'UTF8'),
    jsonb_build_object(
      'Ck-Seq',        NEW.seq::text,
      'Content-Type',  'application/json'
    )
    -- F4 (msg.by): stamp the server-attributed sender `by` so peers (kernels, web bots, users) see
    -- who-said-what WITHOUT the client asserting it. `created_by` derives from the VERIFIED
    -- ckp.requester (F-A), never a client field — so `by` is un-forgeable.
    -- `by` reads the DERIVED core stamp first. It keyed only on the v3.8-era
    -- board property, which 5 instances carry against 73 with core createdBy --
    -- so after the 0.4.44 identity work the header was absent on virtually
    -- everything, and a subscriber could not tell who said what. Board form
    -- kept as the legacy fallback.
    || CASE WHEN v_body ? 'https://conceptkernel.org/ontology/v3.11/core#createdBy'
            THEN jsonb_build_object('by', v_body->>'https://conceptkernel.org/ontology/v3.11/core#createdBy')
            WHEN v_body ? 'urn:ckp:board/created_by'
            THEN jsonb_build_object('by', v_body->>'urn:ckp:board/created_by')
            ELSE '{}'::jsonb END
  );

  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp.materialize_drain_once()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE j record; giri text; wm bigint;
BEGIN
  SELECT concept, scope, formula, epoch INTO j
  FROM ckp.materialize_job ORDER BY enqueued_at LIMIT 1 FOR UPDATE SKIP LOCKED;
  IF NOT FOUND THEN RETURN 0; END IF;
  wm   := ckp._source_watermark(j.scope);
  giri := ckp._epsilon_materialize(j.concept, j.scope, j.formula, j.epoch);
  PERFORM ckp._phenotype_publish(j.concept, giri, j.epoch, wm, now()+interval '1 hour');
  DELETE FROM ckp.materialize_job WHERE concept = j.concept;
  RETURN 1;
END $function$
;

CREATE OR REPLACE FUNCTION ckp.materialize_edge(p_src text, p_pred text, p_tgt text, p_project text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  v_iri_re text := '^[A-Za-z][A-Za-z0-9+.:#/_-]*$';   -- no quote/space/newline/'>' reaches the TTL
  v_src    text := ckp._resolve_ref(p_src);           -- bare id -> @id IRI (else NULL)
  v_tgt    text := ckp._resolve_ref(p_tgt);
  v_pred   text := CASE WHEN position(':' in COALESCE(p_pred,'')) > 0
                        THEN p_pred                                     -- already an IRI: as-is
                        ELSE 'urn:ckp:board/' || p_pred END;  -- short -> v3.7 IRI
  v_g      bigint;
BEGIN
  -- materialize only when both endpoints resolved to clean absolute IRIs (all three injection-gated).
  IF v_src IS NULL OR v_tgt IS NULL
     OR position(':' in v_src) = 0 OR position(':' in v_tgt) = 0
     OR v_src !~ v_iri_re OR v_pred !~ v_iri_re OR v_tgt !~ v_iri_re THEN
    RETURN false;
  END IF;
  v_g := pgrdf.add_graph(format('urn:ckp:%s/edges', p_project));   -- per-project edge graph (get-or-create)
  PERFORM pgrdf.parse_turtle(format('<%s> <%s> <%s> .', v_src, v_pred, v_tgt),
                             v_g, format('urn:ckp:%s/edges#', p_project));
  RETURN true;
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp.plan_exec(p_kernel text, p_verb text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  v_epoch  integer;
  v_plan   jsonb;
  v_stmt   text;
  v_wrap   text;
  v_np     integer;
  a1       text;
  a2       text;
  v_result jsonb;
BEGIN
  SELECT epoch INTO v_epoch FROM ckp.kernel_epoch WHERE kernel = p_kernel;
  v_epoch := COALESCE(v_epoch, 1);
  SELECT plan INTO v_plan FROM ckp.plans WHERE kernel = p_kernel AND verb = p_verb AND epoch = v_epoch;
  IF v_plan IS NULL THEN
    -- CI-C-2: a missing plan at the current epoch forces recompile-then-retry inside the call.
    PERFORM ckp.compile_plans(p_kernel);
    SELECT plan INTO v_plan FROM ckp.plans WHERE kernel = p_kernel AND verb = p_verb AND epoch = v_epoch;
  END IF;
  IF v_plan IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'no_plan', 'verb', p_verb, 'epoch', v_epoch);
  END IF;
  v_stmt := v_plan->>'statement';
  v_wrap := format('SELECT jsonb_agg(t) FROM (%s) t', v_stmt);
  v_np   := COALESCE(jsonb_array_length(v_plan->'params'), 0);
  -- caller VALUES only, in the plan's declared param order — bound, never concatenated.
  IF v_np >= 1 THEN a1 := p_payload->>(v_plan->'params'->>0); END IF;
  IF v_np >= 2 THEN a2 := p_payload->>(v_plan->'params'->>1); END IF;
  IF    v_np = 0 THEN EXECUTE v_wrap INTO v_result;
  ELSIF v_np = 1 THEN EXECUTE v_wrap INTO v_result USING a1;
  ELSIF v_np = 2 THEN EXECUTE v_wrap INTO v_result USING a1, a2;
  ELSE  RAISE EXCEPTION 'plan_exec: > 2 bound params not supported yet (verb %, np %)', p_verb, v_np;
  END IF;
  RETURN jsonb_build_object('ok', true, 'verb', p_verb, 'epoch', v_epoch,
                            'rows', COALESCE(v_result, '[]'::jsonb));
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp.project_instance_label()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  N      text := 'urn:ckp:board/';
  RL     text := 'http://www.w3.org/2000/01/rdf-schema#label';
  v_type text := NEW.body->>'type';
  v_id   text := COALESCE(NEW.body->>'@id', 'urn:ckp:instance:'||NEW.id);
  v_lbl  text;
  v_proj text := ckp._project();
  v_g    bigint;
BEGIN
  v_lbl := COALESCE(NEW.body->>RL, NEW.body->>'rdfs:label',
                    NEW.body->>(N||'title'), NEW.body->>'title',
                    NEW.body->>(N||'name'), NEW.body->>'name');
  -- only label-bearing, well-formed instances are projected (Proposals/Votes/Edges have no label).
  IF v_lbl IS NULL OR v_type IS NULL OR v_id !~ '^[A-Za-z][A-Za-z0-9+.:#/_-]*$' THEN
    RETURN NEW;
  END IF;
  BEGIN
    -- DETERMINISTIC HIGH graph id per project (NOT the IRI-variant auto-id, which assigns the lowest
    -- free id and would steal the reserved core(1)/kernel(2) ids if a write lands before ckp.boot — the
    -- s34 fresh-cluster failure). 1.3e9 + hash keeps it clear of every auto-assigned scratch/board id.
    v_g := 1300000000 + (abs(hashtext(format('urn:ckp:%s/instances', v_proj))) % 90000000);
    PERFORM pgrdf.add_graph(v_g, format('urn:ckp:%s/instances', v_proj));
    PERFORM pgrdf.parse_turtle(
      format('<%s> a <%s> ; <%s> "%s" .', v_id, v_type, RL,
             replace(replace(v_lbl, '\', '\\'), '"', '\"')),
      v_g, format('urn:ckp:%s/instances#', v_proj));
  EXCEPTION WHEN OTHERS THEN
    NULL;  -- projection is a search index, never a write-path gate: a failure must not fail the seal.
  END;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp.project_links(p_project text, p_instance_id text, p_body jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  v_type        text := p_body->>'type';
  v_short_type  text;
  v_board_iri   text := format('urn:ckp:%s/kernel/board', p_project);
  v_board_g     bigint;
  v_scratch_iri text;
  v_scratch_g   bigint;
  v_id          text;
  v_goal_id     text;
  v_kernel      text;
  v_label       text;
  v_subject     text;
  v_ttl         text;
  v_validation  jsonb;
  v_results     jsonb;
  v_added       bigint := 0;
BEGIN
  -- Class detection: only Task and Goal project link triples in v0.1.
  IF v_type ILIKE '%/Task' OR v_type = 'ckp:Task' THEN
    v_short_type := 'Task';
  ELSIF v_type ILIKE '%/Goal' OR v_type = 'ckp:Goal' THEN
    v_short_type := 'Goal';
  ELSE
    RETURN 0;
  END IF;

  -- Build the Turtle that represents this instance's link triples.
  IF v_short_type = 'Task' THEN
    v_id      := p_body->>'urn:ckp:board/task_id';
    v_goal_id := p_body->>'urn:ckp:board/part_of_goal';
    v_kernel  := p_body->>'urn:ckp:board/target_kernel';

    -- Bodies missing any required link field reach the SHACL gate below
    -- with an empty/partial scratch graph — the gate catches them and
    -- rolls back the seal. That keeps the rejection path single-sourced.
    v_subject := 'ckp://Task#' || ckp.urn_normalise(COALESCE(v_id, p_instance_id));

    v_ttl := format(
      '@prefix ckp: <https://conceptkernel.org/ontology/v3.11/core#> . '
      || '<%s> a ckp:Task',
      v_subject);

    IF v_goal_id IS NOT NULL THEN
      v_ttl := v_ttl || format(
        ' ; ckp:part_of_goal <ckp://Goal#%s>',
        ckp.urn_normalise(v_goal_id));
    END IF;
    IF v_kernel IS NOT NULL THEN
      v_ttl := v_ttl || format(
        ' ; ckp:target_kernel <ckp://Kernel#%s>',
        ckp.urn_normalise(v_kernel));
    END IF;
    v_ttl := v_ttl || ' .';

  ELSIF v_short_type = 'Goal' THEN
    v_id    := p_body->>'urn:ckp:board/goal_id';
    v_label := p_body->>'urn:ckp:board/title';

    v_subject := 'ckp://Goal#' || ckp.urn_normalise(COALESCE(v_id, p_instance_id));

    v_ttl := format(
      '@prefix ckp:  <https://conceptkernel.org/ontology/v3.11/core#> . '
      || '@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> . '
      || '<%s> a ckp:Goal',
      v_subject);

    IF v_label IS NOT NULL THEN
      v_ttl := v_ttl || format(
        ' ; rdfs:label "%s"',
        replace(v_label, '"', '\"'));
    END IF;
    v_ttl := v_ttl || ' .';
  END IF;

  -- CKB-4 pre-flight: refuse to validate if the project board's shapes
  -- are missing (stale /ontology/ mount, project never imported the
  -- modules, etc.). shapes_self_test RAISES on missing shape — propagate.
  PERFORM ckp.shapes_self_test(p_project);

  -- Project into a private scratch graph so the gate decides whether the
  -- triples ever land in the board. add_graph is get-or-create; clear
  -- before parse so a duplicate seal (same id) doesn't pollute.
  v_board_g     := pgrdf.add_graph(v_board_iri);
  v_scratch_iri := format('urn:ckp:%s/seal-scratch/%s', p_project, p_instance_id);
  v_scratch_g   := pgrdf.add_graph(v_scratch_iri);
  PERFORM pgrdf.clear_graph(v_scratch_g);
  PERFORM pgrdf.parse_turtle(v_ttl, v_scratch_g, 'urn:ckp:projection#');

  -- SHACL gate — against the COMPOSED SURFACE, the same law ckp.seal reads.
  -- 0.4.82: this validated against the BOARD graph, which nothing seeds since
  -- the board vocabulary retired from CORE (0.4.51) — get-or-create minted it
  -- empty, and pgRDF 0.6.34's vacuity refusal exposed the path (pgRDF#134,
  -- resolved as ours; the refusal was correct). The composed surface is the one
  -- law (F10). KNOWN RESIDUE, deliberately not fixed in this release: the link
  -- TTL above types core#Task/core#Goal — IRIs no surface declares — so this
  -- gate selects ZERO focus nodes and passes silently; the SEAL gate remains
  -- the real law (a board-declaring project's Task is judged there, M4 =
  -- board/shape/Task, measured). The projection namespace mismatch is
  -- tests/v312-tdd case 16's RED and the next train's fix; changing projection
  -- semantics mid-release would break the oci-germination bundle agreements.
  v_validation := pgrdf.validate(v_scratch_g, ckp._composed_shapes(p_project));

  IF NOT (v_validation->>'conforms')::boolean THEN
    v_results := v_validation->'results';
    PERFORM pgrdf.drop_graph(v_scratch_g);
    RAISE EXCEPTION 'ckp.seal: SHACL gate rejected % % — % violation(s); first: %',
      v_short_type,
      p_instance_id,
      jsonb_array_length(v_results),
      v_results->0->>'sourceConstraintComponent';
  END IF;

  -- Validation passed: commit the same Turtle into the board graph and
  -- discard the scratch.
  v_added := pgrdf.parse_turtle(v_ttl, v_board_g, 'urn:ckp:projection#');
  PERFORM pgrdf.drop_graph(v_scratch_g);

  RETURN v_added::int;
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp.propose_change(p_kernel_urn text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  C        text := 'https://conceptkernel.org/ontology/v3.11/core#';
  v_core   int  := (SELECT v::int FROM ckp.config WHERE k='core_graph_id');
  -- P0-E (pgCK#28): NO GOVERNED OP WITHOUT A PROJECTOR. An op that cannot
  -- project a change is refused HERE, at propose — never sealed as an inert
  -- "applied" that bumps the epoch and changes nothing. These four have a
  -- projector today: add_class / add_property / set_transition_map translate
  -- via ckp._op_to_ttl; add_affordance registers a query/derived plan at apply.
  -- modify_shape_constraint / set_quorum / set_materialize_policy have none yet
  -- (they would seal and do nothing) — refused until a projector exists,
  -- default-deny per I2. Widening this set requires implementing the projector,
  -- not editing the list. 0.4.65 adds add_proof_obligation (§5b): its projector
  -- is ckp.register_proof_obligation at apply — the obligation registry is the
  -- change it projects, the seal-exit dual of add_affordance's dispatch entry.
  v_ops    text[] := ARRAY['add_class','add_property','set_transition_map','add_affordance','add_proof_obligation'];
  v_op     text := p_payload->>'op';
  -- ckp.dispatch calls this with v_proj -- the bare project SEGMENT ('pgck'),
  -- not a URN, despite the parameter name. Defaulting `about` to it produced a
  -- literal where ProposalShape demands sh:IRI, so EVERY proposal that omitted
  -- `about` was refused. Build the kernel IRI when a bare segment arrives.
  v_about  text := COALESCE(p_payload->>'about',
                            CASE WHEN position(':' in p_kernel_urn) > 0 THEN p_kernel_urn
                                 ELSE 'urn:ckp:'||p_kernel_urn||'/kernel/ck' END);
  v_detail jsonb;
  v_quorum int;
  v_pid    text;
  v_body   jsonb;
  v_ttl    text;
  v_report jsonb;
BEGIN
  -- 1. INJECTION-SAFE FIELD GATE (mirrors ProposalShape; makes step 2's TTL construction safe).
  -- P0-E, SECOND HALF. That the OP has a projector is not enough: the DETAIL must
  -- carry something to project. add_affordance with an empty detail sealed as
  -- `applied`, bumped the epoch, registered nothing, and returned ok:true with
  -- graph_changed:false and no error anywhere -- measured on pgck, epoch 5 is
  -- exactly that inert applied. Refuse at propose, which is what P0-E promised.
  IF v_op = 'add_affordance' THEN
    v_detail := COALESCE(p_payload->'detail', p_payload->'proposalDetail', '{}'::jsonb);
    IF NOT (v_detail ? 'verb') OR NOT (v_detail ? 'query') THEN
      RETURN jsonb_build_object('ok', false, 'error', 'detail_projects_nothing', 'op', v_op,
        'hint', 'add_affordance needs detail.verb and detail.query; without them apply bumps the epoch and registers nothing (P0-E)',
        'got', v_detail);
    END IF;
  END IF;
  -- add_proof_obligation, same P0-E half: an activation must name the obligation,
  -- its target type AND a check from the fixed registry; a deactivation
  -- ({active:false}) needs only the obligation name. The strict parse (IRI
  -- shape, check-in-registry) lives in ckp.register_proof_obligation — refused
  -- again at apply if it fails there; this gate refuses the detail that could
  -- not project anything at all.
  IF v_op = 'add_proof_obligation' THEN
    v_detail := COALESCE(p_payload->'detail', p_payload->'proposalDetail', '{}'::jsonb);
    IF NOT (v_detail ? 'obligation')
       OR (COALESCE(v_detail->>'active','true') <> 'false'
           AND (NOT (v_detail ? 'targetType') OR NOT (v_detail ? 'check'))) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'detail_projects_nothing', 'op', v_op,
        'hint', 'add_proof_obligation needs detail.obligation + detail.targetType + detail.check (or detail.obligation + active:false to deactivate); without them apply bumps the epoch and registers nothing (P0-E)',
        'got', v_detail);
    END IF;
  END IF;
  IF v_op IS NULL OR NOT (v_op = ANY(v_ops)) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'op_has_no_projector', 'op', v_op,
                              'hint', 'a governed op is refused at propose unless it can project a change (P0-E, pgCK#28)',
                              'allowed', to_jsonb(v_ops));
  END IF;
  IF v_about IS NULL OR v_about !~ '^[A-Za-z][A-Za-z0-9+.:#/_-]*$' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_about', 'about', v_about);
  END IF;
  BEGIN
    v_quorum := COALESCE((p_payload->>'requires_quorum')::int, 1);
  EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_requires_quorum',
                              'value', p_payload->>'requires_quorum');
  END;
  IF v_quorum < 1 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_requires_quorum', 'value', v_quorum);
  END IF;

  v_pid := 'proposal-'||(extract(epoch from clock_timestamp())*1e9)::bigint::text;

  -- 2. AUTHORITATIVE SHACL GATE — validate against ProposalShape (core graph). Values are
  --    field-validated above, so this string build cannot inject a triple.
  v_ttl := '@prefix ckp: <'||C||'> .'||chr(10)||
           '@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .'||chr(10)||
           '<ckp://Proposal#'||v_pid||'> a ckp:Proposal ; ckp:about <'||v_about||'> ; '||
           'ckp:proposalState "pending" ; ckp:requiresQuorum "'||v_quorum::text||'"^^xsd:integer ; '||
           'ckp:proposalOp "'||v_op||'" .';
  v_report := ckp.validate_report(v_ttl, v_core);
  IF (v_report->>'conforms') IS DISTINCT FROM 'true' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'shape_violation', 'violations', v_report->'violations');
  END IF;

  -- 3. SEAL the Proposal{pending} — DATA about the type, not yet the type. ckp.seal writes the
  --    instance + ledger + proof HMAC chain.
  v_body := jsonb_build_object(
    'type',              C||'Proposal',
    '@id',               'ckp://Proposal#'||v_pid,
    C||'about',          v_about,
    C||'proposalState',  'pending',
    C||'proposalOp',     v_op,
    C||'requiresQuorum', v_quorum::text,
    -- accept BOTH spellings: the door historically took 'detail' while the
    -- sealed key is 'proposalDetail', so a caller using the name it reads back
    -- silently got {}.
    'proposalDetail',    COALESCE(p_payload->'detail', p_payload->'proposalDetail', '{}'::jsonb)
  );
  PERFORM ckp.seal(v_pid, v_body);

  RETURN jsonb_build_object('ok', true, 'proposal', v_pid, 'proposal_iri', 'ckp://Proposal#'||v_pid,
                            'state', 'pending', 'op', v_op, 'verified', ckp.verify(v_pid));
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp.query(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  v_type    text := p_payload->>'type';
  v_proj    text := ckp._project();
  v_ops     jsonb := '{"eq":"=","neq":"<>","lt":"<","lte":"<=","gt":">","gte":">=","contains":"LIKE"}'::jsonb;
  v_key_re  text := '^[A-Za-z][A-Za-z0-9:#/._-]*$';   -- the unshaped-fallback key gate
  v_propmap jsonb;          -- declared localname -> full path IRI ({} when the type is unshaped)
  v_shaped  boolean;
  v_where   text;
  v_limit   int := LEAST(GREATEST(COALESCE((p_payload->>'limit')::int, 100), 1), 1000);
  v_offset  int := GREATEST(COALESCE((p_payload->>'offset')::int, 0), 0);
  f         jsonb;
  v_op text; v_key_in text; v_key text; v_val text;
  v_sql text; v_result jsonb;
BEGIN
  IF v_type IS NULL OR v_type !~ '^[A-Za-z]' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_type', 'type', v_type);
  END IF;

  -- Derive the type's declared property map. 0.4.51: one definition
  -- (ckp._propmap), and this is the ONE declared exception to it — p_composed
  -- false keeps the kernel-graph read, because v_shaped below turns the map
  -- into a REFUSAL set for filter keys. Widening it here would newly refuse
  -- reads that resolve today against substrate-stamped keys no shape declares.
  -- Held as a named argument with a reason rather than tightened silently.
  v_propmap := ckp._propmap(v_type, v_proj, false);
  v_shaped := (v_propmap <> '{}'::jsonb);

  v_where := format('(body->>%L) = %L', 'type', v_type);   -- base: this instance type only

  FOR f IN SELECT jsonb_array_elements(COALESCE(p_payload->'filter', '[]'::jsonb)) LOOP
    v_op := f->>'op'; v_key_in := f->>'key'; v_val := f->>'value';
    IF NOT (v_ops ? v_op) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'invalid_operator', 'op', v_op,
                                'allowed', (SELECT jsonb_agg(k) FROM jsonb_object_keys(v_ops) k));
    END IF;

    -- KEY RESOLUTION.
    IF v_shaped THEN
      -- shaped type: the key MUST be a declared property (by localname or full IRI).
      IF v_propmap ? v_key_in THEN
        v_key := v_propmap->>v_key_in;                                   -- declared localname -> IRI
      ELSIF v_key_in IS NOT NULL
            AND EXISTS (SELECT 1 FROM jsonb_each_text(v_propmap) e WHERE e.value = v_key_in) THEN
        v_key := v_key_in;                                              -- already a declared full IRI
      ELSE
        RETURN jsonb_build_object('ok', false, 'error', 'undeclared_filter_key',
                                  'key', v_key_in, 'type', v_type,
                                  'declared', (SELECT jsonb_agg(k) FROM jsonb_object_keys(v_propmap) k));
      END IF;
    ELSE
      -- unshaped for THIS session's project (the shape isn't in urn:ckp:<project>/kernel/ck, or
      -- the type is genuinely unshaped). Resolve the key against the ACTUAL instance-body keys —
      -- exact full-IRI OR by localname suffix — so the filter runs against the key the bodies use,
      -- independent of the shape/project read (pgCK#6). Bare-key bodies (localname == key) resolve
      -- to themselves, so s29 back-compat holds.
      IF v_key_in IS NULL OR v_key_in !~ v_key_re THEN
        RETURN jsonb_build_object('ok', false, 'error', 'invalid_filter_key', 'key', v_key_in);
      END IF;
      SELECT bk INTO v_key
      FROM ckp.instances i
      CROSS JOIN LATERAL jsonb_object_keys(i.body) AS bk
      WHERE i.body->>'type' = v_type
        AND (bk = v_key_in OR regexp_replace(bk, '^.*[/#]', '') = v_key_in)
      LIMIT 1;
      IF v_key IS NULL THEN
        -- NEVER a silent [] (pgCK#6): the key maps to no stored property on this type.
        IF EXISTS (SELECT 1 FROM ckp.instances WHERE body->>'type' = v_type) THEN
          RETURN jsonb_build_object('ok', false, 'error', 'unresolved_shape',
                                    'key', v_key_in, 'type', v_type,
                                    'hint', 'no shape for this type in the session project and no instance carries this property key');
        END IF;
        v_key := v_key_in;   -- no instances of this type: the filtered read is legitimately empty
      END IF;
    END IF;

    -- WHERE construction (unchanged operator logic; quote_literal values + enum operators).
    IF v_op = 'contains' THEN
      v_where := v_where || format(' AND (body->>%L) LIKE %L', v_key, '%'||COALESCE(v_val,'')||'%');
    ELSIF v_op IN ('lt','lte','gt','gte') THEN
      IF v_val IS NULL OR v_val !~ '^-?[0-9.]+$' THEN
        RETURN jsonb_build_object('ok', false, 'error', 'invalid_numeric_value', 'op', v_op, 'value', v_val);
      END IF;
      v_where := v_where || format(' AND (body->>%L) ~ ''^-?[0-9.]+$'' AND (body->>%L)::numeric %s %s',
                                   v_key, v_key, v_ops->>v_op, v_val);
    ELSE  -- eq, neq
      v_where := v_where || format(' AND (body->>%L) %s %L', v_key, v_ops->>v_op, v_val);
    END IF;
  END LOOP;

  v_sql := format(
    'SELECT jsonb_agg(jsonb_build_object(''id'', id, ''body'', body) ORDER BY id) '
    'FROM (SELECT id, body FROM ckp.instances WHERE %s ORDER BY id LIMIT %s OFFSET %s) t',
    v_where, v_limit, v_offset);
  EXECUTE v_sql INTO v_result;
  RETURN jsonb_build_object('ok', true, 'type', v_type, 'shaped', v_shaped,
                            'count', COALESCE(jsonb_array_length(v_result), 0),
                            'rows', COALESCE(v_result, '[]'::jsonb));
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp.reach(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  v_from     text := p_payload->>'from';
  v_from_iri text;
  v_via      text := p_payload->>'via';
  v_proj     text := ckp._project();
  v_iri_re   text := '^[A-Za-z][A-Za-z0-9+.:#/_-]*$';
  v_max      int  := COALESCE(NULLIF(current_setting('pgrdf.path_max_depth', true),'')::int, 0);
  v_declared jsonb;
  v_reached  jsonb;
BEGIN
  IF v_from IS NULL OR btrim(v_from) = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_from', 'from', v_from);
  END IF;
  -- id-form: a bare instance id resolves to its @id IRI (the form link/materialize_edge wrote);
  -- an absolute IRI passes through. An unresolvable bare id has nothing to reach FROM.
  v_from_iri := ckp._resolve_ref(v_from);
  IF v_from_iri IS NULL THEN
    RETURN jsonb_build_object('ok', true, 'from', v_from, 'resolved', NULL, 'via', v_via,
                              'max_depth', v_max, 'reached', '[]'::jsonb);
  END IF;
  IF v_from_iri !~ v_iri_re THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_from', 'from', v_from, 'resolved', v_from_iri);
  END IF;
  -- injection-safe IRI gate on `via` (always).
  IF v_via IS NULL OR v_via !~ v_iri_re THEN
    RETURN jsonb_build_object('ok', false, 'error', 'undeclared_predicate', 'via', v_via);
  END IF;
  -- T2: `via` MUST be in the kernel's DECLARED predicate set; a kernel that declares none falls
  -- back to the namespace allowlist (back-compat).
  v_declared := ckp.declared_predicates(v_proj);
  IF jsonb_array_length(v_declared) > 0 THEN
    IF NOT (v_declared @> to_jsonb(v_via)) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'undeclared_predicate', 'via', v_via, 'declared', v_declared);
    END IF;
  ELSIF NOT (v_via LIKE 'https://conceptkernel.org/%' OR v_via LIKE 'urn:ckp:%') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'undeclared_predicate', 'via', v_via);
  END IF;
  -- bounded transitive traversal over the materialized link quads — `+` engine-capped.
  SELECT jsonb_agg(DISTINCT j->>'r') INTO v_reached
  FROM pgrdf.sparql(format('SELECT ?r WHERE { GRAPH ?g { <%s> <%s>+ ?r } }', v_from_iri, v_via)) j;
  RETURN jsonb_build_object('ok', true, 'from', v_from, 'resolved', v_from_iri, 'via', v_via,
                            'max_depth', v_max, 'reached', COALESCE(v_reached, '[]'::jsonb));
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp._affordance_schema(p_shape_iri text, p_comp integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  v_giri text;
  v_props jsonb;
BEGIN
  IF p_shape_iri IS NULL OR p_comp IS NULL THEN RETURN NULL; END IF;
  SELECT iri INTO v_giri FROM pgrdf._pgrdf_graphs WHERE graph_id = p_comp;
  IF v_giri IS NULL THEN RETURN NULL; END IF;

  SELECT jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
           'path',     j->>'path',
           'name',     regexp_replace(j->>'path', '^.*[#/]', ''),
           'datatype', j->>'dt',
           'required', CASE WHEN COALESCE((j->>'mn')::int, 0) >= 1 THEN true ELSE NULL END,
           'maxCount', (j->>'mx')::int,
           'nodeKind', regexp_replace(COALESCE(j->>'nk',''), '^.*[#/]', ''),
           'pattern',  j->>'pat'
         )) ORDER BY j->>'path')
    INTO v_props
  FROM pgrdf.sparql(format($q$
    PREFIX sh: <http://www.w3.org/ns/shacl#>
    SELECT ?path ?dt ?mn ?mx ?nk ?pat WHERE { GRAPH <%s> {
      <%s> sh:property ?p . ?p sh:path ?path .
      OPTIONAL { ?p sh:datatype ?dt } OPTIONAL { ?p sh:minCount ?mn }
      OPTIONAL { ?p sh:maxCount ?mx } OPTIONAL { ?p sh:nodeKind ?nk }
      OPTIONAL { ?p sh:pattern ?pat } } }$q$, v_giri, p_shape_iri)) j;

  -- Unresolvable => NULL, never an empty contract. A shape that resolves to
  -- nothing and a shape that is not there must not read the same.
  IF v_props IS NULL THEN RETURN NULL; END IF;
  RETURN jsonb_build_object('shape', p_shape_iri, 'properties', v_props);
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp.affordances_of(p_project text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  N       text := 'https://conceptkernel.org/ontology/v3.11/core#';
  v_kern  text := 'urn:ckp:'||p_project||'/kernel/ck';
  v_epoch int  := COALESCE((SELECT epoch FROM ckp.kernel_epoch WHERE kernel = p_project), 0);
  v_comp  int;
  v_list  jsonb;
  v_unsealed jsonb;
BEGIN
  v_comp := ckp._composed_shapes(p_project);

  SELECT jsonb_agg(a ORDER BY a->>'name') INTO v_list FROM (
    SELECT jsonb_strip_nulls(jsonb_build_object(
      'name',    regexp_replace(i.body->>(N||'inTopic'), '^input\.kernel\.[^.]+\.action\.', ''),
      'iri',     i.body->>'@id',
      'in',      i.body->>(N||'inTopic'),
      'out',     i.body->>(N||'outTopic'),
      'plane',   i.body->>(N||'plane'),
      'delegate', (i.body->>(N||'delegate'))::boolean,
      'inShape', i.body->>(N||'inShape'),
      -- inShape resolved into a real input contract, or null + a marker. §4.5:
      -- report what was found; never invent a contract for a dangling IRI.
      'schema',  ckp._affordance_schema(i.body->>(N||'inShape'), v_comp),
      'schema_resolved',
                 CASE WHEN i.body ? (N||'inShape')
                      THEN ckp._affordance_schema(i.body->>(N||'inShape'), v_comp) IS NOT NULL
                      ELSE NULL END,
      -- provenance for the affordance ITSELF (root: derivedBy minCount 1)
      'derivedBy', i.body->>(N||'derivedBy'),
      'sealedAtEpoch', (i.body->>(N||'sealedAtEpoch'))::int
    )) AS a
    FROM ckp.instances i
    WHERE i.body->>'type' = N||'Affordance'
      -- kernel filter: producedBy is the substrate-stamped kernel, unforgeable
      AND i.body->>(N||'producedBy') = v_kern
      -- retirement honoured: retired AT or BEFORE the current epoch is gone
      AND (NOT (i.body ? (N||'retiredAtEpoch'))
           OR (i.body->>(N||'retiredAtEpoch'))::int > v_epoch)
  ) s;

  -- The #56 split, made VISIBLE: verbs dispatch resolves that no sealed
  -- Affordance declares. Reported, never merged — a union would hide exactly
  -- the hand-registered action the root says cannot hide.
  --
  -- 0.4.51 — THE ADVERTISED SURFACE WAS NOT THE ROUTABLE ONE. This filtered
  -- `r.kernel = p_project`, while ckp.registry_lookup resolves
  -- `r.kernel = p_kernel OR r.kernel = 'pgck'` — the substrate floor seeded at
  -- install, which belongs to no kernel because install runs before any kernel
  -- exists. So a kernel that had registered two verbs of its own read
  -- {derived: [], unsealed: [its two]} and then SEALED SUCCESSFULLY through
  -- instance.create, a verb neither list named. pgCK.MCP filed that as F11 and
  -- inferred `derived` counts materialized affordances while instance-plane
  -- verbs are granted by role; the inference is refuted — both lists answer the
  -- same question, and they answered it against different predicates.
  --
  -- The fix is not a matching WHERE clause, which would drift again the next
  -- time the router changes. The candidate set is now filtered THROUGH
  -- registry_lookup itself, so "what this kernel may lawfully call" has exactly
  -- one definition and enumerable ⟺ dispatchable holds by construction. That is
  -- R7 / G7 closed by single-sourcing rather than by syncing two stores.
  SELECT jsonb_agg(q.verb ORDER BY q.verb) INTO v_unsealed
  FROM (
    SELECT DISTINCT r.verb
      FROM ckp.affordance_registry r
     WHERE ckp.registry_lookup(p_project, r.verb) IS NOT NULL
  ) q
  WHERE NOT EXISTS (
      SELECT 1 FROM ckp.instances i
      WHERE i.body->>'type' = N||'Affordance'
        AND i.body->>(N||'producedBy') = v_kern
        AND regexp_replace(i.body->>(N||'inTopic'), '^input\.kernel\.[^.]+\.action\.', '') = q.verb);

  RETURN jsonb_build_object(
    'ok', true,
    'kernel', p_project,
    'epoch', v_epoch,
    'affordances', COALESCE(v_list, '[]'::jsonb),
    'unsealed', COALESCE(v_unsealed, '[]'::jsonb));
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp.register_derived_affordance(p_prop jsonb, p_project text, p_epoch integer)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  v_detail  jsonb := COALESCE(p_prop->'proposalDetail', '{}'::jsonb);
  v_verb    text  := v_detail->>'verb';
  v_formula text  := v_detail->>'formula';
  v_scope   jsonb := v_detail->'scope';
  v_name_re text  := '^[a-z][a-z0-9_.]*$';
BEGIN
  IF v_verb IS NULL OR v_verb !~ v_name_re THEN
    RAISE EXCEPTION 'add_derived_affordance: verb must be a safe dotted name, got %', v_verb; END IF;
  IF v_formula IS NULL OR length(btrim(v_formula)) < 1 THEN
    RAISE EXCEPTION 'add_derived_affordance: formula required'; END IF;
  IF v_scope IS NULL OR v_scope->>'type' IS NULL OR v_scope->>'about_prop' IS NULL THEN
    RAISE EXCEPTION 'add_derived_affordance: scope {type, about_prop} required'; END IF;

  -- COMPILE: the sealed {formula, scope} becomes the plan for (kernel, verb, epoch).
  INSERT INTO ckp.plans(kernel, verb, epoch, plan)
  VALUES (p_project, v_verb, p_epoch,
          jsonb_build_object('kind', 'derived', 'formula', v_formula, 'scope', v_scope))
  ON CONFLICT (kernel, verb, epoch) DO UPDATE SET plan = EXCLUDED.plan, compiled_at = now();

  -- REGISTER: dispatch resolves the verb via plane='derived'.
  -- out_topic DECLARES where the caller will receive the result. It was left
  -- NULL on every row (0 of 30 measured), so a subscriber had no way to know
  -- what to listen to. This is not a new channel: src/nats_client.rs already
  -- publishes replies to result.kernel.<kernel>.<verb>. Registration now
  -- states the truth the transport already implements.
  INSERT INTO ckp.affordance_registry(kernel, verb, in_topic, out_topic, plane, epoch)
  VALUES (p_project, v_verb, 'input.kernel.'||p_project||'.action.'||v_verb,
          'result.kernel.'||p_project||'.'||v_verb, 'derived', p_epoch)
  ON CONFLICT (kernel, verb) DO UPDATE SET plane = 'derived', epoch = EXCLUDED.epoch,
    out_topic = EXCLUDED.out_topic, refreshed_at = now();

  RETURN v_verb;
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp.register_query_affordance(p_prop jsonb, p_project text, p_epoch integer)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  v_detail  jsonb := COALESCE(p_prop->'proposalDetail', '{}'::jsonb);
  v_verb    text  := v_detail->>'verb';
  v_query   text  := v_detail->>'query';
  v_params  jsonb := COALESCE(v_detail->'params', '[]'::jsonb);
  v_name_re text  := '^[a-z][a-z0-9_.]*$';   -- verb + param NAME gate (lowercase dotted ids)
  v_p       text;
BEGIN
  IF v_verb IS NULL OR v_verb !~ v_name_re THEN
    RAISE EXCEPTION 'add_affordance: verb must be a safe dotted name, got %', v_verb; END IF;
  IF v_query IS NULL OR length(btrim(v_query)) < 1 THEN
    RAISE EXCEPTION 'add_affordance: query text required'; END IF;
  IF jsonb_typeof(v_params) <> 'array' THEN
    RAISE EXCEPTION 'add_affordance: params must be a JSON array of names'; END IF;
  FOR v_p IN SELECT jsonb_array_elements_text(v_params) LOOP
    IF v_p !~ v_name_re THEN RAISE EXCEPTION 'add_affordance: unsafe param name %', v_p; END IF;
  END LOOP;

  -- COMPILE: the sealed query becomes the plan for (kernel, verb, epoch). §5.3 made real.
  INSERT INTO ckp.plans(kernel, verb, epoch, plan)
  VALUES (p_project, v_verb, p_epoch,
          jsonb_build_object('kind', 'sparql', 'statement', v_query, 'params', v_params))
  ON CONFLICT (kernel, verb, epoch) DO UPDATE SET plan = EXCLUDED.plan, compiled_at = now();

  -- REGISTER: dispatch resolves the verb via plane='query'.
  -- out_topic DECLARES where the caller will receive the result. It was left
  -- NULL on every row (0 of 30 measured), so a subscriber had no way to know
  -- what to listen to. This is not a new channel: src/nats_client.rs already
  -- publishes replies to result.kernel.<kernel>.<verb>. Registration now
  -- states the truth the transport already implements.
  INSERT INTO ckp.affordance_registry(kernel, verb, in_topic, out_topic, plane, epoch)
  VALUES (p_project, v_verb, 'input.kernel.'||p_project||'.action.'||v_verb,
          'result.kernel.'||p_project||'.'||v_verb, 'query', p_epoch)
  ON CONFLICT (kernel, verb) DO UPDATE SET plane = 'query', epoch = EXCLUDED.epoch,
    out_topic = EXCLUDED.out_topic, refreshed_at = now();

  RETURN v_verb;
END;
$function$
;

-- 0.4.65 — SEALED PROOF OBLIGATIONS (§5b, ruling-1786820448218277000).
--
-- The design fact this builds on: ckp.proof carries NO uniqueness — N proofs
-- per fact was placed so the seal's exit could grow by agreement. An obligation
-- is a governed proof-producer: registered through propose→vote→apply, run by
-- ckp.seal after the shape gate for every candidate of its target type, its
-- satisfaction appended as a ckp.proof row whose method names it. A failing
-- obligation REFUSES the seal — that is its point. A buggy one is bounded:
-- per-kernel scope (the registry row names the project), a FIXED registry of
-- pure-read checks that call the substrate's own internals (an obligation may
-- never carry code — it may only NAME a check the substrate implements, the
-- exact discipline P0-E applies to ops), and removal by the same governed op
-- that added it. External effects stay out until the validity≠safety gate is
-- specified: anything touching outside state belongs to the TOOL tier.

CREATE OR REPLACE FUNCTION ckp.register_proof_obligation(p_prop jsonb, p_project text, p_epoch integer)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  v_detail  jsonb := COALESCE(p_prop->'proposalDetail', '{}'::jsonb);
  v_ob      text  := v_detail->>'obligation';
  v_type    text  := v_detail->>'targetType';
  v_chk     text  := v_detail->>'check';
  v_active  boolean;
  v_name_re text  := '^[a-z][a-z0-9-]*$';
  v_iri_re  text  := '^[A-Za-z][A-Za-z0-9+.:#/_-]*$';
  -- THE FIXED CHECK REGISTRY. Widening it means implementing a pure-read check
  -- in ckp._run_proof_obligations' CASE, never editing this list alone — the
  -- P0-E sibling: a check that cannot run is refused at registration.
  -- 0.4.72 adds the vision §2 trio: adopts-resolves (referential validity of
  -- Adoptions — the ontosys class), structural-pin (the graph being adopted is
  -- structurally the graph first pinned under that IRI), and no-warnings (the
  -- ratchet: guidance becomes law for kernels that adopt it, §2.0a).
  v_checks  text[] := ARRAY['digest-match','adopts-resolves','structural-pin','no-warnings'];
BEGIN
  IF v_ob IS NULL OR v_ob !~ v_name_re THEN
    RAISE EXCEPTION 'add_proof_obligation: obligation must be a lowercase dashed name, got %', v_ob; END IF;
  BEGIN
    v_active := COALESCE((v_detail->>'active')::boolean, true);
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'add_proof_obligation: active must be a boolean, got %', v_detail->>'active'; END;
  IF NOT v_active THEN
    -- deactivation: the same governed road out that led in. The row stays —
    -- WHICH obligation guarded WHICH epochs remains answerable.
    UPDATE ckp.proof_obligations SET active = false
      WHERE project = p_project AND obligation = v_ob;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'add_proof_obligation: no obligation named % on this kernel to deactivate', v_ob; END IF;
    RETURN v_ob;
  END IF;
  IF v_type IS NULL OR v_type !~ v_iri_re THEN
    RAISE EXCEPTION 'add_proof_obligation: targetType must be a type IRI, got %', v_type; END IF;
  IF v_chk IS NULL OR NOT (v_chk = ANY(v_checks)) THEN
    RAISE EXCEPTION 'add_proof_obligation: check % is not in the fixed registry % — an obligation names a check the substrate implements; widening the registry means implementing one, not naming one', v_chk, v_checks; END IF;
  INSERT INTO ckp.proof_obligations(project, obligation, target_type, check_name, added_epoch, active)
  VALUES (p_project, v_ob, v_type, v_chk, p_epoch, true)
  ON CONFLICT (project, obligation) DO UPDATE
    SET target_type = EXCLUDED.target_type, check_name = EXCLUDED.check_name,
        added_epoch = EXCLUDED.added_epoch, active = true;
  RETURN v_ob;
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp._oblig_digest_match(p_instance_id text, p_body jsonb, p_project text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
-- THE DEBUT CHECK (§5b): "the surfaceDigest this candidate cites was sealed by
-- an Epoch." Pure read. Returns NULL on satisfaction, the refusal text
-- otherwise. Closes the fabricated-digest hole ck-lib-js measured
-- (finding-1786716799509380000): a wave:Pass citing an invented sixty-four-hex
-- digest sealed verified:true, because the shape gate judges FORM and nothing
-- judged REFERENCE. This check judges reference — against the sealed Epoch
-- instances themselves, never a parallel record.
--
-- Jurisdiction discipline: an ABSENT surfaceDigest is minCount's business (the
-- shape gate refuses it); this check rules only on a PRESENT citation. When the
-- candidate also cites an epoch number, the pair must sit on one sealed Epoch —
-- citing epoch 13 with epoch 12's digest is exactly the dishonesty this exists
-- to refuse.
DECLARE
  C        text := 'https://conceptkernel.org/ontology/v3.11/core#';
  v_digest text := p_body->>(C||'surfaceDigest');
  v_epoch  text := p_body->>(C||'epoch');
BEGIN
  IF v_digest IS NULL THEN
    RETURN NULL;
  END IF;
  IF EXISTS (SELECT 1 FROM ckp.instances i
             WHERE i.body->>'type' = C||'Epoch'
               AND i.body->>(C||'surfaceDigest') = v_digest
               AND (v_epoch IS NULL OR i.body->>(C||'epoch') = v_epoch)) THEN
    RETURN NULL;
  END IF;
  RETURN format('digest-match: the candidate cites surfaceDigest %s…%s but no sealed ckp:Epoch carries that surface — a citation must name a digest an Epoch sealed, exactly as sealed (ck_epochs lists them)',
                left(v_digest, 12),
                CASE WHEN v_epoch IS NOT NULL THEN ' at epoch '||v_epoch ELSE '' END);
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp._oblig_adopts_resolves(p_instance_id text, p_body jsonb, p_project text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
-- 0.4.72 (vision §2.0b) — REFERENTIAL VALIDITY OF ADOPTIONS. Module-IRI-is-
-- graph-IRI: the adopts value IS the graph the composer copies, and a shape
-- cannot check that the referenced graph exists and is non-empty (body
-- locality) — so this is the obligations' half. Catches the ontosys class
-- (adopts naming a namespace with no graph behind it) and every judged,
-- load-bearing-for-nothing Adoption before it seals. Pure read, NULL = pass.
DECLARE
  C text := 'https://conceptkernel.org/ontology/v3.11/core#';
  v_adopts text := p_body->>(C||'adopts');
BEGIN
  IF v_adopts IS NULL THEN RETURN NULL; END IF;  -- minCount is the gate's business
  IF NOT EXISTS (
    SELECT 1 FROM pgrdf._pgrdf_quads q
    JOIN pgrdf._pgrdf_graphs g ON g.graph_id = q.graph_id
    WHERE g.iri = v_adopts AND NOT q.is_inferred) THEN
    RETURN format('adopts-resolves: %s names no non-empty graph in this store — module-IRI-is-graph-IRI, and adopting a reference with nothing behind it seals a judged record that composes NOTHING (the load-bearing-for-nothing class, paid for five times). Load the module graph first, and check the spelling: the module GRAPH IRI, never the namespace', v_adopts);
  END IF;
  RETURN NULL;
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp._oblig_structural_pin(p_instance_id text, p_body jsonb, p_project text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
-- 0.4.72 (vision §2.0b, the synapse-regrowth gate of the sporaxis design) —
-- the graph being adopted must be STRUCTURALLY the graph first pinned under
-- that IRI. First sight passes (nothing to compare, TOFU as declared); a
-- structural mismatch against an existing pin refuses: someone swapped the
-- module under a pinned name, and reload-relabelling is exactly what this
-- plane cannot be fooled by. DIFFERENT is conclusive (R-7). Pure read.
DECLARE
  C text := 'https://conceptkernel.org/ontology/v3.11/core#';
  v_adopts text := p_body->>(C||'adopts');
  v_pin text; v_now text;
BEGIN
  IF v_adopts IS NULL THEN RETURN NULL; END IF;
  SELECT structural_digest INTO v_pin FROM ckp.adoption_pins WHERE graph_iri = v_adopts;
  IF v_pin IS NULL THEN RETURN NULL; END IF;   -- first sight, or pre-structural pin: nothing to hold against
  v_now := ckp._structural_digest(pgrdf.add_graph(v_adopts));
  IF v_now <> v_pin THEN
    RETURN format('structural-pin: the graph at %s is structurally %s… but was first pinned as %s… — unequal structural digests PROVE the graphs differ (this plane survives reload, so this is never a relabelling artifact). A legitimate update arrives as a NEW module IRI + Supersession, never a swap under a pinned name', v_adopts, left(v_now,12), left(v_pin,12));
  END IF;
  RETURN NULL;
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp._oblig_no_warnings(p_instance_id text, p_body jsonb, p_project text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
-- 0.4.72 (vision §2.0a, the operator's ratchet) — "adopt the rule NO WARNINGS
-- ON SEAL: now they are law — comply, or others cannot rely on what you do."
-- The gate parked this seal's Warning/Info results in the txn-local GUC
-- moments ago; a kernel that adopted this obligation turns that guidance band
-- into refusals, and every conforming seal carries obligation:no-warnings as
-- a proof row — the warranty rides the fact, per-instance verifiable, so
-- reliance is a row rather than a reputation. Pure read of this txn's state.
DECLARE
  v_warn jsonb := NULLIF(current_setting('ckp.last_warnings', true), '')::jsonb;
BEGIN
  IF v_warn IS NULL OR jsonb_array_length(v_warn) = 0 THEN RETURN NULL; END IF;
  RETURN format('no-warnings: this kernel adopted the strict regime and the candidate carries %s warning(s) — first: %s on %s. Guidance is law here; shape the body until the warnings clear, or the fleet cannot rely on this kernel''s output at the grade it declared',
    jsonb_array_length(v_warn), v_warn->0->>'resultMessage', v_warn->0->>'resultPath');
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp._run_proof_obligations(p_instance_id text, p_type text, p_body jsonb, p_project text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
-- Runs every ACTIVE obligation this kernel registered for the candidate's
-- declared type. Returns {satisfied: [names]} or {refused: <obligation>,
-- reason: <text>} — ckp.seal raises on refusal and appends one proof row per
-- satisfied name. Exact-type match: an obligation on wave:Pass does not reach
-- ckp:Epoch seals (the apply cascade), and ancestor-aware matching waits for
-- an agreement that wants it. An obligation naming a check this substrate does
-- not implement fails CLOSED — registration refuses it (register_proof_
-- obligation), and if one arrives anyway (downgrade skew), the seal refuses
-- rather than silently skipping a guard two parties agreed to.
DECLARE
  r      record;
  v_fail text;
  v_sat  jsonb := '[]'::jsonb;
BEGIN
  FOR r IN SELECT obligation, check_name FROM ckp.proof_obligations
           WHERE active AND project = p_project AND target_type = p_type
           ORDER BY obligation
  LOOP
    CASE r.check_name
      WHEN 'digest-match'    THEN v_fail := ckp._oblig_digest_match(p_instance_id, p_body, p_project);
      WHEN 'adopts-resolves' THEN v_fail := ckp._oblig_adopts_resolves(p_instance_id, p_body, p_project);
      WHEN 'structural-pin'  THEN v_fail := ckp._oblig_structural_pin(p_instance_id, p_body, p_project);
      WHEN 'no-warnings'     THEN v_fail := ckp._oblig_no_warnings(p_instance_id, p_body, p_project);
      ELSE v_fail := format('check %s is not implemented by this substrate — failing closed rather than skipping an agreed guard', r.check_name);
    END CASE;
    IF v_fail IS NOT NULL THEN
      RETURN jsonb_build_object('refused', r.obligation, 'reason', v_fail);
    END IF;
    v_sat := v_sat || to_jsonb(r.obligation);
  END LOOP;
  RETURN jsonb_build_object('satisfied', v_sat);
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp.registry_lookup(p_kernel text, p_verb text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
  -- EMPTY MEANS NONE. A kernel is authorized for the verbs its OWN registry
  -- rows name. It is never authorized for another kernel's, and never for
  -- EVERYTHING on the grounds that it has none -- degrading an empty surface
  -- to the full surface is fail-open authorization (d-28-sah-1). All 26 seeded
  -- rows name kernel pgCK, so every other workspace resolves to zero rows,
  -- which is a true answer meaning none.
  --
  -- ONE bootstrap exception, the narrowest that still permits creation: a
  -- kernel that does not exist yet cannot own a registry row, so without this
  -- no kernel could ever be created through the door. kernel.germinate is the
  -- only verb reachable with no surface -- it refuses anonymous callers and
  -- stamps ownedBy from the verified connection, so reaching it proves an
  -- identity rather than bypassing one.
  -- YOUR OWN FIRST, THEN THE SUBSTRATE FLOOR. A row this kernel registered wins;
  -- otherwise the row seeded at install, which belongs to no kernel because
  -- install runs before any kernel exists. Resolving ONLY the floor made every
  -- kernel share one name's surface; resolving ONLY the caller made the seeded
  -- verbs unreachable for everyone. Empty still means NONE -- it is now a real
  -- answer about this kernel rather than a lookup under someone else's name.
  SELECT to_jsonb(r) FROM ckp.affordance_registry r
  WHERE r.verb = p_verb
    AND (r.kernel = p_kernel OR r.kernel = 'pgck' OR p_verb = 'kernel.germinate')
  ORDER BY (r.kernel = p_kernel) DESC
  LIMIT 1;
$function$
;

CREATE OR REPLACE FUNCTION ckp.registry_refresh()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  r          record;
  v_kernel   text;
  v_verb     text;
  v_epoch    integer;
  v_delegate boolean;
  v_count    integer := 0;
BEGIN
  FOR r IN
    SELECT j->>'a'  AS iri,
           j->>'it' AS in_topic,
           j->>'ot' AS out_topic,
           j->>'is' AS in_shape,
           j->>'pl' AS plane,
           j->>'ep' AS epoch,
           j->>'dg' AS delegate
    FROM pgrdf.sparql($q$
      PREFIX ckp: <https://conceptkernel.org/ontology/v3.11/core#>
      SELECT ?a ?it ?ot ?is ?pl ?ep ?dg WHERE {
        GRAPH ?g {
          ?a a ckp:Affordance ; ckp:inTopic ?it .
          OPTIONAL { ?a ckp:outTopic ?ot }
          OPTIONAL { ?a ckp:inShape  ?is }
          OPTIONAL { ?a ckp:plane    ?pl }
          OPTIONAL { ?a ckp:epoch    ?ep }
          OPTIONAL { ?a ckp:delegate ?dg }
        } }
    $q$) AS j
  LOOP
    -- derive kernel + verb from inTopic: input.kernel.<Kernel>.action.<verb>
    v_kernel := substring(r.in_topic FROM '^input\.kernel\.([^.]+)\.action\.');
    v_verb   := regexp_replace(r.in_topic, '^input\.kernel\.[^.]+\.action\.', '');
    CONTINUE WHEN v_kernel IS NULL OR v_verb IS NULL OR v_verb = r.in_topic OR v_verb = '';

    -- typed-literal-safe parses (strip any ^^<datatype> suffix the engine may carry)
    v_epoch    := COALESCE(NULLIF(split_part(COALESCE(r.epoch,    ''), '^', 1), '')::integer, 1);
    v_delegate := COALESCE(NULLIF(split_part(COALESCE(r.delegate, ''), '^', 1), '')::boolean, false);

    INSERT INTO ckp.affordance_registry
      (kernel, verb, affordance_iri, in_topic, out_topic, in_shape, plane, epoch, delegate, refreshed_at)
    VALUES
      (v_kernel, v_verb, r.iri, r.in_topic, r.out_topic, r.in_shape,
       COALESCE(NULLIF(split_part(COALESCE(r.plane,''),'^',1),''), 'instance'),
       v_epoch, v_delegate, now())
    ON CONFLICT (kernel, verb) DO UPDATE SET
      affordance_iri = EXCLUDED.affordance_iri,
      in_topic   = EXCLUDED.in_topic,
      out_topic  = EXCLUDED.out_topic,
      in_shape   = EXCLUDED.in_shape,
      plane      = EXCLUDED.plane,
      epoch      = EXCLUDED.epoch,
      delegate   = EXCLUDED.delegate,
      refreshed_at = EXCLUDED.refreshed_at;
    v_count := v_count + 1;
  END LOOP;
  RETURN v_count;
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp.retire(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  C        text := 'https://conceptkernel.org/ontology/v3.11/core#';
  v_id     text := p_payload->>'id';
  v_reason text := p_payload->>'reason';
  v_proj   text := ckp._project();
  v_epoch  int;
  v_body   jsonb;
  v_type   text;
BEGIN
  IF v_reason IS NULL OR length(btrim(v_reason)) < 1 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'reason_required', 'id', v_id);
  END IF;
  SELECT body INTO v_body FROM ckp.instances WHERE id = v_id;
  IF v_body IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'unknown_instance', 'id', v_id);
  END IF;
  -- Only a DECLARED retirement blocks a second one. A row carrying the bare
  -- pre-0.4.55 `retired` key and no ckp:retiredAtEpoch was never retired in any
  -- way another kernel can read, so letting the sanctioned verb finish the act is
  -- COMPLETING it, not repeating it and not backfilling it — nothing is invented,
  -- the declared property is simply moved to where the private key already said
  -- it was. This is what lets F15's two observed rows close instead of standing
  -- as scars that every reader has to be told about.
  IF v_body ? (C||'retiredAtEpoch') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'already_retired', 'id', v_id,
      'reason', COALESCE(v_body->>(C||'reason'), v_body->>'retired_reason'));
  END IF;
  -- 0.4.55 — RETIREMENT NOW MOVES THE DECLARED PROPERTY, AND STOPS MINTING KEYS.
  --
  -- This wrote bare `retired` and `retired_reason` — not IRIs at all, so they
  -- entered the body as undeclared predicates, which is the E3/R2 fail-open this
  -- substrate exists to end, committed by the retraction path itself. Worse, the
  -- DECLARED state never moved: a retired Proposal kept ckp:proposalState
  -- "pending" forever, so every other kernel reading the gated property saw
  -- outstanding work that no longer existed.
  --
  -- pgCK.MCP found it from outside and filed it as F15, and its reasoning is the
  -- correct one: it counted those proposals as pending "because the declared
  -- property is the only one another kernel can rely on". A retraction that only
  -- a private key records is not a retraction — it is a note.
  --
  -- Declared vocabulary only, from here:
  --   ckp:retiredAtEpoch  integer, already honoured by ckp.affordances_of
  --   ckp:reason          string, the same property FailedMaterialization carries
  --   ckp:proposalState   for a Proposal, moved to 'rejected' — the enum is
  --                       (pending applied rejected) and it is sh:in-GATED, so if
  --                       this value were wrong the seal would refuse and say so.
  --
  -- The retraction stays a sealed fact: body' carries it, the seal appends ledger
  -- + proof, every prior body stays in the chain. Nothing is ever unsealed.
  v_epoch := COALESCE((SELECT epoch FROM ckp.kernel_epoch WHERE kernel = v_proj), 0);
  v_type  := v_body->>'type';
  v_body  := v_body || jsonb_build_object(
               C||'retiredAtEpoch', to_jsonb(v_epoch),
               C||'reason', btrim(v_reason));
  IF v_type = C||'Proposal' THEN
    v_body := v_body || jsonb_build_object(C||'proposalState', 'rejected');
  END IF;
  PERFORM ckp.seal(v_id, v_body);
  RETURN jsonb_build_object('ok', true, 'id', v_id,
    'retiredAtEpoch', v_epoch,
    'declaredStateMoved', (v_type = C||'Proposal'),
    'reason', btrim(v_reason), 'verified', ckp.verify(v_id));
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp.run_derived_affordance(p_verb text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  -- The plan is keyed by (kernel, verb, epoch). Reading it under a hard-coded
  -- kernel while register_*_affordance writes under p_project splits the pair:
  -- the write lands under the calling project and the read never finds it.
  -- Both sides now resolve the SAME way dispatch does.
  v_proj   text := ckp._project();
  v_plan    jsonb;
  v_epoch   bigint;
  v_formula text;
  v_scope   jsonb;
  v_concept text := p_payload->>'concept';
  v_val_re  text := '^[A-Za-z0-9 ._:#/-]*$';   -- concept VALUE gate (no quote/brace/backslash)
  v_res     jsonb;
  wm_now    bigint;
  wm_ph     bigint;
BEGIN
  SELECT plan, epoch INTO v_plan, v_epoch FROM ckp.plans
    WHERE kernel IN (v_proj, 'pgck') AND verb = p_verb
   ORDER BY (kernel = v_proj) DESC, epoch DESC LIMIT 1;
  IF v_plan IS NULL OR v_plan->>'kind' <> 'derived' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'unknown_derived_affordance', 'verb', p_verb); END IF;
  IF v_concept IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'missing_param', 'param', 'concept'); END IF;
  IF v_concept !~ v_val_re THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_param', 'param', 'concept'); END IF;

  v_formula := v_plan->>'formula';
  v_scope   := (v_plan->'scope') || jsonb_build_object('about', v_concept);   -- bind the concept

  v_res  := ckp.derived_sum(v_concept, v_scope, v_formula, v_epoch);
  wm_now := ckp._source_watermark(v_scope);
  SELECT watermark INTO wm_ph FROM ckp.phenotype_ptr WHERE concept = v_concept;

  RETURN jsonb_build_object(
    'ok', true, 'verb', p_verb,
    'value', (v_res->>'value')::numeric,
    'scored', true,
    'freshness', jsonb_build_object('watermark', wm_ph, 'current', wm_now,
                                    'fresh', COALESCE(wm_ph >= wm_now, false)));
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('ok', false, 'error', SQLERRM);
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp.run_query_affordance(p_verb text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  -- The plan is keyed by (kernel, verb, epoch). Reading it under a hard-coded
  -- kernel while register_*_affordance writes under p_project splits the pair:
  -- the write lands under the calling project and the read never finds it.
  -- Both sides now resolve the SAME way dispatch does.
  v_proj   text := ckp._project();
  v_plan   jsonb;
  v_stmt   text;
  v_params jsonb;
  v_val_re text := '^[A-Za-z0-9 ._:#/-]*$';   -- param VALUE gate: no quote/brace/backslash/?-var
  v_name   text;
  v_val    text;
  v_rows   jsonb;
BEGIN
  -- latest-epoch plan for this governed verb (a stale epoch is simply superseded).
  -- PLAN RESOLUTION = your own first, then the substrate floor. A plan the
  -- calling project registered wins; otherwise fall back to the one seeded at
  -- install, which belongs to no kernel because install runs before any kernel
  -- exists. Reading ONLY the floor made every project share one kernel's plans;
  -- reading ONLY v_proj made the seeded substrate verbs unreachable for
  -- everyone (smoke-s4 s32). Both halves are needed until the seed itself stops
  -- naming a kernel.
  SELECT plan INTO v_plan FROM ckp.plans
   WHERE kernel IN (v_proj, 'pgck') AND verb = p_verb
   ORDER BY (kernel = v_proj) DESC, epoch DESC LIMIT 1;
  IF v_plan IS NULL OR v_plan->>'kind' <> 'sparql' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'unknown_query_affordance', 'verb', p_verb); END IF;

  v_stmt   := v_plan->>'statement';
  v_params := COALESCE(v_plan->'params', '[]'::jsonb);

  -- bind each declared param: the caller supplies a VALUE only; validate it, then substitute
  -- into the author's `$name$` placeholder (placed in string-literal positions by the query).
  FOR v_name IN SELECT jsonb_array_elements_text(v_params) LOOP
    v_val := p_payload->>v_name;
    IF v_val IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'error', 'missing_param', 'param', v_name); END IF;
    IF v_val !~ v_val_re THEN
      RETURN jsonb_build_object('ok', false, 'error', 'invalid_param', 'param', v_name); END IF;
    v_stmt := replace(v_stmt, '$' || v_name || '$', v_val);
  END LOOP;

  -- run the GOVERNED query — the text is a sealed kernel fact; only validated values were bound.
  SELECT jsonb_agg(j) INTO v_rows FROM pgrdf.sparql(v_stmt) j;
  RETURN jsonb_build_object('ok', true, 'verb', p_verb,
                            'count', COALESCE(jsonb_array_length(v_rows), 0),
                            'rows', COALESCE(v_rows, '[]'::jsonb));
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('ok', false, 'error', SQLERRM);
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp.seal(p_instance_id text, p_body jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  v_core   INT := (SELECT v::int FROM ckp.config WHERE k='core_graph_id');
  v_kgraph INT := (SELECT v::int FROM ckp.config WHERE k='kernel_graph_id');
  v_identity_key TEXT := COALESCE(
    NULLIF(current_setting('ckp.identity_key', true), ''),
    (SELECT v FROM ckp.config WHERE k='identity_key')
  );
  v_project TEXT := ckp._project();
  v_type   TEXT := p_body->>'type';
  v_missing TEXT;
  v_sha    TEXT;
  v_sig    TEXT;
  v_prev   BIGINT;
  v_now    TIMESTAMPTZ := now();
  v_led_ttl TEXT;
  v_prf_ttl TEXT;
  v_sub    TEXT;
  v_req    TEXT;
  v_display TEXT;
  v_email  TEXT;
  v_participant TEXT;
  N        TEXT := 'https://conceptkernel.org/ontology/v3.11/core#';
  v_stamps JSONB := '{}'::jsonb;
  v_oblig  JSONB := '{}'::jsonb;
  v_ob     TEXT;
  v_res    TEXT;
  v_gref   TEXT;
BEGIN
  IF v_type IS NULL THEN
    RAISE EXCEPTION 'ckp.seal: body has no "type"';
  END IF;
  IF v_identity_key IS NULL OR v_identity_key = '' THEN
    RAISE EXCEPTION 'ckp.seal: no identity key configured';
  END IF;

  -- 0. RESOLVE participant identity (CKF-3). Map an optional "participant"
  -- claims object {sub, preferred_username, email} to the canonical IRI
  -- urn:ckp:participant:<normalised-sub>; mint urn:ckp:participant:anon:<nonce>
  -- when absent or sub is empty. Display claims (preferred_username, email)
  -- are carried as non-authoritative attributes per NOTIFIES.pgCK §D.
  -- This MUST run before the body SHA (step 2) so the stored body, the ledger
  -- digest, and ckp.verify()'s recompute all hash the same canonical body.
  --
  -- IDENTITY HAS ONE SOURCE. `ckp.requester` is set transaction-locally by the
  -- relay from the callout-verified connection; the payload's participant.sub
  -- is whatever the client typed. Reading the payload here while germination
  -- read the GUC gave one seal two identities: a Project ownedBy a verified
  -- participant and createdBy anon:<nonce> -- "owned by someone, created by
  -- nobody" -- and it made createdBy client-assertable, which is the whole
  -- thing the four stamps exist to prevent. The verified connection WINS; a
  -- conflicting payload sub is ignored, not merged. The payload arm survives
  -- only for callers with no verified connection at all (direct SQL, tests).
  v_req     := NULLIF(trim(COALESCE(current_setting('ckp.requester', true), '')), '');
  v_sub     := p_body->'participant'->>'sub';
  v_display := NULLIF(trim(COALESCE(p_body->'participant'->>'preferred_username','')), '');
  v_email   := NULLIF(trim(COALESCE(p_body->'participant'->>'email','')), '');
  IF v_req IS NOT NULL THEN
    v_participant := 'urn:ckp:participant:' || ckp.urn_normalise(v_req);
  ELSIF p_body ? 'participant' AND v_sub IS NOT NULL AND length(trim(v_sub)) > 0 THEN
    v_participant := 'urn:ckp:participant:' || ckp.urn_normalise(v_sub);
  ELSE
    -- 0.4.64 — REFUSE, do not mint. This minted anon:<fresh-uuid> per call, so
    -- every unattributed write became a permanent fact belonging to nobody and
    -- N naked-path seals presented as N distinct participants (ck-dev's
    -- finding-1786732252462817000; quorum was closed at 0.4.62, and THIS closes
    -- unattributability itself). The door is unaffected: its anonymous tier is
    -- subscribe-only and never reaches seal; a verified connection always sets
    -- ckp.requester. Only the naked path (psql / pgRDF-side SPI) lands here,
    -- and the naked path must NAME an identity — a declared service identity
    -- is acceptable, an absent one is not. The 39 historical anon seals stand
    -- as fenced history; no new one can be created.
    RAISE EXCEPTION 'ckp.seal: unattributed write refused — no verified identity on this call. Name one explicitly: SELECT set_config(''ckp.requester'', ''<your declared identity, e.g. svc:smoke-suite>'', true) before sealing. The substrate no longer mints anon:<uuid> participants: a fact belonging to nobody is permanent, and fresh uuids let one caller impersonate many distinct parties.';
    v_display := NULL;
    v_email := NULL;
  END IF;
  -- Replace the raw claims object with the resolved canonical IRI; carry the
  -- display fields only when they were supplied alongside an identified sub.
  p_body := (p_body - 'participant')
    || jsonb_build_object(
      'https://conceptkernel.org/ontology/v3.11/core#participant', v_participant);
  IF v_display IS NOT NULL THEN
    p_body := jsonb_set(p_body, '{participant_display_name}', to_jsonb(v_display), true);
  END IF;
  IF v_email IS NOT NULL THEN
    p_body := jsonb_set(p_body, '{participant_email}', to_jsonb(v_email), true);
  END IF;

  -- 0b. #59: STRIP any caller-asserted substrate stamp. All four are maxCount 1
  -- in ckp:InstanceShape, so a body carrying its own createdBy was projected
  -- alongside the derived one and refused on MaxCountConstraintComponent — a
  -- denial any client could trigger, reading as a shape defect rather than as a
  -- rejected claim. §4.3 says these are server-derived and claim-ignoring;
  -- removing them here is what makes that structural instead of conventional.
  p_body := p_body - ARRAY[
    N||'producedBy', N||'createdBy', N||'sealedAtEpoch', N||'conformsToShape'
  ];

  -- 1. VALIDATE the payload against the COMPOSED shapes graph (P0-B, pgCK#25).
  --
  -- Was: a hand-rolled SPARQL scan for sh:minCount against the KERNEL graph only.
  -- That saw no core shape (the kernel graph holds only the kernel's own), and it
  -- read past every other SHACL component the engine enforces. Measured on the
  -- bench, same malformed body, two shapes graphs: kernel -> conforms TRUE,
  -- composed -> conforms FALSE. Twelve Core components are measured enforcing.
  --
  -- Now: project the body to RDF, stamp the declared type's ancestors so
  -- InstanceShape and friends target it (pgrdf.validate does NOT entail, and
  -- entailment is per-graph — either gap silently returns conforms=true), and
  -- validate against core UNION kernel.
  DECLARE
    v_comp    int;
    v_cand    text;
    v_report  jsonb;
    v_excl    text := NULL;
  BEGIN
    -- 0.4.73 — deadlock escape, derived never claimed: when the candidate IS a
    -- core#Supersession, the graph named by its target Adoption's adopts value
    -- is excluded from the fail-closed composition — the cure must not be
    -- gated by the poison it removes. Derived from the SEALED target, so a
    -- caller cannot exclude arbitrary graphs by asserting supersedes at random:
    -- a supersedes that names no sealed Adoption excludes nothing.
    IF v_type = 'https://conceptkernel.org/ontology/v3.11/core#Supersession' THEN
      SELECT a.body->>'https://conceptkernel.org/ontology/v3.11/core#adopts' INTO v_excl
        FROM ckp.instances a
       WHERE a.body->>'@id' = p_body->>'https://conceptkernel.org/ontology/v3.11/core#supersedes'
         AND a.body->>'type' = 'https://conceptkernel.org/ontology/v3.11/core#Adoption';
    END IF;
    v_comp := ckp._composed_shapes(v_project, v_excl);
    -- P0-D mechanism 2 (pgCK#27): fail closed on the UNDECLARED TYPE, BEFORE
    -- validation runs. This is the half that produced the live defect — an
    -- invented type URN is targeted by no shape, so SHACL never runs and the
    -- body seals verified:true. The lookup refuses it; a declared type (class
    -- or shape target) passes on to the measured-enforcing gate below.
    IF NOT ckp._type_admitted(v_type, v_project, v_comp) THEN
      RAISE EXCEPTION 'ckp.seal: type % is not admitted — no shape targets it and it is declared by no class in the composed surface (undeclared types cannot seal; SHACL would validate them vacuously)', COALESCE(v_type, '<null>');
    END IF;
    -- pgCK#41: the four substrate-derived properties (producedBy, createdBy,
    -- sealedAtEpoch, conformsToShape) are demanded by ckp:InstanceShape with
    -- minCount 1, but were derived AFTER this gate — so on the v3.11 root every
    -- Instance-classed seal failed by construction. Derive them INTO the
    -- candidate the gate validates: what is checked is what will be stamped.
    --
    -- #59: derive ONCE, here, and keep the jsonb. The Turtle below and the
    -- stored body in step 2 are two renderings of this single value, so the
    -- gate and the store cannot disagree about what was stamped.
    v_stamps := ckp._derived_stamps(p_instance_id, v_type, v_project, v_participant, v_comp);
    v_cand := ckp._body_to_ttl(p_body, p_instance_id, v_comp)
              || ckp._parent_closure_ttl(v_type, p_instance_id, v_comp)
              || ckp._stamps_to_ttl(p_instance_id, v_stamps);
    v_report := ckp.validate_report(v_cand, v_comp);
    -- 0.4.72 — THE GATE LEARNS SEVERITY (guidance-as-validation, vision §2.0).
    -- Results at sh:Violation — or with no severity, SHACL's default — REFUSE
    -- exactly as before: every pre-existing shape carries no explicit severity,
    -- so nothing weakens (the negative control). Results a shape deliberately
    -- authored at sh:Warning/sh:Info SEAL AND SURFACE: they ride a txn-local
    -- GUC to the reply's `warnings`, so guidance reaches the caller at zero
    -- marginal cost — the validation already ran. "Valid core looks like this;
    -- you get warnings" — and the no-warnings obligation (§2.0a) is the
    -- governed ratchet that turns them into refusals for kernels that adopt it.
    PERFORM set_config('ckp.last_warnings', '', true);
    DECLARE
      v_viol jsonb; v_warn jsonb;
    BEGIN
      SELECT COALESCE(jsonb_agg(r) FILTER (WHERE r->>'resultSeverity' IS DISTINCT FROM 'sh:Warning'
                                             AND r->>'resultSeverity' IS DISTINCT FROM 'sh:Info'), '[]'::jsonb),
             COALESCE(jsonb_agg(r) FILTER (WHERE r->>'resultSeverity' IN ('sh:Warning','sh:Info')), '[]'::jsonb)
        INTO v_viol, v_warn
        FROM jsonb_array_elements(COALESCE(v_report->'violations', '[]'::jsonb)) r;
      IF jsonb_array_length(v_viol) > 0 THEN
        RAISE EXCEPTION 'ckp.seal: payload fails the composed shape gate: %',
          COALESCE(ckp._report_summary(jsonb_build_object('conforms','false','violations',v_viol)), v_viol::text);
      END IF;
      IF jsonb_array_length(v_warn) > 0 THEN
        PERFORM set_config('ckp.last_warnings', v_warn::text, true);
      END IF;
    END;
  END;

  -- 1b. PROOF OBLIGATIONS (0.4.65, §5b) — the seal's exit, extensible by
  -- agreement. The shape gate above judges FORM; obligations judge whatever the
  -- registered check judges (the debut, digest-match, judges REFERENCE: a cited
  -- surfaceDigest must be one an Epoch sealed). Every ACTIVE obligation this
  -- kernel registered for this exact type runs; one refusal refuses the seal.
  -- Satisfactions become proof rows at step 4b — the agreement leaves a mark on
  -- every fact it guarded, so "which checks did this seal pass" is a read.
  v_oblig := ckp._run_proof_obligations(p_instance_id, v_type, p_body, v_project);
  IF v_oblig ? 'refused' THEN
    RAISE EXCEPTION 'ckp.seal: proof obligation % refused this candidate — %',
      v_oblig->>'refused', v_oblig->>'reason';
  END IF;

  -- 2. MATERIALIZE durable instance.
  --
  -- #59: the stamps join the body BEFORE the digest. Merged last so they win
  -- over anything of the same name (nothing can, after 0b) and so v_sha — and
  -- therefore the HMAC, the ledger, the proof and ckp.verify()'s recompute —
  -- covers the provenance. Before this the attestation said "this body was
  -- sealed"; it now says "by this participant, under this shape, at this epoch".
  p_body := p_body || v_stamps;
  v_sha := encode(digest(convert_to(p_body::text,'UTF8'),'sha256'),'hex');
  v_sig := encode(hmac(v_sha, v_identity_key, 'sha256'),'hex');
  SELECT max(seq) INTO v_prev FROM ckp.ledger;
  INSERT INTO ckp.instances(id, body) VALUES (p_instance_id, p_body)
  ON CONFLICT (id) DO UPDATE SET body = EXCLUDED.body, ts_updated = v_now;

  -- 3. VALIDATE the protocol's OWN ledger op, then write it.
  v_led_ttl := format($t$
    @prefix ckp: <https://conceptkernel.org/ontology/v3.11/core#> .
    @prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
    <urn:ckp:led:%s> a ckp:LedgerEntry ;
      ckp:about <%s> ; ckp:bodySha "%s" ; ckp:sig "%s" ;
      ckp:prev %s ;
      ckp:ts "%s"^^xsd:dateTime .$t$,
    p_instance_id, p_instance_id, v_sha, v_sig,
    -- v3.11 LedgerEntryShape demands ckp:prev (minCount 1, xsd:integer) — the
    -- chain position, which v3.8 left implicit in the relational prev_seq.
    -- Genesis encodes as 0: the column stays NULL (no referent), the protocol
    -- statement is "nothing precedes me", and a bare Turtle integer is
    -- xsd:integer, matching the declared datatype.
    COALESCE(v_prev, 0)::text, to_char(v_now,'YYYY-MM-DD"T"HH24:MI:SS"Z"'));
  IF NOT ckp.validate(v_led_ttl, v_core) THEN
    RAISE EXCEPTION 'ckp.seal: ledger entry fails ckp:LedgerEntryShape (core governance)';
  END IF;
  INSERT INTO ckp.ledger(instance_id, body_sha256, sig, prev_seq)
  VALUES (p_instance_id, v_sha, v_sig, v_prev);

  -- 4. VALIDATE the protocol's OWN proof op, then write it.
  v_prf_ttl := format($t$
    @prefix ckp: <https://conceptkernel.org/ontology/v3.11/core#> .
    @prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
    <urn:ckp:prf:%s> a ckp:Proof ;
      ckp:about <%s> ; ckp:method "hmac+sha256" ; ckp:digest "%s" ;
      ckp:verifiedAt "%s"^^xsd:dateTime .$t$,
    p_instance_id, p_instance_id, v_sha, to_char(v_now,'YYYY-MM-DD"T"HH24:MI:SS"Z"'));
  IF NOT ckp.validate(v_prf_ttl, v_core) THEN
    RAISE EXCEPTION 'ckp.seal: proof fails ckp:ProofShape (core governance)';
  END IF;
  INSERT INTO ckp.proof(about, method, digest) VALUES (p_instance_id,'hmac+sha256',v_sha);

  -- 4b. APPEND one proof per SATISFIED obligation (0.4.65, §5b) — same digest,
  -- method naming the agreement ('obligation:<name>'). ckp.proof's absent
  -- uniqueness is the placed joint this stands on: the hmac row proves the
  -- bytes, each obligation row proves one agreed check held when they sealed.
  -- Validated against ckp:ProofShape like the hmac row — the protocol's own
  -- ops pass their own gate or nothing does.
  FOR v_ob IN SELECT jsonb_array_elements_text(COALESCE(v_oblig->'satisfied','[]'::jsonb))
  LOOP
    v_prf_ttl := format($t$
      @prefix ckp: <https://conceptkernel.org/ontology/v3.11/core#> .
      @prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
      <urn:ckp:prf:%s:%s> a ckp:Proof ;
        ckp:about <%s> ; ckp:method "obligation:%s" ; ckp:digest "%s" ;
        ckp:verifiedAt "%s"^^xsd:dateTime .$t$,
      p_instance_id, v_ob, p_instance_id, v_ob, v_sha, to_char(v_now,'YYYY-MM-DD"T"HH24:MI:SS"Z"'));
    IF NOT ckp.validate(v_prf_ttl, v_core) THEN
      RAISE EXCEPTION 'ckp.seal: obligation proof % fails ckp:ProofShape (core governance)', v_ob;
    END IF;
    INSERT INTO ckp.proof(about, method, digest) VALUES (p_instance_id, 'obligation:'||v_ob, v_sha);
  END LOOP;

  -- 4c. IDENTITY EVIDENCE (0.4.70) — the sealed half of the fleet identity
  -- contract (pgRDF operation-1786906298085342000, confirmed by pgck in
  -- operation-1786897156122855000). Two GUCs, relay-set on the channel clients
  -- cannot write, land as proof rows so verified-at-time becomes SEALABLE
  -- EVIDENCE riding the ledger into every future epoch, instead of the
  -- substrate's unrecorded word. The attach list is CLOSED at these two:
  -- anything beyond them is argued for on the wire, never slipped in.
  --
  --   token-residue   digest = the claims fingerprint itself (iss/kid/sub/exp
  --                   hash, 64-hex). NEVER the token: a raw JWT (eyJ…) fails
  --                   the pattern and REFUSES the seal — the never-the-token
  --                   rule is structural, not conventional. Absent GUC = no
  --                   row = honestly unattested (tests, raw plane).
  --   grant-ref       the acting voted Grant's URN rides in the METHOD
  --                   ('grant-ref:<urn>'), readable for resolve-never-believe
  --                   custody (pgRDF#122); digest = v_sha, consistent with
  --                   obligation rows (evidence about THIS sealed body).
  v_res := NULLIF(trim(COALESCE(current_setting('ckp.token_residue', true), '')), '');
  IF v_res IS NOT NULL THEN
    IF v_res !~ '^[0-9a-f]{64}$' THEN
      RAISE EXCEPTION 'ckp.seal: ckp.token_residue must be a 64-hex claims fingerprint (sha256 over iss/kid/sub/exp), NEVER the token itself — bearer tokens replay, and a raw credential in the evidence plane is permanent. Got a value of length %.', length(v_res);
    END IF;
    v_prf_ttl := format($t$
      @prefix ckp: <https://conceptkernel.org/ontology/v3.11/core#> .
      @prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
      <urn:ckp:prf:%s:tr> a ckp:Proof ;
        ckp:about <%s> ; ckp:method "token-residue" ; ckp:digest "%s" ;
        ckp:verifiedAt "%s"^^xsd:dateTime .$t$,
      p_instance_id, p_instance_id, v_res, to_char(v_now,'YYYY-MM-DD"T"HH24:MI:SS"Z"'));
    IF NOT ckp.validate(v_prf_ttl, v_core) THEN
      RAISE EXCEPTION 'ckp.seal: token-residue proof fails ckp:ProofShape (core governance)';
    END IF;
    INSERT INTO ckp.proof(about, method, digest) VALUES (p_instance_id, 'token-residue', v_res);
  END IF;
  v_gref := NULLIF(trim(COALESCE(current_setting('ckp.grant_ref', true), '')), '');
  IF v_gref IS NOT NULL THEN
    IF v_gref !~ '^[A-Za-z][A-Za-z0-9+.:#/_-]*$' THEN
      RAISE EXCEPTION 'ckp.seal: ckp.grant_ref must be the acting Grant''s URN/IRI, got %', v_gref;
    END IF;
    -- the URN character gate above makes this string build injection-safe.
    v_prf_ttl := format($t$
      @prefix ckp: <https://conceptkernel.org/ontology/v3.11/core#> .
      @prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
      <urn:ckp:prf:%s:gr> a ckp:Proof ;
        ckp:about <%s> ; ckp:method "grant-ref:%s" ; ckp:digest "%s" ;
        ckp:verifiedAt "%s"^^xsd:dateTime .$t$,
      p_instance_id, p_instance_id, v_gref, v_sha, to_char(v_now,'YYYY-MM-DD"T"HH24:MI:SS"Z"'));
    IF NOT ckp.validate(v_prf_ttl, v_core) THEN
      RAISE EXCEPTION 'ckp.seal: grant-ref proof fails ckp:ProofShape (core governance)';
    END IF;
    INSERT INTO ckp.proof(about, method, digest) VALUES (p_instance_id, 'grant-ref:'||v_gref, v_sha);
  END IF;

  -- 5. PROJECT link triples for Task/Goal instances into the project board graph (CKB-5).
  PERFORM ckp.project_links(v_project, p_instance_id, p_body);

  -- 6. PROJECT THE SPINE (0.4.59, pgRDF §4.4): the sealed body — stamps included,
  -- since they merged at step 2 — becomes quads in <project>/instances, so the
  -- fence census and every oracle signal are SPARQL, adoptable by any kernel.
  PERFORM ckp._project_instance_spine(p_instance_id, p_body, v_project);

  RETURN v_sha;
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp.set_materialize_policy(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  v_trigger text := p_payload->>'trigger';
  v_profile text := p_payload->>'profile';
BEGIN
  IF v_trigger IS NULL OR v_trigger NOT IN ('batch','on_seal','governance-manual') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_trigger', 'trigger', v_trigger);
  END IF;
  IF v_profile IS NULL OR v_profile NOT IN ('rdfs','owl-rl') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_profile', 'profile', v_profile);
  END IF;
  INSERT INTO ckp.config(k,v) VALUES ('materialize_trigger', v_trigger) ON CONFLICT (k) DO UPDATE SET v=EXCLUDED.v;
  INSERT INTO ckp.config(k,v) VALUES ('materialize_profile', v_profile) ON CONFLICT (k) DO UPDATE SET v=EXCLUDED.v;
  RETURN jsonb_build_object('ok', true, 'trigger', v_trigger, 'profile', v_profile);
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp.shapes_self_test(p_project text)
 RETURNS TABLE(shape_class text, target_class text, present boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  v_comp_iri text := format('urn:ckp:%s/shapes/composed', p_project);
  v_iri      text;
  v_row      record;
  v_n        int := 0;
BEGIN
  -- Prefer the project's composed surface; fall back to the ε0 core so a
  -- project that has not composed yet is still checked for vacuity.
  v_iri := CASE WHEN pgrdf.graph_id(v_comp_iri) IS NOT NULL
                THEN v_comp_iri ELSE 'urn:ckp:core' END;

  FOR v_row IN
    SELECT j->>'s' AS s, j->>'tc' AS tc
    FROM pgrdf.sparql(format(
      'PREFIX sh: <http://www.w3.org/ns/shacl#>
       PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
       SELECT ?s ?tc FROM <%s>
       WHERE { ?s rdf:type sh:NodeShape ; sh:targetClass ?tc }', v_iri)) j
  LOOP
    shape_class  := v_row.s;
    target_class := v_row.tc;
    present      := true;
    v_n := v_n + 1;
    RETURN NEXT;
  END LOOP;

  IF v_n = 0 THEN
    RAISE EXCEPTION
      'ckp.shapes_self_test: % targets NO class — the surface is VACUOUS. '
      'A validation against it would report conforms:true having evaluated '
      'nothing. Check the ontology mount and that ckp.boot() ran.', v_iri;
  END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION ckp.snapshot(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE v_req text := p_payload->>'requester'; v_rows jsonb;
BEGIN
  -- F-E: a bulk replay requires an explicit grant on the requester.
  IF v_req IS NULL OR NOT ckp.has_grant(v_req, 'snapshot') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'snapshot_not_granted', 'requester', v_req);
  END IF;
  SELECT jsonb_agg(jsonb_build_object('id', id, 'type', body->>'type') ORDER BY id) INTO v_rows FROM ckp.instances;
  RETURN jsonb_build_object('ok', true, 'requester', v_req,
                            'count', COALESCE(jsonb_array_length(v_rows), 0),
                            'instances', COALESCE(v_rows, '[]'::jsonb));
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp.stage_ttl(p_ttl text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  v_iri       text := 'urn:ckp:stage:'||pg_backend_pid();
  v_scratch   int;
  v_quads     bigint;
  v_forbidden jsonb;
BEGIN
  -- 1. STAGE — parse the caller's TTL via the engine into a scratch graph. Never concatenated
  --    into SQL; a malformed payload fails in the parser, not in our code.
  v_scratch := pgrdf.add_graph(v_iri);   -- get-or-create BY IRI (stable id; no fixed-id collision)
  PERFORM pgrdf.clear_graph(v_scratch);
  BEGIN
    v_quads := pgrdf.parse_turtle(p_ttl, v_scratch, 'urn:ckp:stage#');
  EXCEPTION WHEN OTHERS THEN
    PERFORM pgrdf.clear_graph(v_scratch);
    RETURN jsonb_build_object('ok', false, 'error', 'parse_error', 'detail', SQLERRM);
  END;

  -- 2. META-FENCE — admit only ontology-meta predicates (rdf/rdfs/owl/sh). Any other predicate
  --    (instance data uses ckp:* data predicates; foreign triples use other namespaces) is a
  --    fence violation. The caller may EXTEND the type ontology, never inject data.
  SELECT jsonb_agg(DISTINCT j->>'p') INTO v_forbidden
  FROM pgrdf.sparql(format($q$
    SELECT ?p WHERE { GRAPH <%s> { ?s ?p ?o }
      FILTER( !STRSTARTS(STR(?p), "http://www.w3.org/1999/02/22-rdf-syntax-ns#")
           && !STRSTARTS(STR(?p), "http://www.w3.org/2000/01/rdf-schema#")
           && !STRSTARTS(STR(?p), "http://www.w3.org/2002/07/owl#")
           && !STRSTARTS(STR(?p), "http://www.w3.org/ns/shacl#") ) }
  $q$, v_iri)) j;

  PERFORM pgrdf.clear_graph(v_scratch);

  IF v_forbidden IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'fence_violation',
                              'forbidden_predicates', v_forbidden, 'staged_quads', v_quads);
  END IF;
  RETURN jsonb_build_object('ok', true, 'staged_quads', v_quads, 'fenced', 'ontology-meta-only');
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp.transition(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  C        text := 'https://conceptkernel.org/ontology/v3.11/core#';
  N        text := 'urn:ckp:board/';
  v_id     text := p_payload->>'id';
  v_to     text := p_payload->>'to_state';
  v_state_re text := '^[A-Za-z][A-Za-z0-9_-]*$';
  v_body   jsonb; v_from text; v_type text; v_allowed jsonb; v_has_map boolean; v_src text;
BEGIN
  IF v_to IS NULL OR v_to !~ v_state_re THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_to_state', 'to_state', v_to);
  END IF;
  SELECT body INTO v_body FROM ckp.instances WHERE id = v_id;
  IF v_body IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'unknown_instance', 'id', v_id);
  END IF;
  v_type := v_body->>'type';
  v_from := COALESCE(v_body->>(N||'lifecycle_state'), v_body->>'state', v_body->>(C||'lifecycle_state'), 'planned');

  -- T3 (v0.4.20, pgCK#7): does the instance's TYPE carry a sealed transition map in ANY kernel
  -- graph? Resolve project-independently — ckp:allowsTransition only exists in kernel graphs.
  v_has_map := (v_type IS NOT NULL AND v_type ~ '^[A-Za-z]' AND EXISTS (
    SELECT 1 FROM pgrdf.sparql(format($q$
      PREFIX ckp: <%s>
      SELECT ?t WHERE { GRAPH ?g { <%s> ckp:allowsTransition ?t } } LIMIT 1
    $q$, C, v_type)) j));

  IF v_has_map THEN
    -- the type's sealed map governs (wherever it lives). from must be a safe state to bind.
    v_src := 'kernel';
    IF v_from !~ v_state_re OR NOT EXISTS (
      SELECT 1 FROM pgrdf.sparql(format($q$
        PREFIX ckp: <%s>
        SELECT ?t WHERE { GRAPH ?g {
          <%s> ckp:allowsTransition ?t . ?t ckp:fromState "%s" ; ckp:toState "%s" } }
      $q$, C, v_type, v_from, v_to)) j) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'invalid_transition',
                                'from', v_from, 'to', v_to, 'source', v_src);
    END IF;
  ELSE
    -- fallback: the global config map (back-compat).
    v_src := 'config';
    v_allowed := (SELECT v::jsonb FROM ckp.config WHERE k='transition_map')->v_from;
    IF v_allowed IS NULL OR NOT EXISTS (SELECT 1 FROM jsonb_array_elements_text(v_allowed) e WHERE e = v_to) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'invalid_transition',
                                'from', v_from, 'to', v_to, 'allowed', v_allowed, 'source', v_src);
    END IF;
  END IF;

  v_body := v_body || jsonb_build_object(N||'lifecycle_state', v_to, 'state', v_to);
  -- 0.4.57 — THE RE-SEAL IS JUDGED BY THE KERNEL THAT PRODUCED THE FACT, never
  -- by the ambient session project. This sealed under _project(), so an
  -- instance produced by demo, transitioned from a session whose GUC named a
  -- different kernel, was re-validated against a FOREIGN surface — an M2
  -- violation (jurisdiction: whose meaning governs it). Invisible while the
  -- type gate was fleet-wide; the moment the gate was scoped (0.4.51), s56
  -- refused exactly this, which is that test doing its job one layer deeper
  -- than it was written for. The map lookup above was already
  -- project-independent; the re-seal now follows the same rule: derive the
  -- project from the substrate-stamped producedBy (unforgeable), fall back to
  -- the session only for pre-stamp rows.
  DECLARE
    v_pb   text := v_body->>(C||'producedBy');
    v_proj text;
  BEGIN
    IF v_pb IS NOT NULL AND v_pb ~ '^urn:ckp:.+/kernel/ck$' THEN
      v_proj := regexp_replace(v_pb, '^urn:ckp:(.+)/kernel/ck$', '\1');
      PERFORM set_config('ckp.project', v_proj, true);
    END IF;
    PERFORM ckp.seal(v_id, v_body);
  END;
  RETURN jsonb_build_object('ok', true, 'id', v_id, 'from', v_from, 'to', v_to,
                            'source', v_src, 'verified', ckp.verify(v_id));
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp.update_typed(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  v_id      text := p_payload->>'id';
  v_patch   jsonb := p_payload->'patch';
  v_proj    text := ckp._project();
  v_cur     jsonb;
  v_type    text;
  v_ns      text;
  v_propmap jsonb;
  v_shaped  boolean;
  v_key     text;
  v_val     jsonb;
  v_keyiri  text;
BEGIN
  IF v_id IS NULL OR btrim(v_id) = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'id_required'); END IF;
  IF v_patch IS NULL OR jsonb_typeof(v_patch) <> 'object' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_patch', 'hint', 'instance.update generic form needs a {patch:{…}} object'); END IF;
  SELECT body INTO v_cur FROM ckp.instances WHERE id = v_id;
  IF v_cur IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'unknown_instance', 'id', v_id); END IF;

  v_type := v_cur->>'type';
  v_ns   := CASE WHEN v_type ~ '[/#]' THEN regexp_replace(v_type, '[^/#]*$', '') ELSE '' END;

  -- declared property map for the instance's type (same read as create_typed).
  -- 0.4.51: composed-aware, because a patch is a WRITE and must resolve keys the
  -- same way the gate will judge them. Refusing an undeclared patch key earlier,
  -- with the declared set named, is strictly better than sealing it under the
  -- type's namespace and letting the gate refuse the whole body.
  v_propmap := ckp._propmap(v_type, v_proj);
  v_shaped := (v_propmap <> '{}'::jsonb);

  v_cur := v_cur - 'participant';   -- re-resolved by ckp.seal from any supplied claims

  FOR v_key, v_val IN SELECT key, value FROM jsonb_each(v_patch)
  LOOP
    CONTINUE WHEN v_key IN ('id', 'type', '@id');   -- not patchable via this path
    IF position(':' in v_key) > 0 THEN
      v_keyiri := v_key;                                    -- already a full IRI
    ELSIF v_shaped THEN
      IF v_propmap ? v_key THEN
        v_keyiri := v_propmap->>v_key;                      -- declared localname -> IRI
      ELSE
        RETURN jsonb_build_object('ok', false, 'error', 'undeclared_patch_key',
                                  'key', v_key, 'type', v_type,
                                  'declared', (SELECT jsonb_agg(k) FROM jsonb_object_keys(v_propmap) k));
      END IF;
    ELSE
      v_keyiri := v_ns || v_key;                            -- unshaped: namespace under the type's NS
    END IF;
    v_cur := v_cur || jsonb_build_object(v_keyiri, v_val);  -- `->` value: preserves number/bool/object
  END LOOP;

  -- re-seal: the required-props gate re-validates the patched body.
  PERFORM ckp.seal(v_id, v_cur);
  RETURN jsonb_build_object('ok', true, 'id', v_id, 'verified', ckp.verify(v_id),
    'proof_digest', (SELECT digest FROM ckp.proof WHERE about = v_id ORDER BY id DESC LIMIT 1))
    || CASE WHEN NULLIF(current_setting('ckp.last_warnings', true), '') IS NOT NULL
            THEN jsonb_build_object('warnings', current_setting('ckp.last_warnings', true)::jsonb)
            ELSE '{}'::jsonb END;
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('ok', false, 'error', SQLERRM);
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp.urn_normalise(p_raw text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
  SELECT regexp_replace(lower(trim(coalesce(p_raw, ''))), '[^a-z0-9-]+', '-', 'g');
$function$
;

CREATE OR REPLACE FUNCTION ckp.validate(ttl text, shapes_graph_id integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  -- The scratch graph is allocated BY IRI, never computed as
  -- 1000000000 + pg_backend_pid(). That arithmetic lands inside the very band
  -- pgrdf allocates data graphs from: on the bench 59 live graphs sat at
  -- offsets 112..1637 -- ordinary container pids -- with the core ontology
  -- itself at 1000000221. A backend that drew a colliding pid aimed
  -- clear_graph at real data, and every seal in that session refused with a
  -- shape error that had nothing to do with the payload. Only pgrdf's
  -- "bound to a different IRI" check stood between this and deleting core.
  -- add_graph(iri) is idempotent and returns the id, so the scratch stays
  -- one-per-backend and can never alias a data graph.
  scratch_id BIGINT := pgrdf.add_graph('urn:ckp:validate-scratch:'||pg_backend_pid());
  report jsonb;
BEGIN
  -- Bench-proven form (reconciled from pgck.localhost, 2026-08-08): the graph
  -- is materialized BEFORE validation. pgrdf.validate does not entail and
  -- entailment is per-graph, so without this the candidate's rdf:type closure
  -- is invisible to targetClass resolution and a malformed entry can conform
  -- vacuously — the PASS-10/PASS-17 failure shape, at the innermost gate.
  PERFORM pgrdf.clear_graph(scratch_id);
  PERFORM pgrdf.parse_turtle(ttl, scratch_id, 'urn:ckp:scratch#');
  PERFORM pgrdf.materialize(scratch_id);
  report := pgrdf.validate(scratch_id, shapes_graph_id);
  PERFORM pgrdf.clear_graph(scratch_id);
  RETURN COALESCE((report->>'conforms')::boolean, false);
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp.validate_instance(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  v_body    jsonb := COALESCE(p_payload->'body', p_payload);
  v_type    text := v_body->>'type';
  v_proj    text := ckp._project();
  v_subj    text := 'urn:ckp:validate:'||pg_backend_pid();
  v_ns      text;
  v_propmap jsonb;
  v_resolved jsonb;
  v_key text; v_val jsonb; v_kiri text;
  v_scratch bigint;
  v_comp    int;
  v_ttl     text;
  v_report  jsonb;
BEGIN
  IF v_type IS NULL THEN
    -- 0.4.51 — the payload IS read as COALESCE(p_payload->'body', p_payload), so
    -- flat {type, …} and nested {body:{type, …}} both work and
    -- {type, body:{…}} is the ONE shape that cannot: the type sits outside the
    -- body this descends into. Saying "type_required" there names the single
    -- field the caller DID supply, and the caller re-sends it. Distinguish.
    IF p_payload ? '@type' OR p_payload ? 'type'
       OR (jsonb_typeof(p_payload->'body') = 'object' AND ((p_payload->'body') ? '@type')) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'type_not_readable_here',
        'hint', 'a type WAS supplied, in a position this verb does not read. Accepted: FLAT {"type": "<class IRI>", "<prop>": …}, or nested {"body": {"type": …, "<prop>": …}}. NOT accepted: @type (never read), or {"type": …, "body": {…}} — that puts the type outside the body this verb descends into.');
    END IF;
    RETURN jsonb_build_object('ok', false, 'error', 'type_required',
      'hint', 'the payload is flat: {"type": "<class IRI>", "<prop>": …}');
  END IF;

  -- P0-D mechanism 2 parity (pgCK#27): validate PREDICTS seal. seal refuses an
  -- undeclared type before the SHACL gate; validate must report the same, or
  -- validate <=> seal is a slogan. An undeclared type reports conforms=false
  -- with a violation naming it — never the vacuous conforms=true that let
  -- invented types look valid.
  v_comp := ckp._composed_shapes(v_proj);
  BEGIN
    IF NOT ckp._type_admitted(v_type, v_proj, v_comp) THEN
      RETURN jsonb_build_object('ok', true, 'type', v_type, 'conforms', false,
        'violations', jsonb_build_array(jsonb_build_object(
          'focusNode', v_type, 'resultMessage', 'type is not admitted — no shape targets it and it is declared by no class',
          'sourceConstraintComponent', 'ckp:AdmittedTypeConstraint')),
        'report', jsonb_build_object('conforms', false));
    END IF;
  END;

  -- Resolve the body's short keys to declared property IRIs (mirror ckp.create_typed) so validate
  -- accepts the same {type, …fields} shape as instance.create. Already-IRI keys pass through.
  v_ns := CASE WHEN v_type ~ '[/#]' THEN regexp_replace(v_type, '[^/#]*$', '') ELSE '' END;
  -- 0.4.51: the SAME map create_typed uses. This read composed while create read
  -- the kernel graph — validate ⟺ seal broken one layer below the gate.
  v_propmap := ckp._propmap(v_type, v_proj);
  v_resolved := jsonb_build_object('type', v_type);
  FOR v_key, v_val IN SELECT key, value FROM jsonb_each(v_body) LOOP
    CONTINUE WHEN v_key IN ('type', '@id', 'sub');
    IF position(':' in v_key) > 0 THEN v_kiri := v_key;
    ELSIF v_propmap ? v_key THEN v_kiri := v_propmap->>v_key;
    ELSE v_kiri := v_ns || v_key; END IF;
    v_resolved := v_resolved || jsonb_build_object(v_kiri, v_val);
  END LOOP;

  -- project the resolved candidate body to RDF in a scratch graph.
  -- 0.4.62 — THE DRY-RUN CANDIDATE IS THE SEAL'S CANDIDATE, all three parts.
  -- This serialized the body alone, so every requirement arriving by PARENT
  -- CLOSURE was invisible: wave:Pass receives EpochShape via wave:Pass ⊑
  -- ckp:Epoch, so epoch and surfaceDigest are demanded at seal — and this
  -- dry-run said conforms:true to a body missing both (ck-dev's escalation
  -- operation-1786642612862085000, reproduced here on 0.4.61 before fixing).
  -- Same root as the 0.4.60 propmap fix, one layer over: ancestors resolved in
  -- the property MAP but never STAMPED on the dry-run candidate. The derived
  -- stamps join too, exactly as seal composes them, so InstanceShape's
  -- requirements are previewed rather than falsely refused.
  v_ttl := ckp._body_to_ttl(v_resolved, v_subj, v_comp)
        || ckp._parent_closure_ttl(v_type, v_subj, v_comp)
        || ckp._stamps_to_ttl(v_subj, ckp._derived_stamps(v_subj, v_type, v_proj,
             NULLIF(trim(COALESCE(current_setting('ckp.requester', true), '')), ''), v_comp));
  v_scratch := pgrdf.add_graph('urn:ckp:validate:'||pg_backend_pid());
  PERFORM pgrdf.clear_graph(v_scratch);
  BEGIN
    PERFORM pgrdf.parse_turtle(v_ttl, v_scratch, 'urn:ckp:validate#');
  EXCEPTION WHEN OTHERS THEN
    PERFORM pgrdf.clear_graph(v_scratch);
    RETURN jsonb_build_object('ok', false, 'error', 'project_error', 'detail', SQLERRM);
  END;

  -- Full native W3C SHACL Core report against the COMPOSED SURFACE -- the graph
  -- ckp.seal actually gates on. This validated against <urn:ckp:%s/kernel/ck>,
  -- which holds a Kernel and three organs and NO shapes: measured on the bench,
  -- 30 triples and 0 sh:targetClass, versus a composed surface of 1258 triples
  -- and 27 targets. Nothing could ever be selected, and the only thing standing
  -- between that and a vacuous conforms:true is the no-target guard.
  -- "validate PREDICTS seal" (pgCK#27) was a slogan on all three axes -- shapes
  -- graph, property map, serializer overload. All three now match seal.
  v_report := pgrdf.validate(v_scratch, v_comp, 'native');
  PERFORM pgrdf.clear_graph(v_scratch);

  -- 0.4.72 — SEVERITY PARITY (validate ⟺ seal, fourth axis). The seal now
  -- refuses on Violations only and surfaces Warnings; a dry-run that reported
  -- conforms=false for a warnings-only body would predict a refusal the seal
  -- does not make — the exact split class this function exists to prevent.
  -- Partition identically: `conforms` reflects Violations; `warnings` carries
  -- the guidance band.
  DECLARE v_viol jsonb; v_warn jsonb;
  BEGIN
    SELECT COALESCE(jsonb_agg(r) FILTER (WHERE r->>'resultSeverity' IS DISTINCT FROM 'sh:Warning'
                                           AND r->>'resultSeverity' IS DISTINCT FROM 'sh:Info'), '[]'::jsonb),
           COALESCE(jsonb_agg(r) FILTER (WHERE r->>'resultSeverity' IN ('sh:Warning','sh:Info')), '[]'::jsonb)
      INTO v_viol, v_warn
      FROM jsonb_array_elements(COALESCE(v_report->'results', '[]'::jsonb)) r;
    RETURN jsonb_build_object('ok', true, 'type', v_type,
      'conforms',   (jsonb_array_length(v_viol) = 0),
      'violations', v_viol,
      'warnings',   v_warn,
      'report',     v_report);
  END;
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp.validate_report(p_ttl text, p_shapes_graph integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  v_iri     text := 'urn:ckp:vreport-scratch:'||pg_backend_pid();
  v_scratch integer;
  v_report  jsonb;
BEGIN
  v_scratch := pgrdf.add_graph(v_iri);   -- get-or-create BY IRI (the stage_ttl fix, applied here)
  PERFORM pgrdf.clear_graph(v_scratch);
  PERFORM pgrdf.parse_turtle(p_ttl, v_scratch, 'urn:ckp:vreport#');
  v_report := ckp._validate(v_scratch, p_shapes_graph);   -- Ring-1: full sh:ValidationReport
  PERFORM pgrdf.clear_graph(v_scratch);
  RETURN jsonb_build_object(
    'conforms',   COALESCE((v_report->>'conforms')::boolean, false),
    'violations', COALESCE(v_report->'results', '[]'::jsonb));
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp.validation_report_ttl(p_report jsonb, p_subj text DEFAULT 'urn:ckp:report:1'::text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE v_ttl text; v jsonb; i int := 0; r text;
BEGIN
  v_ttl := '@prefix sh: <http://www.w3.org/ns/shacl#> .'||chr(10)
        || '@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .'||chr(10)
        || '<'||p_subj||'> a sh:ValidationReport ; sh:conforms '
        || CASE WHEN (p_report->>'conforms')='true' THEN '"true"' ELSE '"false"' END
        || '^^xsd:boolean .'||chr(10);
  FOR v IN SELECT * FROM jsonb_array_elements(COALESCE(p_report->'results','[]'::jsonb))
  LOOP
    i := i + 1;
    r := p_subj||':r'||i;
    v_ttl := v_ttl
      || '<'||p_subj||'> sh:result <'||r||'> .'||chr(10)
      || '<'||r||'> a sh:ValidationResult ;'||chr(10)
      || '  sh:resultSeverity sh:Violation ;'||chr(10)
      || '  sh:sourceConstraintComponent <'||(v->>'sourceConstraintComponent')||'> '
      || CASE WHEN v->>'focusNode' IS NOT NULL
              THEN ';'||chr(10)||'  sh:focusNode <'||(v->>'focusNode')||'> ' ELSE '' END
      || CASE WHEN v->>'resultPath' IS NOT NULL
              THEN ';'||chr(10)||'  sh:resultPath <'||(v->>'resultPath')||'> ' ELSE '' END
      || CASE WHEN v->>'resultMessage' IS NOT NULL
              THEN ';'||chr(10)||'  sh:resultMessage "'
                   ||replace(replace(v->>'resultMessage','\','\\'),'"','\"')||'" ' ELSE '' END
      || '.'||chr(10);
  END LOOP;
  RETURN v_ttl;
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp.verb_canon(p_verb text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
  SELECT CASE p_verb
    WHEN 'task.create'     THEN 'instance.create'
    WHEN 'kernel.create'   THEN 'instance.create'   -- CK.Lib.Js fix: instance, not propose
    WHEN 'edge.create'     THEN 'instance.link'
    WHEN 'task.update'     THEN 'instance.update'
    WHEN 'instances.list'  THEN 'instance.query'
    WHEN 'instances.last'  THEN 'instance.query'
    WHEN 'instances.count' THEN 'instance.query'
    WHEN 'snapshot.board'  THEN 'instance.snapshot'
    WHEN 'snapshot.bodies' THEN 'instance.snapshot'
    WHEN 'provenance'      THEN 'instance.provenance'
    ELSE p_verb   -- instance.* / kernel.* / participant.join / affordances / kernels.list pass through
  END;
$function$
;

CREATE OR REPLACE FUNCTION ckp.verb_to_legacy(p_verb text, p_payload jsonb)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
  SELECT CASE p_verb
    WHEN 'instance.create' THEN
      CASE WHEN p_payload ? 'task' THEN 'task.create'
           WHEN p_payload ? 'name' THEN 'kernel.create'
           ELSE 'task.create' END
    WHEN 'instance.update'     THEN 'task.update'
    WHEN 'instance.link'       THEN 'edge.create'
    WHEN 'instance.snapshot'   THEN 'snapshot.board'
    WHEN 'instance.query'      THEN 'instances.list'
    WHEN 'instance.provenance' THEN 'provenance'
    ELSE p_verb   -- legacy names + instance.get / instance.verify pass straight through
  END;
$function$
;

CREATE OR REPLACE FUNCTION ckp.verify(p_instance_id text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  v_body JSONB;
  v_identity_key TEXT := COALESCE(
    NULLIF(current_setting('ckp.identity_key', true), ''),
    (SELECT v FROM ckp.config WHERE k='identity_key')
  );
  v_recompute TEXT;
  v_ledger_seq BIGINT;
  v_ledger_sha TEXT;
  v_ledger_sig TEXT;
  v_prev_seq BIGINT;
  v_expected_prev BIGINT;
  v_proof_method TEXT;
  v_proof_digest TEXT;
  v_expected_sig TEXT;
BEGIN
  IF v_identity_key IS NULL OR v_identity_key = '' THEN
    RETURN false;
  END IF;

  SELECT body INTO v_body FROM ckp.instances WHERE id = p_instance_id;
  IF v_body IS NULL THEN
    RETURN false;
  END IF;

  SELECT seq, body_sha256, sig, prev_seq
  INTO v_ledger_seq, v_ledger_sha, v_ledger_sig, v_prev_seq
  FROM ckp.ledger
  WHERE instance_id = p_instance_id
  ORDER BY seq DESC
  LIMIT 1;

  -- 0.4.66 — VERIFY THE BYTE-PROOF, BY NAME. This took the LAST proof row and
  -- demanded it be hmac+sha256 — true exactly as long as ckp.proof held one row
  -- per fact. 0.4.65's obligations made proofs PLURAL (that was the point), the
  -- obligation row lands after the hmac row, and the first obligation-guarded
  -- fact on the bench (pass-1786830306955914000) verified FALSE seconds after
  -- sealing cleanly. The writer moved and this reader did not — caught by the
  -- mechanism's own debut, the day it shipped. The byte-proof is selected by
  -- METHOD now; obligation rows are attestations of agreed checks, never
  -- substitutes for the bytes.
  SELECT method, digest
  INTO v_proof_method, v_proof_digest
  FROM ckp.proof
  WHERE about = p_instance_id AND method = 'hmac+sha256'
  ORDER BY id DESC
  LIMIT 1;

  IF v_ledger_seq IS NULL
     OR v_ledger_sha IS NULL
     OR v_ledger_sig IS NULL
     OR v_proof_method IS NULL
     OR v_proof_digest IS NULL THEN
    RETURN false;
  END IF;

  v_recompute := encode(digest(convert_to(v_body::text,'UTF8'),'sha256'),'hex');
  v_expected_sig := encode(hmac(v_recompute, v_identity_key, 'sha256'),'hex');
  SELECT max(seq) INTO v_expected_prev FROM ckp.ledger WHERE seq < v_ledger_seq;

  RETURN v_prev_seq IS NOT DISTINCT FROM v_expected_prev
     AND v_proof_method = 'hmac+sha256'
     AND v_recompute = v_ledger_sha
     AND v_ledger_sha = v_proof_digest
     AND v_ledger_sig = v_expected_sig;
END;
$function$
;

CREATE OR REPLACE FUNCTION ckp.vote(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ckp', 'public', 'pg_temp'
AS $function$
DECLARE
  C           text := 'https://conceptkernel.org/ontology/v3.11/core#';
  v_core      int  := (SELECT v::int FROM ckp.config WHERE k='core_graph_id');
  v_about     text := p_payload->>'about';   -- the Proposal @id (IRI)
  -- VoteShape declares ckp:voteValue; this read only 'value', so a caller using
  -- the declared name got invalid_vote_value. Accept both.
  v_value     text := COALESCE(p_payload->>'value', p_payload->>'voteValue');
  v_prop      jsonb;
  v_quorum    int;
  v_approvals int;
  v_vid       text;
  v_body      jsonb;
  v_ttl       text;
  v_report    jsonb;
BEGIN
  -- 1. injection-safe field gate (mirrors VoteShape).
  IF v_value IS NULL OR v_value NOT IN ('approve','reject') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_vote_value', 'value', v_value);
  END IF;
  IF v_about IS NULL OR v_about !~ '^[A-Za-z][A-Za-z0-9+.:#/_-]*$' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_about', 'about', v_about);
  END IF;

  -- 2. the Proposal must exist and still be pending.
  SELECT body INTO v_prop FROM ckp.instances
    WHERE body->>'@id' = v_about AND body->>'type' = C||'Proposal';
  IF v_prop IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'unknown_proposal', 'about', v_about);
  END IF;
  IF v_prop->>(C||'proposalState') <> 'pending' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'proposal_not_pending',
                              'state', v_prop->>(C||'proposalState'));
  END IF;
  v_quorum := COALESCE((v_prop->>(C||'requiresQuorum'))::int, 1);

  v_vid := 'vote-'||(extract(epoch from clock_timestamp())*1e9)::bigint::text;

  -- 3. authoritative SHACL gate (VoteShape) — values field-validated, so the TTL is safe.
  v_ttl := '@prefix ckp: <'||C||'> .'||chr(10)||
           '<ckp://Vote#'||v_vid||'> a ckp:Vote ; ckp:about <'||v_about||'> ; '||
           'ckp:voteValue "'||v_value||'" .';
  v_report := ckp.validate_report(v_ttl, v_core);
  IF (v_report->>'conforms') IS DISTINCT FROM 'true' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'shape_violation', 'violations', v_report->'violations');
  END IF;

  -- 4. seal the Vote (sealed by the session identity — a human approval is indistinguishable).
  v_body := jsonb_build_object(
    'type',         C||'Vote',
    '@id',          'ckp://Vote#'||v_vid,
    C||'about',     v_about,
    C||'voteValue', v_value
  );
  PERFORM ckp.seal(v_vid, v_body);

  -- 5. quorum: DISTINCT accountable parties (0.4.62) — see ckp.apply for the
  -- mechanism and ck-dev's finding. Votes are not approvals; parties are.
  SELECT count(DISTINCT body->>(C||'createdBy')) INTO v_approvals FROM ckp.instances
    WHERE body->>'type' = C||'Vote'
      AND body->>(C||'about') = v_about
      AND body->>(C||'voteValue') = 'approve'
      AND COALESCE(body->>(C||'createdBy'),'') NOT LIKE 'urn:ckp:participant:anon:%';

  RETURN jsonb_build_object('ok', true, 'vote', v_vid, 'proposal', v_about, 'value', v_value,
                            'approvals', v_approvals, 'quorum', v_quorum,
                            'quorum_met', v_approvals >= v_quorum, 'verified', ckp.verify(v_vid));
END;
$function$
;


